import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, within, waitFor } from "@/test/utils/test-utils";
import { OfferingTypePanel } from "./OfferingTypePanel";
import * as UseMasterDataHooks from "@/hooks/admissions/useMasterData";

// Mock the hooks
vi.mock("@/hooks/admissions/useMasterData", () => ({
  useOfferingTypes: vi.fn(),
  useCreateOfferingType: vi.fn(),
  useUpdateOfferingType: vi.fn(),
  useDeleteOfferingType: vi.fn(),
}));

describe("OfferingTypePanel", () => {
  const mockData = [
    {
      id: 1,
      code: "regular",
      name: "Regular",
      display_order: 1,
      is_active: true,
    },
    {
      id: 2,
      code: "part_time",
      name: "Part-time",
      display_order: 2,
      is_active: true,
    },
  ];

  const mockCreateMutate = vi.fn();
  const mockUpdateMutate = vi.fn();
  const mockDeleteMutate = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    
    (UseMasterDataHooks.useOfferingTypes as any).mockReturnValue({
      data: mockData,
      isLoading: false,
    });
    
    (UseMasterDataHooks.useCreateOfferingType as any).mockReturnValue({
      mutateAsync: mockCreateMutate,
    });
    
    (UseMasterDataHooks.useUpdateOfferingType as any).mockReturnValue({
      mutateAsync: mockUpdateMutate,
    });
    
    (UseMasterDataHooks.useDeleteOfferingType as any).mockReturnValue({
      mutateAsync: mockDeleteMutate,
    });
  });

  it("should render offering types list correctly", () => {
    render(<OfferingTypePanel />);

    expect(screen.getByText("Regular")).toBeInTheDocument();
    expect(screen.getByText("Part-time")).toBeInTheDocument();
    expect(screen.getByText("regular")).toBeInTheDocument(); // Code
    expect(screen.getByText("part_time")).toBeInTheDocument(); // Code
  });

  it("should open create dialog and submit form correctly", async () => {
    render(<OfferingTypePanel />);

    // Click Add New
    const addButton = screen.getByText("Add New");
    fireEvent.click(addButton);

    // Verify Dialog
    const dialog = await screen.findByRole("dialog");
    expect(dialog).toBeInTheDocument();
    expect(screen.getByText("Create Offering Type")).toBeInTheDocument();

    const withinDialog = within(dialog);

    // Fill Form
    const codeInput = withinDialog.getByLabelText(/Code/i);
    const nameInput = withinDialog.getByLabelText(/Name/i);
    
    fireEvent.change(codeInput, { target: { value: "distance" } });
    fireEvent.change(nameInput, { target: { value: "Distance Learning" } });

    // Submit
    const submitButton = withinDialog.getByText("Create");
    fireEvent.click(submitButton);

    // Check Mutation
    await waitFor(() => {
      expect(mockCreateMutate).toHaveBeenCalledWith({
        code: "distance",
        name: "Distance Learning",
        display_order: 3, // Default is length + 1 (2 + 1 = 3)
        is_active: true,
      });
    });
  });

  it("should open edit dialog and populate data correctly", async () => {
    render(<OfferingTypePanel />);

    // Find Edit button for "Regular"
    // Regular is row 1
    const row = screen.getByText("Regular").closest("tr");
    const editButton = row?.querySelector("button"); // First button is Edit
    expect(editButton).toBeInTheDocument();

    fireEvent.click(editButton!);

    // Verify Dialog
    const dialog = await screen.findByRole("dialog");
    expect(dialog).toBeInTheDocument();
    expect(screen.getByText("Edit Offering Type")).toBeInTheDocument();

    const withinDialog = within(dialog);

    // Verify Fields
    const codeInput = withinDialog.getByLabelText(/Code/i) as HTMLInputElement;
    const nameInput = withinDialog.getByLabelText(/Name/i) as HTMLInputElement;

    expect(codeInput.value).toBe("regular");
    expect(codeInput.disabled).toBe(true); // Code is disabled in edit
    expect(nameInput.value).toBe("Regular");
  });

  it("should call delete mutation when delete is confirmed", async () => {
    // Mock window.confirm
    vi.spyOn(window, "confirm").mockImplementation(() => true);

    render(<OfferingTypePanel />);

    // Find Delete button for "Part-time"
    const row = screen.getByText("Part-time").closest("tr");
    const buttons = row?.querySelectorAll("button");
    const deleteButton = buttons?.[1]; // Second button is Delete
    expect(deleteButton).toBeInTheDocument();

    fireEvent.click(deleteButton!);

    // Check Mutation
    expect(window.confirm).toHaveBeenCalled();
    await waitFor(() => {
      expect(mockDeleteMutate).toHaveBeenCalledWith(2); // Part-time ID is 2
    });
  });
});

/**
 * OfferingTypePanel Component
 *
 * Phase 1.2: Offering Type Management
 * CRUD interface for offering types (Regular, Part-time, etc.)
 */

"use client";

import { Layers } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { CRUDTable } from "../shared/CRUDTable";
import {
  useOfferingTypes,
  useCreateOfferingType,
  useUpdateOfferingType,
  useDeleteOfferingType,
} from "@/hooks/admissions/useMasterData";
import type { OfferingType, CRUDTableColumn, BaseFormData } from "../shared/types";

// ============================================
// CONSTANTS
// ============================================

const COLUMNS: CRUDTableColumn<OfferingType>[] = [
  { key: "code", header: "Mã", width: "150px" },
  { key: "name", header: "Tên loại hình" },
  { key: "display_order", header: "Thứ tự", width: "80px" },
  { key: "is_active", header: "Trạng thái", width: "100px" },
];

// ============================================
// COMPONENT
// ============================================

export function OfferingTypePanel() {
  const { data = [], isLoading } = useOfferingTypes();
  const createMutation = useCreateOfferingType();
  const updateMutation = useUpdateOfferingType();
  const deleteMutation = useDeleteOfferingType();

  const handleCreate = async (formData: BaseFormData) => {
    // Transform to match backend ConfigOfferingTypeCreate schema
    const payload = {
      code: formData.code,
      name: formData.name,
      display_order: formData.display_order || 0,
      is_active: formData.is_active !== undefined ? formData.is_active : true,
    };
    await createMutation.mutateAsync(payload as any);
  };

  const handleUpdate = async (id: number, formData: BaseFormData) => {
    // Transform to match backend ConfigOfferingTypeUpdate schema
    const payload = {
      code: formData.code,
      name: formData.name,
      display_order: formData.display_order,
      is_active: formData.is_active,
    };
    await updateMutation.mutateAsync({ id, data: payload as any });
  };

  const handleDelete = async (id: number) => {
    await deleteMutation.mutateAsync(id);
  };

  const renderForm = (
    item: OfferingType | null,
    formData: BaseFormData,
    setFormData: (data: BaseFormData) => void,
    isEdit: boolean
  ) => {
    return (
      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="code">
            Mã loại hình <span className="text-destructive">*</span>
          </Label>
          <Input
            id="code"
            value={formData.code || ""}
            onChange={(e) => setFormData({ ...formData, code: e.target.value })}
            placeholder="ví dụ: chinh_quy, lien_thong, vlvh"
            disabled={isEdit}
            required
          />
          <p className="text-xs text-muted-foreground">
            Mã định danh duy nhất (không thể thay đổi sau khi tạo)
          </p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="name">
            Tên loại hình <span className="text-destructive">*</span>
          </Label>
          <Input
            id="name"
            value={formData.name || ""}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder="ví dụ: Chính quy, Liên thông, Vừa làm vừa học"
            required
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="display_order">Thứ tự hiển thị</Label>
          <Input
            id="display_order"
            type="number"
            value={formData.display_order || 1}
            onChange={(e) =>
              setFormData({ ...formData, display_order: parseInt(e.target.value) })
            }
            min={1}
          />
          <p className="text-xs text-muted-foreground">
            Quy định thứ tự hiển thị trong danh sách và dropdown
          </p>
        </div>
      </div>
    );
  };

  const initialFormData = () => ({
    code: "",
    name: "",
    display_order: data.length + 1,
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Loại hình Đào tạo</h1>
        <p className="text-muted-foreground mt-2">
          Quản lý các loại hình đào tạo (Chính quy, Vừa làm vừa học, Liên thông...)
        </p>
      </div>

      <CRUDTable<OfferingType>
        title="Loại hình"
        description="Các hình thức đào tạo của nhà trường"
        icon={<Layers className="h-5 w-5 text-primary" />}
        columns={COLUMNS}
        data={data}
        isLoading={isLoading}
        onCreate={handleCreate}
        onUpdate={handleUpdate}
        onDelete={handleDelete}
        renderForm={renderForm}
        initialFormData={initialFormData}
      />
    </div>
  );
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, within } from "@/test/utils/test-utils";
import { OrganizationUnitPanel } from "./OrganizationUnitPanel";
import * as UseMasterDataHooks from "@/hooks/admissions/useMasterData";

// Mock the hooks
vi.mock("@/hooks/admissions/useMasterData", () => ({
  useOrganizationUnits: vi.fn(),
  useCreateOrganizationUnit: vi.fn(),
  useUpdateOrganizationUnit: vi.fn(),
  useDeleteOrganizationUnit: vi.fn(),
}));

describe("OrganizationUnitPanel", () => {
  const mockData = [
    {
      id: 1,
      name: "Faculty of IT",
      type: "Khoa",
      parent_id: null,
      is_active: true,
      children: [
        {
          id: 2,
          name: "Software Engineering",
          type: "Bộ môn",
          parent_id: 1,
          is_active: true,
          children: [],
        },
        {
          id: 3,
          name: "Computer Science",
          type: "Bộ môn",
          parent_id: 1,
          is_active: true,
          children: [],
        },
      ],
    },
    {
      id: 4,
      name: "Faculty of Medical",
      type: "Khoa",
      parent_id: null,
      is_active: true,
      children: [],
    },
  ];

  beforeEach(() => {
    vi.clearAllMocks();
    // Default mock implementation
    (UseMasterDataHooks.useOrganizationUnits as any).mockReturnValue({
      data: mockData,
      isLoading: false,
    });
    (UseMasterDataHooks.useCreateOrganizationUnit as any).mockReturnValue({
      mutateAsync: vi.fn(),
    });
    (UseMasterDataHooks.useUpdateOrganizationUnit as any).mockReturnValue({
      mutateAsync: vi.fn(),
    });
    (UseMasterDataHooks.useDeleteOrganizationUnit as any).mockReturnValue({
      mutateAsync: vi.fn(),
    });
  });

  it("should render flattened list with correct hierarchy", () => {
    render(<OrganizationUnitPanel />);

    // 1. Verify all items are rendered (flattened)
    const facultyItems = screen.getAllByText("Faculty of IT");
    expect(facultyItems.length).toBeGreaterThan(0);
    expect(screen.getByText("Software Engineering")).toBeInTheDocument();
    expect(screen.getByText("Computer Science")).toBeInTheDocument();
    expect(screen.getByText("Faculty of Medical")).toBeInTheDocument();

    // 2. Verify Hierarchy Visualization (Indentation)
    // Find the row containing "Software Engineering"
    const nameSpan = screen.getByText("Software Engineering");
    const containerDiv = nameSpan.parentElement; // The div with flex and padding
    
    // Check padding logic (Level 1 should have 24px padding)
    expect(containerDiv).toHaveStyle({ paddingLeft: '24px' });

    // Check for the presence of the indentation marker.
    const arrowSpan = containerDiv?.querySelector(".text-muted-foreground");
    expect(arrowSpan).toBeInTheDocument();
    expect(arrowSpan).toHaveTextContent("└─"); 
  });

  it("should sort items by name within the hierarchy", () => {
    render(<OrganizationUnitPanel />);
    
    const cells = screen.getAllByText(/Faculty|Computer|Software/);
    const cellTexts = cells.map(cell => cell.textContent);

    const itIndex = cellTexts.findIndex(t => t?.includes("Faculty of IT"));
    const csIndex = cellTexts.findIndex(t => t?.includes("Computer Science"));
    const seIndex = cellTexts.findIndex(t => t?.includes("Software Engineering"));

    expect(itIndex).toBeLessThan(csIndex);
    expect(csIndex).toBeLessThan(seIndex);
  });

  it("should populate form data correctly when editing a child item", async () => {
    render(<OrganizationUnitPanel />);
    
    const seRow = screen.getByText("Software Engineering").closest("tr");
    const buttons = seRow?.querySelectorAll("button");
    const editButton = buttons?.[0];
    fireEvent.click(editButton!);

    // Verify Dialog Open
    const dialog = await screen.findByRole("dialog");
    expect(dialog).toBeInTheDocument();

    // Scope queries to the dialog
    const withinDialog = within(dialog);

    // 1. Name
    const nameInput = withinDialog.getByLabelText(/Name/i) as HTMLInputElement;
    expect(nameInput.value).toBe("Software Engineering");

    // 2. Type
    expect(withinDialog.getByText("Bộ môn")).toBeInTheDocument();

    // 3. Parent 
    expect(withinDialog.getByText(/Faculty of IT/)).toBeInTheDocument();
  });
});

/**
 * OrganizationUnitPanel Component
 *
 * Phase 1.1: Organization Unit Management
 * CRUD interface for organization units (Departments, Faculties, etc.)
 */

"use client";

import { useMemo } from "react";
import { Building2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { SmartUnitSelector } from "@/components/common/selectors/SmartUnitSelector";
import { CRUDTable } from "../shared/CRUDTable";
import {
  useOrganizationUnits,
  useCreateOrganizationUnit,
  useUpdateOrganizationUnit,
  useDeleteOrganizationUnit,
} from "@/hooks/admissions/useMasterData";
import type { OrganizationUnit, CRUDTableColumn, BaseFormData } from "../shared/types";

// ============================================
// CONSTANTS
// ============================================

// Valid organization unit types from backend
const ORGANIZATION_UNIT_TYPES = [
  "Trường",
  "Phòng ban",
  "Trung tâm",
  "Khoa",
  "Tổ",
  "Bộ môn",
];

const COLUMNS: CRUDTableColumn<OrganizationUnit>[] = [
  { key: "name", header: "Tên đơn vị" },
  { key: "type", header: "Loại hình", width: "120px" },
  { key: "parent_id", header: "Đơn vị cấp trên", width: "150px" },
  { key: "description", header: "Mô tả" },
  { key: "is_active", header: "Trạng thái", width: "100px" },
];

// ============================================
// COMPONENT
// ============================================

export function OrganizationUnitPanel() {
  const { data = [], isLoading } = useOrganizationUnits();
  const createMutation = useCreateOrganizationUnit();
  const updateMutation = useUpdateOrganizationUnit();
  const deleteMutation = useDeleteOrganizationUnit();

  // ============================================
  // HIERARCHY HELPERS
  // ============================================

  // ============================================
  // HIERARCHY HELPERS
  // ============================================

  // Helper to flatten nested tree
  const flattenTree = (units: OrganizationUnit[]): (OrganizationUnit & { level: number })[] => {
    const result: (OrganizationUnit & { level: number })[] = [];

    // Sort by name for display consistency
    const sortedUnits = [...units].sort((a, b) => a.name.localeCompare(b.name));

    sortedUnits.forEach((unit) => {
      // Add current unit
      // Since backend returns nested structure, we calculate level during recursive flattening
      // But for the root call, we need a starting level (0)
      // Actually, flattening logic needs to carry level.
      
      const traverse = (node: OrganizationUnit, level: number) => {
        result.push({ ...node, level });
        
        if (node.children && node.children.length > 0) {
           // Sort children
           const sortedChildren = [...node.children].sort((a, b) => a.name.localeCompare(b.name));
           sortedChildren.forEach(child => traverse(child, level + 1));
        }
      };

      traverse(unit, 0);
    });

    return result;
  };

  // Memoize sorted data
  const sortedData = useMemo(() => flattenTree(data), [data]);

  // Create flat lookup for finding parents
  const allUnitsFlat = useMemo(() => {
    const flatten = (units: OrganizationUnit[]): OrganizationUnit[] => {
      let result: OrganizationUnit[] = [];
      units.forEach((unit) => {
        result.push(unit);
        if (unit.children && unit.children.length > 0) {
          result = result.concat(flatten(unit.children));
        }
      });
      return result;
    };
    return flatten(data);
  }, [data]);

  // Enhance columns to show parent unit name and indentation
  const enhancedColumns: CRUDTableColumn<OrganizationUnit & { level: number }>[] = [
    {
      key: "name",
      header: "Name",
      render: (item: OrganizationUnit) => {
        // Cast to any to access level added by buildHierarchy
        const level = (item as any).level || 0;
        return (
          <div style={{ paddingLeft: `${level * 24}px` }} className="flex items-center">
            {level > 0 && <span className="text-muted-foreground mr-2">└─</span>}
            <span className={level === 0 ? "font-medium" : ""}>{item.name}</span>
          </div>
        );
      },
    },
    { key: "type", header: "Type", width: "120px" },
    {
      key: "parent_id",
      header: "Parent Unit",
      width: "200px",
      render: (item: OrganizationUnit) => {
        if (!item.parent_id) return <span className="text-muted-foreground">—</span>;
        const parent = allUnitsFlat.find((u: OrganizationUnit) => u.id === item.parent_id);
        return parent ? (
          <span className="text-sm">{parent.name}</span>
        ) : (
          <span className="text-sm text-muted-foreground">Đơn vị #{item.parent_id}</span>
        );
      },
    },
    { key: "description", header: "Description" },
    { key: "is_active", header: "Status", width: "100px" },
  ];

  const mapItemToFormData = (item: OrganizationUnit): BaseFormData => {
    const formData: any = {
      name: item.name,
      description: item.description || "",
      is_active: item.is_active,
      type: item.type,
      parent_id: item.parent_id,
    };
    return formData;
  };

  const handleCreate = async (formData: BaseFormData) => {
    // Transform formData to match backend OrganizationUnitCreate schema
    const payload = {
      name: formData.name,
      type: (formData as any).type, // Required by backend
      description: formData.description || null,
      parent_id: (formData as any).parent_id || null,
    };
    await createMutation.mutateAsync(payload as any);
  };

  const handleUpdate = async (id: number, formData: BaseFormData) => {
    // Transform formData to match backend OrganizationUnitUpdate schema
    const payload = {
      name: formData.name,
      type: (formData as any).type,
      description: formData.description || null,
      parent_id: (formData as any).parent_id || null,
    };
    await updateMutation.mutateAsync({ id, data: payload as any });
  };

  const handleDelete = async (id: number) => {
    await deleteMutation.mutateAsync(id);
  };

  const renderForm = (
    item: OrganizationUnit | null,
    formData: BaseFormData,
    setFormData: (data: BaseFormData) => void,
    isEdit: boolean
  ) => {
    return (
      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="name">
            Tên đơn vị <span className="text-destructive">*</span>
          </Label>
          <Input
            id="name"
            value={formData.name || ""}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder="Ví dụ: Khoa Công nghệ Thông tin"
            required
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="type">
            Loại hình <span className="text-destructive">*</span>
          </Label>
          <Select
            value={(formData as any).type || ""}
            onValueChange={(value) =>
              setFormData({ ...formData, type: value } as any)
            }
          >
            <SelectTrigger id="type">
              <SelectValue placeholder="Chọn loại đơn vị" />
            </SelectTrigger>
            <SelectContent>
              {ORGANIZATION_UNIT_TYPES.map((type) => (
                <SelectItem key={type} value={type}>
                  {type}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            Loại hình tổ chức (ví dụ: Khoa, Phòng ban)
          </p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="parent_id">Đơn vị cấp trên (Tùy chọn)</Label>
          <SmartUnitSelector
            value={(formData as any).parent_id?.toString()}
            onChange={(value) =>
              setFormData({
                ...formData,
                parent_id: value ? parseInt(value) : null
              } as any)
            }
            placeholder="Không có (Đơn vị cấp cao nhất)"
            allowNone={true}
            noneLabel="Không có (Đơn vị cấp cao nhất)"
            excludeUnitId={item?.id} // Prevent self-parenting and circular dependencies
            variant="combobox"
            activeOnly={false} // Show inactive units for editing existing relationships
          />
          <p className="text-xs text-muted-foreground">
            Đơn vị cấp trên trực tiếp (để trống nếu là đơn vị cấp cao nhất)
          </p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="description">Mô tả</Label>
          <Textarea
            id="description"
            value={formData.description || ""}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            placeholder="Mô tả tóm tắt về đơn vị"
            rows={3}
          />
        </div>
      </div>
    );
  };

  const initialFormData = (): any => ({
    name: "",
    type: "", // Required by backend
    description: "",
    parent_id: null,
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Quản lý Đơn vị Tổ chức</h1>
        <p className="text-muted-foreground mt-2">
          Quản lý danh sách các khoa, phòng ban và đơn vị trực thuộc
        </p>
      </div>

      <CRUDTable<OrganizationUnit & { level: number }>
        title="Đơn vị"
        description="Khoa, phòng ban và các đơn vị khác"
        icon={<Building2 className="h-5 w-5 text-primary" />}
        columns={enhancedColumns}
        data={sortedData}
        isLoading={isLoading}
        onCreate={handleCreate}
        onUpdate={handleUpdate}
        onDelete={handleDelete}
        renderForm={renderForm}
        initialFormData={initialFormData}
        mapItemToFormData={mapItemToFormData}
      />
    </div>
  );
}

