        display_order: 3, // length + 1
      }));
    });
  });

  it("should open edit dialog and populate data correctly", async () => {
    render(<SubjectGroupTable />);

    // Edit "A00" (Row 1)
    const row = screen.getByText("A00").closest("tr");
