/**
 * MajorProgramPanel Component
 *
 * Phase 2.1: Major Program Management
 * CRUD interface for major programs (IT, Business, etc.)
 * With organization unit selection
 */

"use client";

import { useMemo } from "react";
import { GraduationCap } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { SmartUnitSelector } from "@/components/common/selectors/SmartUnitSelector";
import { CRUDTable } from "../shared/CRUDTable";
import {
  useMajorPrograms,
  useCreateMajorProgram,
  useUpdateMajorProgram,
  useDeleteMajorProgram,
} from "@/hooks/admissions/useProgramData";
import { useOrganizationUnits } from "@/hooks/admissions/useMasterData";
import type { MajorProgram, CRUDTableColumn, BaseFormData } from "../shared/types";

// ============================================
// CONSTANTS
// ============================================

export function MajorProgramPanel() {
  const { data = [], isLoading } = useMajorPrograms();
  const { data: units = [] } = useOrganizationUnits();
  const createMutation = useCreateMajorProgram();
  const updateMutation = useUpdateMajorProgram();
  const deleteMutation = useDeleteMajorProgram();

  // Group and sort data by degree level
  const groupedData = useMemo(() => {
    // Define the order of degree levels
    const levelOrder = ["Đại học", "Cao đẳng", "Trung cấp", "Sơ cấp"];

    // Group by degree_level
    const grouped = data.reduce((acc: Record<string, MajorProgram[]>, program: MajorProgram) => {
      const level = program.degree_level || "Khác";
      if (!acc[level]) acc[level] = [];
      acc[level].push(program);
      return acc;
    }, {} as Record<string, MajorProgram[]>);

    // Sort programs within each group by name
    Object.keys(grouped).forEach(level => {
      grouped[level].sort((a: MajorProgram, b: MajorProgram) => a.name.localeCompare(b.name));
    });

    // Sort groups by predefined order
    return levelOrder
      .filter(level => grouped[level])
      .map(level => ({ level, programs: grouped[level] }))
      .concat(
        Object.keys(grouped)
          .filter(level => !levelOrder.includes(level))
          .map(level => ({ level, programs: grouped[level] }))
      );
  }, [data]);

  // Flatten grouped data for table display with level markers
  const flattenedData = useMemo(() => {
    const result: (MajorProgram & { isGroupHeader?: boolean; groupLevel?: string })[] = [];

    groupedData.forEach((group, groupIndex) => {
      // Add group header marker with unique ID to avoid key conflicts
      result.push({
        id: `header-${groupIndex}` as any, // Unique string-based ID for header
        code: group.level,
        name: group.level,
        degree_level: group.level,
        unit_id: 0,
        is_active: true,
        is_heavy: false,
        isGroupHeader: true,
        groupLevel: group.level,
      } as any);

      // Add programs in this group
      group.programs.forEach((program: MajorProgram) => {
        result.push(program);
      });
    });

    return result;
  }, [groupedData]);

  const COLUMNS: CRUDTableColumn<MajorProgram>[] = [
    {
      key: "code",
      header: "Mã ngành",
      width: "120px",
      render: (item: any) => {
        // Show group header
        if (item.isGroupHeader) {
          return (
            <div className="font-bold text-base text-primary py-1 col-span-full">
              {item.groupLevel}
            </div>
          );
        }
        return (
          <code className="bg-muted rounded px-2 py-1 text-xs font-mono">
            {item.code}
          </code>
        );
      }
    },
    {
      key: "degree_level",
      header: "Trình độ",
      width: "120px",
      render: (item: any) => {
        if (item.isGroupHeader) return null;
        return item.degree_level;
      }
    },
    {
      key: "name",
      header: "Tên chương trình",
      render: (item: any) => {
        if (item.isGroupHeader) return null;
        return item.name;
      }
    },
    {
      key: "is_heavy",
      header: "Nặng nhọc/Độc hại",
      width: "140px",
      render: (item: any) => {
        if (item.isGroupHeader) return null;
        return (
          <span className={item.is_heavy ? "text-amber-600 font-medium" : "text-muted-foreground"}>
            {item.is_heavy ? "Có" : "Không"}
          </span>
        );
      }
    },
    {
      key: "quota",
      header: "Tổng chỉ tiêu",
      width: "120px",
      render: (item: any) => {
        if (item.isGroupHeader) return null;
        const total = item.offerings?.reduce((acc: number, off: any) => {
          const latestInfo = off.academic_info_history?.[0];
          return acc + (latestInfo?.annual_admission_quota || 0);
        }, 0) || 0;

        if (total === 0) return <span className="text-muted-foreground text-xs">—</span>;
        return <span className="font-medium">{total}</span>;
      }
    },
    {
      key: "unit_id",
      header: "Đơn vị quản lý",
      width: "200px",
      render: (item: any) => {
        if (item.isGroupHeader) return null;
        const unit = units.find((u: any) => u.id === item.unit_id);
        if (!unit) return <span className="text-muted-foreground text-xs">—</span>;
        return <span className="text-sm">{unit.name}</span>;
      },
    },
    {
      key: "is_active",
      header: "Trạng thái",
      width: "100px",
      render: (item: any) => {
        if (item.isGroupHeader) return null;
        return item.is_active;
      }
    },
  ];

  const handleCreate = async (formData: BaseFormData) => {
    // Transform to match backend MajorProgramCreate schema
    const payload = {
      name: formData.name,
      degree_level: formData.degree_level,
      code: formData.code,
      unit_id: parseInt(formData.unit_id?.toString() || "0"),
      is_active: formData.is_active !== undefined ? formData.is_active : true,
      is_heavy: !!formData.is_heavy,
    };
    await createMutation.mutateAsync(payload as any);
  };

  const handleUpdate = async (id: number, formData: BaseFormData) => {
    // Transform to match backend MajorProgramUpdate schema
    // Note: code is NOT updatable per backend schema
    const payload = {
      name: formData.name,
      degree_level: formData.degree_level,
      unit_id: parseInt(formData.unit_id?.toString() || "0"),
      is_active: formData.is_active,
      is_heavy: !!formData.is_heavy,
    };
    await updateMutation.mutateAsync({ id, data: payload as any });
  };

  const handleDelete = async (id: number) => {
    await deleteMutation.mutateAsync(id);
  };

  const renderForm = (
    item: MajorProgram | null,
    formData: BaseFormData,
    setFormData: (data: BaseFormData) => void,
    isEdit: boolean
  ) => {
    return (
      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="code">
            Mã ngành <span className="text-destructive">*</span>
          </Label>
          <Input
            id="code"
            value={formData.code || ""}
            onChange={(e) => setFormData({ ...formData, code: e.target.value })}
            placeholder="vd: 6480201, 7340101"
            disabled={isEdit}
            required
          />
          <p className="text-xs text-muted-foreground">
            Mã ngành chính thức theo Bộ GD&ĐT (không thể thay đổi sau khi tạo)
          </p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="degree_level">
              Trình độ đào tạo <span className="text-destructive">*</span>
            </Label>
            <Select
              value={formData.degree_level?.toString() || "Cao đẳng"}
              onValueChange={(value) => setFormData({ ...formData, degree_level: value })}
            >
              <SelectTrigger id="degree_level">
                <SelectValue placeholder="Chọn trình độ" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="Cao đẳng">Cao đẳng</SelectItem>
                <SelectItem value="Trung cấp">Trung cấp</SelectItem>
                <SelectItem value="Sơ cấp">Sơ cấp</SelectItem>
                <SelectItem value="Đại học">Đại học</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-end pb-2">
            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                id="is_heavy"
                checked={!!formData.is_heavy}
                onChange={(e) => setFormData({ ...formData, is_heavy: e.target.checked })}
                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
              />
              <Label htmlFor="is_heavy" className="cursor-pointer">
                Ngành nặng nhọc, độc hại
              </Label>
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="name">
            Tên chương trình <span className="text-destructive">*</span>
          </Label>
          <Input
            id="name"
            value={formData.name || ""}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder="vd: Cao đẳng Công nghệ Thông tin"
            required
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="unit_id">Đơn vị quản lý <span className="text-destructive">*</span></Label>
          <SmartUnitSelector
            value={formData.unit_id?.toString()}
            onChange={(value) =>
              setFormData({ ...formData, unit_id: value ? parseInt(value) : null })
            }
            placeholder="Chọn khoa/bộ môn quản lý"
            variant="combobox"
            filterTypes={["Khoa", "Bộ môn", "Trung tâm"]} // Only show relevant organizational units
            activeOnly={true} // Only show active units for assignment
          />
          <p className="text-xs text-muted-foreground">
            Khoa hoặc bộ môn trực tiếp quản lý chuyên môn của ngành này
          </p>
        </div>
      </div>
    );
  };

  const initialFormData = () => ({
    code: "",
    degree_level: "Cao đẳng",
    name: "",
    unit_id: null,
    is_heavy: false,
  });

  const mapItemToFormData = (item: MajorProgram): BaseFormData => {
    return {
      code: item.code,
      degree_level: item.degree_level,
      name: item.name,
      unit_id: item.unit_id,
      is_heavy: item.is_heavy,
      is_active: item.is_active,
    } as any;
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Chương trình đào tạo</h1>
        <p className="text-muted-foreground mt-2">
          Quản lý danh mục các ngành, nghề đào tạo (CNTT, Kinh tế, Kỹ thuật...)
        </p>
      </div>

      <CRUDTable<MajorProgram>
        title="Ngành đào tạo"
        description="Danh sách các ngành đào tạo của nhà trường"
        icon={<GraduationCap className="h-5 w-5 text-primary" />}
        columns={COLUMNS}
        data={flattenedData as any}
        isLoading={isLoading}
        onCreate={handleCreate}
        onUpdate={handleUpdate}
        onDelete={handleDelete}
        renderForm={renderForm}
        initialFormData={initialFormData}
        mapItemToFormData={mapItemToFormData}
      />
    </div>
  );
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, within, waitFor } from "@/test/utils/test-utils";
import { ProgramOfferingPanel } from "./ProgramOfferingPanel";
import * as UseProgramDataHooks from "@/hooks/admissions/useProgramData";
import * as UseMasterDataHooks from "@/hooks/admissions/useMasterData";

// Mock the hooks
vi.mock("@/hooks/admissions/useProgramData", () => ({
  useProgramOfferings: vi.fn(),
  useCreateProgramOffering: vi.fn(),
  useUpdateProgramOffering: vi.fn(),
  useDeleteProgramOffering: vi.fn(),
  useMajorPrograms: vi.fn(),
}));

vi.mock("@/hooks/admissions/useMasterData", () => ({
  useOfferingTypes: vi.fn(),
}));

describe("ProgramOfferingPanel", () => {
  const mockOfferings = [
    {
      id: 1,
      program_id: 1,
      offering_type: "Chính quy",
      duration_semesters: 6,
      total_credits: 120,
      is_active: true,
      program: { name: "Công nghệ Thông tin", code: "648" }
    },
    {
      id: 2,
      program_id: 2,
      offering_type: "Vừa làm vừa học",
      duration_semesters: 8,
      total_credits: 130,
      is_active: true,
      program: { name: "Quản trị Kinh doanh", code: "734" }
    }
  ];

  const mockMajors = [
    { id: 1, name: "Công nghệ Thông tin", code: "648" },
    { id: 2, name: "Quản trị Kinh doanh", code: "734" },
  ];

  const mockOfferingTypes = [
    { id: 10, name: "Chính quy", code: "CQ" },
    { id: 11, name: "Vừa làm vừa học", code: "VLVH" },
  ];

  const mockCreateMutate = vi.fn();
  const mockUpdateMutate = vi.fn();
  const mockDeleteMutate = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    window.HTMLElement.prototype.scrollIntoView = vi.fn();
    
    (UseProgramDataHooks.useProgramOfferings as any).mockReturnValue({
      data: mockOfferings,
      isLoading: false,
    });
    
    (UseProgramDataHooks.useMajorPrograms as any).mockReturnValue({
      data: mockMajors,
      isLoading: false,
    });
    
    (UseMasterDataHooks.useOfferingTypes as any).mockReturnValue({
      data: mockOfferingTypes,
      isLoading: false,
    });

    (UseProgramDataHooks.useCreateProgramOffering as any).mockReturnValue({
      mutateAsync: mockCreateMutate,
    });
    
    (UseProgramDataHooks.useUpdateProgramOffering as any).mockReturnValue({
      mutateAsync: mockUpdateMutate,
    });
    
    (UseProgramDataHooks.useDeleteProgramOffering as any).mockReturnValue({
      mutateAsync: mockDeleteMutate,
    });
  });

  it("should render offerings list correctly", () => {
    render(<ProgramOfferingPanel />);

    // Check Major Names (rendered via lookups)
    expect(screen.getByText("Công nghệ Thông tin")).toBeInTheDocument();
    expect(screen.getByText("Quản trị Kinh doanh")).toBeInTheDocument();

    // Check Offering Types
    expect(screen.getByText("Chính quy")).toBeInTheDocument();
    expect(screen.getByText("Vừa làm vừa học")).toBeInTheDocument();
    
    // Check details
    expect(screen.getByText("6")).toBeInTheDocument(); // Duration
    expect(screen.getByText("120")).toBeInTheDocument(); // Credits
  });

  it("should open create dialog and submit form correctly", async () => {
    render(<ProgramOfferingPanel />);

    // Click Add New
    const addButton = screen.getByText("Add New");
    fireEvent.click(addButton);

    // Verify Dialog
    const dialog = await screen.findByRole("dialog");
    expect(dialog).toBeInTheDocument();
    expect(screen.getByText("Create Program Offering")).toBeInTheDocument();

    const withinDialog = within(dialog);

    // Select Major Program
    // Select Major Program & Offering Type
    // Using getAllByRole is safer when text/label selectors are flaky with Radix
    const triggers = await withinDialog.findAllByRole("combobox");
    
    // Assuming order: Program, Type, ...
    const programTrigger = triggers[0]; 
    fireEvent.click(programTrigger);
    const majorOption = await screen.findByText("Công nghệ Thông tin (648)");
    fireEvent.click(majorOption);

    const typeTrigger = triggers[1];
    fireEvent.click(typeTrigger);
    const typeOption = await screen.findByText("Chính quy (CQ)");
    fireEvent.click(typeOption);

    // Input text details
    fireEvent.change(withinDialog.getByLabelText(/Duration/i), { target: { value: "7" } });
    fireEvent.change(withinDialog.getByLabelText(/Total Credits/i), { target: { value: "140" } });
    
    // Submit
    const submitButton = withinDialog.getByText("Create");
    fireEvent.click(submitButton);

    // Check Mutation
    await waitFor(() => {
      expect(mockCreateMutate).toHaveBeenCalledWith(expect.objectContaining({
        duration_semesters: 7,
        total_credits: 140,
        program_id: 1, // ID of Công nghệ Thông tin
        offering_type: "Chính quy", // Name of offering type
      }));
    });
  });

  it("should open edit dialog and populate data correctly", async () => {
    render(<ProgramOfferingPanel />);

    // Edit Row 1
    const row = screen.getByText("Công nghệ Thông tin").closest("tr");
    const editButton = row?.querySelector("button"); 
    fireEvent.click(editButton!);

    // Verify Dialog
    const dialog = await screen.findByRole("dialog");
    expect(dialog).toBeInTheDocument();
    const withinDialog = within(dialog);

    // Verify Fields
    await waitFor(() => {
        const durationInput = withinDialog.getByLabelText(/Duration/i) as HTMLInputElement;
        expect(durationInput.value).toBe("6");
    });

    const creditInput = withinDialog.getByLabelText(/Total Credits/i) as HTMLInputElement;
    expect(creditInput.value).toBe("120");
    
    // Warning: Selects for Program and Offering Type won't strictly "show" text "Công nghệ Thông tin" in input value via simple query
    // But we check that state *would* allow user to see it.
  });

  it("should call delete mutation when delete is confirmed", async () => {
    vi.spyOn(window, "confirm").mockImplementation(() => true);

    render(<ProgramOfferingPanel />);

    const row = screen.getByText("Quản trị Kinh doanh").closest("tr");
    const buttons = row?.querySelectorAll("button");
    const deleteButton = buttons?.[1]; 
    
    fireEvent.click(deleteButton!);

    expect(window.confirm).toHaveBeenCalled();
    await waitFor(() => {
      expect(mockDeleteMutate).toHaveBeenCalledWith(2);
    });
  });
});

/**
 * ProgramOfferingPanel Component
 *
 * Phase 2.2: Program Offering Management
 * CRUD interface for program offerings (combinations of major + offering type)
 * Example: "IT Program - Full-time", "Business Program - Part-time"
 */

"use client";

import { BookOpen } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { CRUDTable } from "../shared/CRUDTable";
import type { ProgramOffering, CRUDTableColumn, BaseFormData } from "../shared/types";
import {
  useProgramOfferings,
  useCreateProgramOffering,
  useUpdateProgramOffering,
  useDeleteProgramOffering,
} from "@/hooks/admissions/useProgramData";
import { useMajorPrograms } from "@/hooks/admissions/useProgramData";
import { useOfferingTypes } from "@/hooks/admissions/useMasterData";

// ============================================
// CONSTANTS
// ============================================

const COLUMNS: CRUDTableColumn<ProgramOffering>[] = [
  {
    key: "program_id",
    header: "Ngành đào tạo",
    width: "200px",
    render: (item) => {
      if (!item.program_id) return "—";
      return <span className="text-sm">Ngành #{item.program_id}</span>;
    },
  },
  {
    key: "offering_type",
    header: "Hệ đào tạo",
    width: "200px",
    render: (item) => {
      return <span className="text-sm">{item.offering_type || "—"}</span>;
    },
  },
  {
    key: "duration_semesters",
    header: "Thời gian (HK)",
    width: "120px",
    render: (item) => {
      return <span className="text-sm">{item.duration_semesters || "—"}</span>;
    },
  },
  {
    key: "total_credits",
    header: "Tổng tín chỉ",
    width: "120px",
    render: (item) => {
      return <span className="text-sm">{item.total_credits || "—"}</span>;
    },
  },
  { key: "is_active", header: "Trạng thái", width: "100px" },
];

// ============================================
// COMPONENT
// ============================================

export function ProgramOfferingPanel() {
  const { data = [], isLoading } = useProgramOfferings();
  const { data: majors = [] } = useMajorPrograms();
  const { data: offeringTypes = [] } = useOfferingTypes();
  const createMutation = useCreateProgramOffering();
  const updateMutation = useUpdateProgramOffering();
  const deleteMutation = useDeleteProgramOffering();

  // Enhance columns with actual names from loaded data
  const enhancedColumns: CRUDTableColumn<ProgramOffering>[] = COLUMNS.map((col) => {
    // Handle Major Program (ID Map)
    if (col.key === "program_id") {
      return {
        ...col,
        render: (item: any) => {
          // Use program_id from backend
          const majorId = item.program_id;
          const major = majors.find((m: { id: number; name: string; code: string }) => m.id === majorId);

          if (!major) {
             // Try to use nested program name if available
             if (item.program?.name) return <span className="text-sm text-muted-foreground">{item.program.name}</span>;
             return <span className="text-muted-foreground">—</span>;
          }

          return (
            <span className="text-sm font-medium">
              {major.name}
              <span className="text-muted-foreground ml-1">({major.code})</span>
            </span>
          );
        },
      };
    }

    return col;
  });

  const handleCreate = async (formData: BaseFormData) => {
    // Transform to match backend ProgramOfferingCreate schema
    const offeringType = offeringTypes.find((t: { id: number; name: string }) => t.id === formData.offering_type_id);
    if (!offeringType) {
      throw new Error("Please select a valid offering type");
    }

    const payload = {
      program_id: parseInt(formData.program_id?.toString() || "0"),
      offering_type: offeringType.name, // Backend expects string name, not ID
      duration_semesters: (formData as any).duration_semesters || undefined,
      total_credits: (formData as any).total_credits || undefined,
      is_active: formData.is_active !== undefined ? formData.is_active : true,
      scoring_rules: (formData as any).scoring_rules || undefined,
    };

    await createMutation.mutateAsync(payload as any);
  };

  const handleUpdate = async (id: number, formData: BaseFormData) => {
    // Transform to match backend ProgramOfferingUpdate schema
    const payload: any = {
      duration_semesters: (formData as any).duration_semesters || undefined,
      total_credits: (formData as any).total_credits || undefined,
      is_active: formData.is_active,
      scoring_rules: (formData as any).scoring_rules || undefined,
    };

    // If offering_type_id is provided, convert it to offering_type (string)
    if (formData.offering_type_id) {
      const offeringType = offeringTypes.find((t: { id: number; name: string }) => t.id === formData.offering_type_id);
      if (offeringType) {
        payload.offering_type = offeringType.name;
      }
    }

    await updateMutation.mutateAsync({ id, data: payload });
  };

  const handleDelete = async (id: number) => {
    await deleteMutation.mutateAsync(id);
  };

  const renderForm = (
    item: ProgramOffering | null,
    formData: BaseFormData,
    setFormData: (data: BaseFormData) => void,
    isEdit: boolean
  ) => {
    return (
      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="program_id">
            Ngành đào tạo <span className="text-destructive">*</span>
          </Label>
          <Select
            value={formData.program_id?.toString() || ""}
            onValueChange={(value) =>
              setFormData({ ...formData, program_id: parseInt(value) })
            }
          >
            <SelectTrigger id="program_id">
              <SelectValue placeholder="Chọn ngành đào tạo" />
            </SelectTrigger>
            <SelectContent>
              {majors.length === 0 && (
                <div className="p-2 text-sm text-muted-foreground">
                  Chưa có ngành nào. Vui lòng tạo ngành đào tạo trước.
                </div>
              )}
              {majors.map((major: { id: number; name: string; code: string }) => (
                <SelectItem key={major.id} value={major.id.toString()}>
                  {major.name} ({major.code})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            Chương trình đào tạo (ví dụ: CNTT, Kinh tế)
          </p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="offering_type_id">
            Hệ đào tạo <span className="text-destructive">*</span>
          </Label>
          <Select
            value={formData.offering_type_id?.toString() || ""}
            onValueChange={(value) =>
              setFormData({ ...formData, offering_type_id: parseInt(value) })
            }
          >
            <SelectTrigger id="offering_type_id">
              <SelectValue placeholder="Chọn hệ đào tạo" />
            </SelectTrigger>
            <SelectContent>
              {offeringTypes.length === 0 && (
                <div className="p-2 text-sm text-muted-foreground">
                  Chưa có hệ đào tạo nào. Vui lòng tạo hệ đào tạo trước.
                </div>
              )}
              {offeringTypes.map((type: { id: number; name: string; code: string }) => (
                <SelectItem key={type.id} value={type.id.toString()}>
                  {type.name} ({type.code})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            Hình thức đào tạo (Chính quy, Vừa làm vừa học...)
          </p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="duration_semesters">Thời gian (Học kỳ)</Label>
            <Input
              id="duration_semesters"
              type="number"
              value={(formData as any).duration_semesters || ""}
              onChange={(e) =>
                setFormData({ ...formData, duration_semesters: e.target.value ? parseInt(e.target.value) : undefined } as any)
              }
              placeholder="e.g., 6"
              min={1}
            />
            <p className="text-xs text-muted-foreground">
              Số học kỳ dự kiến để hoàn thành
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="total_credits">Tổng tín chỉ</Label>
            <Input
              id="total_credits"
              type="number"
              value={(formData as any).total_credits || ""}
              onChange={(e) =>
                setFormData({ ...formData, total_credits: e.target.value ? parseInt(e.target.value) : undefined } as any)
              }
              placeholder="vd: 120"
              min={1}
            />
            <p className="text-xs text-muted-foreground">
              Tổng số tín chỉ tích lũy yêu cầu
            </p>
          </div>
        </div>

        <div className="border rounded-lg p-4 bg-slate-50 space-y-4">
          <h3 className="font-medium flex items-center gap-2">
            Cấu hình Xét tuyển (Scoring Rules)
          </h3>
          
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="scoring_hot_level">Mức độ Hot</Label>
              <Select
                value={(formData as any).scoring_rules?.hot_level?.toString() || "0"}
                onValueChange={(value) => {
                  const currentRules = (formData as any).scoring_rules || {};
                  setFormData({
                    ...formData,
                    scoring_rules: { ...currentRules, hot_level: parseInt(value) }
                  } as any);
                }}
              >
                <SelectTrigger id="scoring_hot_level">
                  <SelectValue placeholder="Chọn mức độ Hot" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="0">Bình thường (0)</SelectItem>
                  <SelectItem value="1">Hot (1)</SelectItem>
                  <SelectItem value="2">Rất Hot (2)</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="scoring_education">Trình độ văn hóa yêu cầu</Label>
              <Select
                value={(formData as any).scoring_rules?.required_education || "thpt"}
                onValueChange={(value) => {
                  const currentRules = (formData as any).scoring_rules || {};
                  setFormData({
                    ...formData,
                    scoring_rules: { ...currentRules, required_education: value }
                  } as any);
                }}
              >
                <SelectTrigger id="scoring_education">
                  <SelectValue placeholder="Chọn trình độ" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="thpt">Tốt nghiệp THPT</SelectItem>
                  <SelectItem value="cao_dang">Tốt nghiệp Cao đẳng</SelectItem>
                  <SelectItem value="dai_hoc">Tốt nghiệp Đại học</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="scoring_age_min">Độ tuổi tối thiểu</Label>
              <Input
                id="scoring_age_min"
                type="number"
                value={(formData as any).scoring_rules?.target_age_min || ""}
                onChange={(e) => {
                   const val = e.target.value ? parseInt(e.target.value) : undefined;
                   const currentRules = (formData as any).scoring_rules || {};
                   setFormData({
                    ...formData,
                    scoring_rules: { ...currentRules, target_age_min: val }
                  } as any);
                }}
                placeholder="vd: 18"
                min={16}
                max={100}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="scoring_age_max">Độ tuổi tối đa</Label>
              <Input
                id="scoring_age_max"
                type="number"
                value={(formData as any).scoring_rules?.target_age_max || ""}
                onChange={(e) => {
                   const val = e.target.value ? parseInt(e.target.value) : undefined;
                   const currentRules = (formData as any).scoring_rules || {};
                   setFormData({
                    ...formData,
                    scoring_rules: { ...currentRules, target_age_max: val }
                  } as any);
                }}
                placeholder="vd: 35"
                min={16}
                max={100}
              />
            </div>
          </div>
        </div>
      </div>
    );
  };

  const initialFormData = () => ({
    program_id: null,
    offering_type_id: null,
  });

  const mapItemToFormData = (item: ProgramOffering): BaseFormData => {
    // Map ProgramOffering to form data structure
    // Find the offering_type_id from the offering type name
    const offeringType = offeringTypes.find((t: { id: number; name: string }) => t.name === item.offering_type);

    return {
      program_id: item.program_id,
      offering_type_id: offeringType?.id || null,
      is_active: item.is_active,
      duration_semesters: item.duration_semesters,
      total_credits: item.total_credits,
      scoring_rules: item.scoring_rules,
    } as any;
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Chương trình Tuyển sinh</h1>
        <p className="text-muted-foreground mt-2">
          Quản lý các chương trình tuyển sinh (kết hợp giữa ngành và hệ đào tạo)
        </p>
      </div>

      {/* Warning if dependencies are missing */}
      {(majors.length === 0 || offeringTypes.length === 0) && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <p className="text-sm text-yellow-800 font-medium">
            Yêu cầu dữ liệu
          </p>
          <p className="text-sm text-yellow-700 mt-1">
            {majors.length === 0 && "Chưa có Ngành đào tạo. Vui lòng tạo Ngành trước tại Bước 2.1."}
            {majors.length === 0 && offeringTypes.length === 0 && " Đồng thời, "}
            {offeringTypes.length === 0 && "Chưa có Hệ đào tạo. Vui lòng tạo Hệ đào tạo trước tại Bước 1.2."}
          </p>
        </div>
      )}

      <CRUDTable<ProgramOffering>
        title="Chương trình Tuyển sinh"
        description="Kết hợp giữa ngành và hệ đào tạo"
        icon={<BookOpen className="h-5 w-5 text-primary" />}
        columns={enhancedColumns}
        data={data}
        isLoading={isLoading}
        onCreate={handleCreate}
        onUpdate={handleUpdate}
        onDelete={handleDelete}
        renderForm={renderForm}
        initialFormData={initialFormData}
        mapItemToFormData={mapItemToFormData}
      />
    </div>
  );
}

