"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Loader2, ArrowRight, ArrowLeft, Search, X, Save } from "lucide-react";
import { toast } from "sonner";

import { useUpdateCriteria } from "@/hooks/admissions/useAdmissionPaths";
import { useSubjectGroups } from "@/hooks/admissions/useMasterData";
import { AdmissionPathResponse } from "@/lib/zod/admission-path";

interface ConfigCriteriaProps {
  path: AdmissionPathResponse;
  onNext: () => void;
  onBack: () => void;
}

export function ConfigCriteria({ path, onNext, onBack }: ConfigCriteriaProps) {
  const { data: subjectGroups = [], isLoading: loadingGroups } = useSubjectGroups();
  const updateMutation = useUpdateCriteria();

  // Form State
  const [minGpa, setMinGpa] = useState<string>("");
  const [minScore, setMinScore] = useState<string>("");
  const [minSubjectScore, setMinSubjectScore] = useState<string>("");
  const [maxScore, setMaxScore] = useState<string>("");
  const [conditions, setConditions] = useState<string>("");
  const [requiredSubjectCount, setRequiredSubjectCount] = useState<string>("");
  
  const [scoringMethod, setScoringMethod] = useState<"sum" | "avg">("sum");
  const [selectionMode, setSelectionMode] = useState<"fixed" | "dynamic">("fixed");
  const [selectedGroups, setSelectedGroups] = useState<number[]>([]);
  
  // Validity State
  const [policyVersion, setPolicyVersion] = useState<string>("2025.1");
  const [effectiveFrom, setEffectiveFrom] = useState<string>("");
  const [effectiveTo, setEffectiveTo] = useState<string>("");

  // Search state for filtering subject groups
  const [searchQuery, setSearchQuery] = useState<string>("");

  // Initialize from existing criteria
  useEffect(() => {
    if (path.criteria) {
      setMinGpa(path.criteria.min_gpa?.toString() || "");
      setMinScore(path.criteria.min_score?.toString() || "");
      setMinSubjectScore(path.criteria.min_subject_score?.toString() || "");
      setMaxScore(path.criteria.max_possible_score?.toString() || "");
      setConditions(path.criteria.conditions || "");
      setRequiredSubjectCount(path.criteria.required_subject_count?.toString() || "");

      setScoringMethod((path.criteria.scoring_method as "sum" | "avg") || "sum");
      setSelectionMode((path.criteria.subject_selection_mode as "fixed" | "dynamic") || "fixed");

      setPolicyVersion(path.criteria.policy_version || "2025.1");
      setEffectiveFrom(path.criteria.effective_from || "");
      setEffectiveTo(path.criteria.effective_to || "");

      // Map nested groups to IDs
      const groupIds = path.criteria.subject_groups.map(g => g.id);
      setSelectedGroups(groupIds);
    }
  }, [
    path.criteria,
    path.criteria?.min_gpa,
    path.criteria?.min_score,
    path.criteria?.min_subject_score,
    path.criteria?.max_possible_score,
    path.criteria?.scoring_method,
    path.criteria?.subject_selection_mode,
    path.updated_at, // Trigger re-sync when path is updated
  ]);

  // Filter subject groups based on search query
  // Filter subject groups based on search query
  const filteredGroups = Array.isArray(subjectGroups) 
    ? subjectGroups.filter((group: any) => {
        if (!searchQuery) return true;
        const query = searchQuery.toLowerCase();
        return (
          (group.code?.toLowerCase() || "").includes(query) ||
          (group.name?.toLowerCase() || "").includes(query)
        );
      })
    : [];

  // Get selected group details for chip display
  const selectedGroupsDetails = subjectGroups.filter((group: any) =>
    selectedGroups.includes(group.id)
  );

  // Handlers
  const handleGroupToggle = (groupId: number) => {
    setSelectedGroups(prev =>
      prev.includes(groupId)
        ? prev.filter(id => id !== groupId)
        : [...prev, groupId]
    );
  };

  const handleRemoveGroup = (groupId: number) => {
    setSelectedGroups(prev => prev.filter(id => id !== groupId));
  };

  const handleSave = async () => {
    // Validation
    if (selectedGroups.length === 0) {
      toast.warning("Vui lòng chọn ít nhất một tổ hợp môn");
      return;
    }

    try {
      // Helper to safely parse float and avoid NaN
      const safeParseFloat = (value: string): number | null => {
        if (!value || value.trim() === "") return null;
        const parsed = parseFloat(value.trim());
        return isNaN(parsed) ? null : parsed;
      };

      // Helper to safely parse int and avoid NaN
      const safeParseInt = (value: string): number | null => {
        if (!value || value.trim() === "") return null;
        const parsed = parseInt(value.trim());
        return isNaN(parsed) ? null : parsed;
      };

      // Prepare data with proper type conversion
      const payload = {
        min_gpa: safeParseFloat(minGpa),
        min_score: safeParseFloat(minScore),
        min_subject_score: safeParseFloat(minSubjectScore),
        max_possible_score: safeParseFloat(maxScore),
        conditions: conditions && conditions.trim() !== "" ? conditions.trim() : null,
        required_subject_count: safeParseInt(requiredSubjectCount),
        scoring_method: scoringMethod,
        subject_selection_mode: selectionMode,
        subject_groups: selectedGroups,
        policy_version: policyVersion,
        effective_from: effectiveFrom || null,
        effective_to: effectiveTo || null,
      };

      console.log("Sending criteria payload:", payload);

      await updateMutation.mutateAsync({
        pathId: path.id,
        data: payload
      });
      toast.success("Đã lưu tiêu chí xét tuyển thành công");
      // Move to next step after successful save
      onNext();
    } catch (error: any) {
      console.error("Failed to save criteria:", error);
      console.error("Error response:", error?.response?.data);

      // Extract validation error details
      const errorDetail = error?.response?.data?.detail;
      let errorMessage = "Lưu thất bại. Vui lòng kiểm tra lại.";

      if (Array.isArray(errorDetail)) {
        // Pydantic validation errors
        errorMessage = errorDetail.map((e: any) => `${e.loc?.join('.')}: ${e.msg}`).join(", ");
      } else if (typeof errorDetail === "string") {
        errorMessage = errorDetail;
      }

      toast.error(errorMessage);
    }
  };

  const isSaving = updateMutation.isPending;

  return (
    <Card>
      <CardHeader>
        <CardTitle>Cấu hình Tiêu chí Xét tuyển</CardTitle>
        <CardDescription>
          Thiết lập điểm sàn, cách tính điểm và tổ hợp môn
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        
        {/* Row 1: Thresholds */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="space-y-2">
            <Label htmlFor="minGpa">Điểm sàn học bạ (Min GPA)</Label>
            <Input 
              id="minGpa" 
              type="number" 
              step="0.1" 
              placeholder="Vd: 6.0"
              value={minGpa}
              onChange={(e) => setMinGpa(e.target.value)}
            />
            <p className="text-xs text-muted-foreground">Thang điểm 10</p>
          </div>
          <div className="space-y-2">
            <Label htmlFor="minScore">Điểm chuẩn (Min Score)</Label>
            <Input 
              id="minScore" 
              type="number" 
              step="0.1" 
              placeholder="Vd: 18.0"
              value={minScore}
              onChange={(e) => setMinScore(e.target.value)}
            />
            <p className="text-xs text-muted-foreground">Tổng điểm xét tuyển</p>
          </div>
          <div className="space-y-2">
            <Label htmlFor="minSubjectScore">Điểm liệt (Min Subject)</Label>
            <Input 
              id="minSubjectScore" 
              type="number" 
              step="0.1" 
              placeholder="Vd: 1.0"
              value={minSubjectScore}
              onChange={(e) => setMinSubjectScore(e.target.value)}
            />
            <p className="text-xs text-muted-foreground">Điểm tối thiểu mỗi môn</p>
          </div>
        </div>

        {/* Row 2: Method Config */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="space-y-2">
            <Label>Cách tính điểm</Label>
            <Select 
              value={scoringMethod} 
              onValueChange={(val: "sum" | "avg") => setScoringMethod(val)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="sum">Tổng điểm (3 môn)</SelectItem>
                <SelectItem value="avg">Điểm trung bình</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Chế độ chọn môn</Label>
            <Select 
              value={selectionMode} 
              onValueChange={(val: "fixed" | "dynamic") => setSelectionMode(val)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="fixed">Cố định (Theo tổ hợp)</SelectItem>
                <SelectItem value="dynamic">Linh hoạt (Best N)</SelectItem>
              </SelectContent>
            </Select>
          </div>
           <div className="space-y-2">
            <Label htmlFor="maxScore">Thang điểm tối đa</Label>
             <Input 
              id="maxScore" 
              type="number" 
              step="1" 
              placeholder="Vd: 30"
              value={maxScore}
              onChange={(e) => setMaxScore(e.target.value)}
            />
            <p className="text-xs text-muted-foreground">Vd: 30, 1200</p>
          </div>
        </div>

        {/* Validity Config */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
           <div className="space-y-2">
            <Label htmlFor="policyVersion">Phiên bản Quy chế</Label>
             <Input 
              id="policyVersion" 
              placeholder="Vd: 2025.1"
              value={policyVersion}
              onChange={(e) => setPolicyVersion(e.target.value)}
            />
          </div>
           <div className="space-y-2">
            <Label htmlFor="effectiveFrom">Hiệu lực từ ngày</Label>
             <Input 
              id="effectiveFrom" 
              type="date"
              value={effectiveFrom}
              onChange={(e) => setEffectiveFrom(e.target.value)}
            />
          </div>
           <div className="space-y-2">
            <Label htmlFor="effectiveTo">Đến ngày (Tùy chọn)</Label>
             <Input 
              id="effectiveTo" 
              type="date"
              value={effectiveTo}
              onChange={(e) => setEffectiveTo(e.target.value)}
            />
          </div>
        </div>

        {/* Conditions */}
         <div className="space-y-2">
          <Label htmlFor="conditions">Điều kiện phụ / Ghi chú</Label>
          <Textarea 
            id="conditions" 
            placeholder="Nhập ghi chú hoặc điều kiện phụ (nếu có)..."
            value={conditions}
            onChange={(e) => setConditions(e.target.value)}
            rows={3}
          />
        </div>

        {/* Subject Groups Selection */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label>Tổ hợp môn được phép</Label>
            <span className="text-xs text-muted-foreground">
              Đã chọn: {selectedGroups.length} tổ hợp
            </span>
          </div>

          {/* Selected Groups as Chips */}
          {selectedGroupsDetails.length > 0 && (
            <div className="flex flex-wrap gap-2 p-3 bg-blue-50 border border-blue-200 rounded-md">
              {selectedGroupsDetails.map((group: any) => (
                <Badge
                  key={group.id}
                  variant="secondary"
                  className="flex items-center gap-1 px-2 py-1 bg-blue-100 text-blue-800 hover:bg-blue-200"
                >
                  <span className="font-medium">{group.code}</span>
                  <span className="text-xs opacity-75">({group.name})</span>
                  <button
                    type="button"
                    onClick={() => handleRemoveGroup(group.id)}
                    className="ml-1 hover:bg-blue-300 rounded-full p-0.5"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </Badge>
              ))}
            </div>
          )}

          {/* Search Input */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Tìm kiếm tổ hợp môn (mã hoặc tên môn)..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery("")}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 hover:bg-gray-100 rounded-full p-1"
              >
                <X className="h-4 w-4 text-muted-foreground" />
              </button>
            )}
          </div>

          {/* Scrollable List */}
          <div className="border rounded-md">
            <div className="grid grid-cols-2 md:grid-cols-3 gap-2 p-4 max-h-60 overflow-y-auto">
              {loadingGroups ? (
                <div className="col-span-3 flex justify-center py-4">
                  <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                </div>
              ) : filteredGroups.length === 0 ? (
                <div className="col-span-3 text-center py-4 text-muted-foreground text-sm">
                  Không tìm thấy tổ hợp môn nào phù hợp với "{searchQuery}"
                </div>
              ) : (
                filteredGroups.map((group: any) => (
                  <div key={group.id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`group-${group.id}`}
                      checked={selectedGroups.includes(group.id)}
                      onCheckedChange={() => handleGroupToggle(group.id)}
                    />
                    <Label
                      htmlFor={`group-${group.id}`}
                      className="text-sm font-normal cursor-pointer"
                    >
                      {group.code} <span className="text-xs text-muted-foreground">({group.name})</span>
                    </Label>
                  </div>
                ))
              )}
            </div>
          </div>

          <p className="text-xs text-muted-foreground">
            Chọn các tổ hợp môn thí sinh có thể dùng để xét tuyển.
          </p>
        </div>

        {/* Actions */}
        <div className="flex justify-between pt-4">
          <Button variant="outline" onClick={onBack} disabled={isSaving}>
            <ArrowLeft className="h-4 w-4 mr-2" />
            Quay lại
          </Button>
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving ? (
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <Save className="h-4 w-4 mr-2" />
            )}
            Lưu & Tiếp tục
            <ArrowRight className="h-4 w-4 ml-2" />
          </Button>
        </div>

      </CardContent>
    </Card>
  );
}

"use client";

import { useState, useMemo } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Loader2, ArrowLeft, Archive, AlertTriangle, Info } from "lucide-react";
import { toast } from "sonner";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

import { useUpdatePathDocuments, usePathDocuments } from "@/hooks/admissions/useAdmissionPaths";
import { useDocumentTypes } from "@/hooks/admissions/useMasterData";
import { AdmissionPathResponse } from "@/lib/zod/admission-path";

interface ConfigDocumentsProps {
  path: AdmissionPathResponse;
  onFinish: () => void;
  onBack: () => void;
}

interface DocSelection {
  document_type_id: number;
  is_mandatory: boolean;
  requires_upload: boolean;
  submission_format: string | null;
  display_order: number;
}

export function ConfigDocuments({ path, onFinish, onBack }: ConfigDocumentsProps) {
  // Queries
  const { data: allDocTypes = [], isLoading: loadingTypes } = useDocumentTypes();
  const { data: resolvedDocs, isLoading: loadingResolved } = usePathDocuments(path.id);
  const updateMutation = useUpdatePathDocuments();

  // ✅ Section 2.6.8: Derive initial selections from API data using useMemo
  const initialSelections = useMemo(() => {
    if (!resolvedDocs) return {};
    const initialMap: Record<number, DocSelection> = {};
    resolvedDocs.forEach((doc) => {
      initialMap[doc.document_type_id] = {
        document_type_id: doc.document_type_id,
        is_mandatory: doc.is_mandatory,
        requires_upload: doc.requires_upload,
        submission_format: doc.submission_format,
        display_order: doc.display_order
      };
    });
    return initialMap;
  }, [resolvedDocs]);

  // Local modifications state - starts empty, merged with initial on save
  const [modifications, setModifications] = useState<Record<number, DocSelection | null>>({});

  // Computed current selections: initial + modifications
  const selections = useMemo(() => {
    const result = { ...initialSelections };
    Object.entries(modifications).forEach(([id, mod]) => {
      const numId = Number(id);
      if (mod === null) {
        delete result[numId]; // Removed by user
      } else if (mod) {
        result[numId] = mod; // Added or updated by user
      }
    });
    return result;
  }, [initialSelections, modifications]);

  // Handlers
  const handleSelect = (typeId: number, checked: boolean) => {
    if (checked) {
      // Add new or restore from initial
      const existing = initialSelections[typeId];
      setModifications(prev => ({
        ...prev,
        [typeId]: existing ?? {
          document_type_id: typeId,
          is_mandatory: true,
          requires_upload: true,
          submission_format: null,
          display_order: Object.keys(selections).length + 1
        }
      }));
    } else {
      // Mark as removed
      setModifications(prev => ({
        ...prev,
        [typeId]: null
      }));
    }
  };

  const handleUpdate = <K extends keyof DocSelection>(typeId: number, field: K, value: DocSelection[K]) => {
    const current = selections[typeId];
    if (!current) return;
    
    setModifications(prev => ({
      ...prev,
      [typeId]: {
        ...current,
        [field]: value
      }
    }));
  };

  const handleSave = async () => {
    const selectedCount = Object.keys(selections).length;

    // Validation - at least one document should be selected
    if (selectedCount === 0) {
      toast.warning("Vui lòng chọn ít nhất một loại hồ sơ");
      return;
    }

    try {
      const payload = Object.values(selections);
      console.log("ConfigDocuments: Saving payload:", payload);

      await updateMutation.mutateAsync({
        pathId: path.id,
        data: payload
      });

      toast.success(`Đã lưu cấu hình hồ sơ thành công (${selectedCount} loại)`);
      // Move to review step after successful save
      onFinish();
    } catch (error: any) {
      console.error("ConfigDocuments: Save error:", error);
      console.error("ConfigDocuments: Error response:", error?.response?.data);

      // Extract validation error details
      const errorDetail = error?.response?.data?.detail;
      let errorMessage = "Lưu thất bại. Vui lòng thử lại.";

      if (Array.isArray(errorDetail)) {
        errorMessage = errorDetail.map((e: any) => `${e.loc?.join('.')}: ${e.msg}`).join(", ");
      } else if (typeof errorDetail === "string") {
        errorMessage = errorDetail;
      }

      toast.error(errorMessage);
    }
  };

  const isLoading = loadingTypes || loadingResolved;
  const isSaving = updateMutation.isPending;

  // Groupdoc types for easier selection? Or just list?
  // Flat list for now
  
  // Detachment check: If ANY resolved doc has source="method_override", we are detached.
  const isDetached = resolvedDocs?.some(doc => doc.source === "method_override");

  return (
    <Card>
      <CardHeader>
        <CardTitle>Cấu hình Hồ sơ Yêu cầu</CardTitle>
        <CardDescription>
          Chọn các loại giấy tờ thí sinh cần nộp cho đợt tuyển sinh này.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        
        {/* Detachment Warning/Info */}
        {!isLoading && (
          <div className="mb-4">
            {isDetached ? (
              <Alert className="bg-blue-50 text-blue-900 border-blue-200">
                <Info className="h-4 w-4" />
                <AlertTitle>Cấu hình riêng biệt (Forked)</AlertTitle>
                <AlertDescription>
                  Phương thức này đang sử dụng cấu hình hồ sơ riêng, không còn đồng bộ với cấu hình chung (Shared Defaults).
                </AlertDescription>
              </Alert>
            ) : (
              <Alert className="bg-yellow-50 text-yellow-900 border-yellow-200">
                <AlertTriangle className="h-4 w-4" />
                <AlertTitle>Chú ý: Ghi đè cấu hình chung</AlertTitle>
                <AlertDescription>
                  Hiện tại đang sử dụng cấu hình chung. Nếu bạn điều chỉnh và <strong>Lưu</strong>, 
                  hồ sơ này sẽ tách ra (Fork) và <strong>không còn tự động cập nhật</strong> theo cấu hình chung nữa.
                </AlertDescription>
              </Alert>
            )}
          </div>
        )}
        {isLoading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <div className="space-y-6">
            <div className="border rounded-lg overflow-hidden">
              <div className="grid grid-cols-12 bg-muted/50 p-3 text-sm font-medium border-b">
                <div className="col-span-6">Loại giấy tờ</div>
                <div className="col-span-2 text-center">Bắt buộc</div>
                <div className="col-span-2 text-center">Yêu cầu up file</div>
                <div className="col-span-2 text-center">Thứ tự</div>
              </div>
              
              <div className="max-h-[400px] overflow-y-auto">
                {allDocTypes.map((type: any) => {
                  const isSelected = !!selections[type.id];
                  const current = selections[type.id];

                  return (
                    <div 
                      key={type.id} 
                      className={`grid grid-cols-12 p-3 items-center border-b last:border-0 hover:bg-slate-50 ${isSelected ? 'bg-blue-50/30' : ''}`}
                    >
                      <div className="col-span-6 flex items-center gap-3">
                        <Checkbox 
                          id={`doc-${type.id}`}
                          checked={isSelected}
                          onCheckedChange={(checked) => handleSelect(type.id, checked as boolean)}
                        />
                        <div className="grid gap-0.5">
                          <Label 
                            htmlFor={`doc-${type.id}`}
                            className="text-sm font-medium cursor-pointer"
                          >
                            {type.name}
                          </Label>
                          <span className="text-xs text-muted-foreground">{type.code}</span>
                        </div>
                        {isSelected && resolvedDocs?.find(d => d.document_type_id === type.id)?.source === 'shared' && (
                          <Badge variant="secondary" className="text-[10px] h-5">Mặc định</Badge>
                        )}
                      </div>

                      <div className="col-span-2 flex justify-center">
                        <Checkbox 
                          checked={current?.is_mandatory || false}
                          disabled={!isSelected}
                          onCheckedChange={(c) => handleUpdate(type.id, 'is_mandatory', c)}
                        />
                      </div>

                      <div className="col-span-2 flex justify-center">
                        <Checkbox 
                          checked={current?.requires_upload || false}
                          disabled={!isSelected}
                          onCheckedChange={(c) => handleUpdate(type.id, 'requires_upload', c)}
                        />
                      </div>
                      
                      <div className="col-span-2 flex justify-center text-xs text-muted-foreground">
                         {current?.display_order || "-"}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Actions */}
            <div className="flex justify-between pt-4">
              <Button variant="outline" onClick={onBack} disabled={isSaving}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Quay lại
              </Button>
              <Button onClick={handleSave} disabled={isSaving}>
                {isSaving ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <Archive className="h-4 w-4 mr-2" />
                )}
                Lưu & Tiếp tục
              </Button>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

