/**
 * PathWizard Component
 *
 * Phase 3: Admission Path Creation/Editing Wizard
 * Multi-step wizard for complete admission path configuration:
 * - Step 1: Basic info (method selection)
 * - Step 2: Criteria configuration
 * - Step 3: Document requirements
 */

"use client";

import { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ChevronLeft, Loader2, ArrowRight, CheckCircle2, Circle } from "lucide-react";
import { toast } from "sonner";
import {
  useAdmissionPath,
  useCreateAdmissionPath,
  useUpdateAdmissionPath,
} from "@/hooks/admissions/useAdmissionPaths";
import { useAdmissionMethods } from "@/hooks/admissions/useMasterData";
import { ConfigCriteria } from "./ConfigCriteria";
import { ConfigDocuments } from "./ConfigDocuments";
import { ConfigReview } from "./ConfigReview";
import type { SelectionContext, Phase3View, AdmissionMethod } from "../shared/types";
import type { AxiosError } from "axios";

// ============================================
// TYPES
// ============================================

interface PathWizardProps {
  context: SelectionContext;
  pathId?: number;
  onNavigate: (view: Phase3View) => void;
  initialStep?: 1 | 2 | 3;
}

// ============================================
// COMPONENTS
// ============================================

function StepIndicator({ currentStep, step, title }: { currentStep: number; step: number; title: string }) {
  const isCompleted = currentStep > step;
  const isCurrent = currentStep === step;

  return (
    <div className={`flex items-center gap-2 ${isCurrent ? "text-primary font-medium" : "text-muted-foreground"}`}>
      {isCompleted ? (
        <CheckCircle2 className="h-5 w-5 text-green-600" />
      ) : isCurrent ? (
        <div className="h-5 w-5 rounded-full border-2 border-primary flex items-center justify-center text-xs">
          {step}
        </div>
      ) : (
        <Circle className="h-5 w-5" />
      )}
      <span className={isCurrent ? "text-foreground" : ""}>{title}</span>
      {step < 4 && <div className="w-8 h-[1px] bg-border mx-2" />}
    </div>
  );
}

export function PathWizard({ context, pathId, onNavigate, initialStep = 1 }: PathWizardProps) {
  // Wizard State
  const [step, setStep] = useState<number>(initialStep);
  const [activePathId, setActivePathId] = useState<number | undefined>(pathId);

  // Router and params for URL synchronization
  const router = useRouter();
  const searchParams = useSearchParams();

  // Update URL when step changes
  useEffect(() => {
    const currentStep = searchParams.get('wizardStep');
    if (currentStep !== step.toString()) {
      const params = new URLSearchParams(searchParams.toString());
      params.set('wizardStep', step.toString());
      router.replace(`?${params.toString()}`, { scroll: false });
    }
  }, [step, searchParams, router]);

  // Fetch data
  const { data: path, isLoading: loadingPath } = useAdmissionPath(activePathId);
  const { data: methods = [], isLoading: loadingMethods } = useAdmissionMethods();
  const createMutation = useCreateAdmissionPath();
  const updateMutation = useUpdateAdmissionPath();

  // Form State (Step 1)
  const [displayName, setDisplayName] = useState("");
  const [selectedMethodId, setSelectedMethodId] = useState<number | null>(null);
  const [displayOrder, setDisplayOrder] = useState(1);
  const [visibility, setVisibility] = useState<"public" | "internal">("internal");

  // Sync form state when path data loads
  useEffect(() => {
    if (path) {
      setDisplayName(path.display_name || "");
      setSelectedMethodId(path.admission_method?.id || null);
      setDisplayOrder(path.display_order || 1);
      setVisibility(path.visibility || "internal");
      setActivePathId(path.id);
    }
  }, [path]);

  // Step 1 Handler: Create/Update Basic Info
  const handleSaveBasic = async () => {
    if (!selectedMethodId) {
      toast.error("Vui lòng chọn phương thức tuyển sinh");
      return;
    }

    try {
      let savedId = activePathId;

      if (activePathId) {
        // Update existing
        await updateMutation.mutateAsync({
          pathId: activePathId,
          data: {
            display_name: displayName || undefined,
            display_order: displayOrder,
            visibility: visibility,
          },
        });
        toast.success("Cập nhật thông tin cơ bản thành công");
      } else {
        // Create new
        const newPath = await createMutation.mutateAsync({
          academic_info_id: context.academicInfoId,
          admission_method_id: selectedMethodId,
          display_name: displayName || undefined,
          display_order: displayOrder,
          visibility: visibility,
        });
        savedId = newPath.id;
        setActivePathId(savedId);
        toast.success("Tạo đợt tuyển sinh thành công");
      }

      // Note: Query cache is automatically updated by mutation hooks via setQueryData
      // No need for manual invalidation here

      // Move to Step 2
      setStep(2);
    } catch (error) {
      const axiosError = error as AxiosError<{ detail?: string }>;
      toast.error(axiosError.response?.data?.detail || "Lưu thất bại");
    }
  };

  const handleBackToList = () => {
    onNavigate({ type: "list" });
  };

  const isSavingBasic = createMutation.isPending || updateMutation.isPending;
  const isLoading = (!!activePathId && loadingPath) || loadingMethods;

  // ... (previous code)

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      {/* Header & Stepper */}
      <div>
        <div className="flex items-center gap-2 mb-4">
          <Button variant="ghost" size="sm" onClick={handleBackToList}>
            <ChevronLeft className="h-4 w-4 mr-1" />
            Quay lại Danh sách
          </Button>
        </div>
        
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold">
            {activePathId ? "Cấu hình Đợt Tuyển sinh" : "Thêm mới Đợt Tuyển sinh"}
          </h1>
          {/* Stepper */}
          <div className="flex items-center">
            <StepIndicator currentStep={step} step={1} title="Cơ bản" />
            <StepIndicator currentStep={step} step={2} title="Tiêu chí" />
            <StepIndicator currentStep={step} step={3} title="Hồ sơ" />
            <StepIndicator currentStep={step} step={4} title="Hoàn tất" />
          </div>
        </div>
      </div>

      {/* Logic for Steps */}
      {step === 1 && (
        <Card>
          <CardHeader>
            <CardTitle>Bước 1: Thông tin Cơ bản</CardTitle>
            <CardDescription>
              Chọn phương thức tuyển sinh và tên hiển thị
            </CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="flex justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
              </div>
            ) : (
              <div className="space-y-6">
                <div className="space-y-2">
                  <Label htmlFor="method">
                    Phương thức Tuyển sinh <span className="text-destructive">*</span>
                  </Label>
                  <Select
                    value={selectedMethodId?.toString() || ""}
                    onValueChange={(value) => setSelectedMethodId(parseInt(value))}
                    disabled={!!activePathId} // Cannot change method after creation
                  >
                    <SelectTrigger id="method">
                      <SelectValue placeholder="Chọn phương thức" />
                    </SelectTrigger>
                    <SelectContent>
                      {methods.map((method: AdmissionMethod) => (
                        <SelectItem key={method.id} value={method.id.toString()}>
                          {method.name}
                          <span className="text-muted-foreground ml-2">({method.code})</span>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {activePathId && (
                    <p className="text-xs text-muted-foreground">
                      Không thể thay đổi phương thức sau khi tạo
                    </p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="displayName">Tên hiển thị (Tùy chọn)</Label>
                  <Input
                    id="displayName"
                    value={displayName}
                    onChange={(e) => setDisplayName(e.target.value)}
                    placeholder="Để trống để dùng tên phương thức mặc định"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="displayOrder">Thứ tự hiển thị</Label>
                  <Input
                    id="displayOrder"
                    type="number"
                    value={displayOrder}
                    onChange={(e) => setDisplayOrder(parseInt(e.target.value) || 1)}
                    min={1}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="visibility">Hiển thị</Label>
                  <Select
                    value={visibility}
                    onValueChange={(val: "public" | "internal") => setVisibility(val)}
                  >
                    <SelectTrigger id="visibility">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="public">Công khai</SelectItem>
                      <SelectItem value="internal">Nội bộ</SelectItem>
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-muted-foreground">
                    Công khai: Hiển thị cho thí sinh. Nội bộ: Chỉ admin/manager thấy.
                  </p>
                </div>

                <div className="flex justify-end pt-4">
                  <Button onClick={handleSaveBasic} disabled={isSavingBasic}>
                    {isSavingBasic ? (
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    ) : (
                      <ArrowRight className="h-4 w-4 mr-2" />
                    )}
                    {activePathId ? "Cập nhật & Tiếp tục" : "Tạo & Tiếp tục"}
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {step === 2 && path && (
        <ConfigCriteria
          // Force re-mount when path/criteria changes with granular dependencies
          key={`step2-${path.id}-${path.criteria?.id || 'no-criteria'}-${path.criteria?.subject_groups?.length || 0}`}
          path={path}
          onNext={() => setStep(3)}
          onBack={() => setStep(1)}
        />
      )}

      {step === 3 && path && (
        <ConfigDocuments
          // Force re-mount when path changes
          key={`step3-${path.id}-${path.validation_errors?.length || 0}`}
          path={path}
          onFinish={() => setStep(4)}
          onBack={() => setStep(2)}
        />
      )}

      {step === 4 && path && (
        // NEW: Review Step
        <div className="animate-in fade-in slide-in-from-right-4 duration-300">
          <ConfigReview
            key={`step4-${path.id}-${path.status}-${path.validation_errors?.length || 0}`}
            path={path}
            onBack={() => setStep(3)}
            onFinish={handleBackToList}
          />
        </div>
      )}

      {/* Loading State for Steps 2/3/4 if path missing */}
      {step > 1 && !path && (
        <div className="flex justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      )}
    </div>
  );
}

/**
 * CRUDTable - Reusable CRUD Table Component
 *
 * Extracted from admin/config/ConfigClient.tsx pattern
 * Provides full CRUD operations for any entity type
 */

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Plus, Pencil, Trash2 } from "lucide-react";
import { CRUDDialog } from "./CRUDDialog";
import type { BaseEntity, BaseFormData, CRUDTableColumn } from "./types";

// ============================================
// TYPES
// ============================================

// Minimal interface required for CRUD operations
interface CRUDEntity {
  id: number;
  name?: string; // Optional since not all entities have a name field
  is_active: boolean;
}

interface CRUDTableProps<T extends CRUDEntity> {
  title: string;
  description: string;
  icon?: React.ReactNode;
  columns: CRUDTableColumn<T>[];
  data: T[];
  isLoading: boolean;
  onCreate: (data: BaseFormData) => Promise<void>;
  onUpdate: (id: number, data: BaseFormData) => Promise<void>;
  onDelete: (id: number) => Promise<void>;
  renderForm: (
    item: T | null,
    formData: BaseFormData,
    setFormData: (data: BaseFormData) => void,
    isEdit: boolean
  ) => React.ReactNode;
  initialFormData: () => BaseFormData;
  // Optional mapper to transform item to form data (useful for complex objects or type conversions)
  mapItemToFormData?: (item: T) => BaseFormData;
  emptyMessage?: string;
  showActions?: boolean;
  allowCreate?: boolean;
  allowEdit?: boolean;
  allowDelete?: boolean;
}

// ============================================
// COMPONENT
// ============================================

export function CRUDTable<T extends CRUDEntity>({
  title,
  description,
  icon,
  columns,
  data,
  isLoading,
  onCreate,
  onUpdate,
  onDelete,
  renderForm,
  initialFormData,
  mapItemToFormData,
  emptyMessage = "Chưa có dữ liệu. Nhấn \"Thêm mới\" để tạo.",
  showActions = true,
  allowCreate = true,
  allowEdit = true,
  allowDelete = true,
}: CRUDTableProps<T>) {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editItem, setEditItem] = useState<T | null>(null);
  const [formData, setFormData] = useState<BaseFormData>(initialFormData());
  const [isSubmitting, setIsSubmitting] = useState(false);

  // ============================================
  // HANDLERS
  // ============================================

  const handleOpenCreate = () => {
    setEditItem(null);
    setFormData(initialFormData());
    setDialogOpen(true);
  };

  const handleOpenEdit = (item: T) => {
    setEditItem(item);
    if (mapItemToFormData) {
      setFormData(mapItemToFormData(item));
    } else {
      // Default mapping for BaseEntity types
      const baseItem = item as any;
      setFormData({
        code: baseItem.code || "",
        name: baseItem.name || "",
        description: baseItem.description || "",
        display_order: baseItem.display_order || 0,
        is_active: baseItem.is_active,
      });
    }
    setDialogOpen(true);
  };

  const handleDelete = async (id: number, name?: string) => {
    const itemLabel = name || `item #${id}`;
    if (confirm(`Bạn có chắc chắn muốn xóa "${itemLabel}"?`)) {
      try {
        await onDelete(id);
      } catch (error) {
        console.error("Delete failed:", error);
      }
    }
  };

  const handleCloseDialog = () => {
    setDialogOpen(false);
    setEditItem(null);
    setFormData(initialFormData());
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      if (editItem) {
        await onUpdate(editItem.id, formData);
      } else {
        await onCreate(formData);
      }
      handleCloseDialog();
    } catch (error) {
      // Error handling is done in parent via toast
      console.error("CRUD operation failed:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  // ============================================
  // RENDER COLUMN VALUE
  // ============================================

  const renderColumnValue = (item: T, column: CRUDTableColumn<T>) => {
    if (column.render) {
      return column.render(item);
    }

    const value = item[column.key as keyof T];

    // Handle special cases
    if (column.key === 'code') {
      return (
        <code className="bg-muted rounded px-2 py-1 text-xs font-mono">
          {String(value)}
        </code>
      );
    }

    if (column.key === 'is_active' || column.key === 'status') {
      const isActive = value === true || value === 'active';
      return (
        <Badge variant={isActive ? "default" : "secondary"}>
          {isActive ? "Hoạt động" : "Ngưng hoạt động"}
        </Badge>
      );
    }

    if (value === null || value === undefined) {
      return <span className="text-muted-foreground">—</span>;
    }

    return String(value);
  };

  // ============================================
  // RENDER
  // ============================================

  return (
    <>
      <div className="space-y-4">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            {icon}
            <div>
              <h3 className="text-lg font-semibold">{title}</h3>
              <p className="text-sm text-muted-foreground">{description}</p>
            </div>
          </div>
          {allowCreate && (
            <Button onClick={handleOpenCreate}>
              <Plus className="mr-2 h-4 w-4" />
              Thêm mới
            </Button>
          )}
        </div>

        {/* Table */}
        {isLoading ? (
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-12 w-full" />
            ))}
          </div>
        ) : data.length === 0 ? (
          <div className="text-muted-foreground py-8 text-center border rounded-lg">
            {emptyMessage}
          </div>
        ) : (
          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  {columns.map((column) => (
                    <TableHead key={String(column.key)} style={{ width: column.width }}>
                      {column.header}
                    </TableHead>
                  ))}
                  {showActions && (allowEdit || allowDelete) && (
                    <TableHead className="w-[120px] text-right">Thao tác</TableHead>
                  )}
                </TableRow>
              </TableHeader>
              <TableBody>
                {data.map((item) => {
                  const isGroupHeader = (item as any).isGroupHeader;

                  return (
                    <TableRow key={item.id} className={isGroupHeader ? "bg-muted/30" : ""}>
                      {columns.map((column) => (
                        <TableCell key={String(column.key)}>
                          {renderColumnValue(item, column)}
                        </TableCell>
                      ))}
                      {showActions && (allowEdit || allowDelete) && (
                        <TableCell className="text-right">
                          {!isGroupHeader && (
                            <div className="flex justify-end gap-2">
                              {allowEdit && (
                                <Button
                                  key="edit"
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => handleOpenEdit(item)}
                                >
                                  <Pencil className="h-4 w-4" />
                                </Button>
                              )}
                              {allowDelete && (
                                <Button
                                  key="delete"
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => handleDelete(item.id, item.name)}
                                >
                                  <Trash2 className="h-4 w-4 text-destructive" />
                                </Button>
                              )}
                            </div>
                          )}
                        </TableCell>
                      )}
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </div>

      {/* Dialog */}
      <CRUDDialog
        open={dialogOpen}
        onClose={handleCloseDialog}
        title={editItem ? `Edit ${title}` : `Create ${title}`}
        isEdit={!!editItem}
        onSubmit={handleSubmit}
        isSubmitting={isSubmitting}
      >
        {renderForm(editItem, formData, setFormData, !!editItem)}
      </CRUDDialog>
    </>
  );
}

/**
 * Shared Types for Admission Config
 *
 * Common interfaces and types used across all admission config components
 */

// ============================================
// BASE TYPES
// ============================================

export interface BaseEntity {
  id: number;
  code: string;
  name: string;
  description?: string | null;
  display_order: number;
  is_active: boolean;
  created_at?: string;
  updated_at?: string;
}

export interface BaseEntityCreate {
  code: string;
  name: string;
  description?: string;
  display_order?: number;
  is_active?: boolean;
}

export interface BaseEntityUpdate {
  name?: string;
  description?: string;
  display_order?: number;
  is_active?: boolean;
}

// Form data type for CRUD operations - uses string/number/boolean for form inputs
export interface BaseFormData {
  code?: string;
  name?: string;
  name_vi?: string;
  name_en?: string;
  degree_level?: string;
  description?: string;
  display_order?: number;
  is_active?: boolean;
  requires_gpa?: boolean;
  requires_subject_scores?: boolean;
  organization_unit_id?: number | null;
  unit_id?: number | null;
  program_id?: number | null; // Updated from major_program_id to match backend
  offering_type_id?: number | null;
  offering_id?: number | null;
  academic_year?: number;
  tuition_fee_per_year?: number;
  annual_admission_quota?: number;
  is_published?: boolean;
  is_heavy?: boolean;
  scoring_rules?: ScoringRules;
  [key: string]: string | number | boolean | null | undefined | ScoringRules;
}

// ============================================
// STATE MACHINE TYPES
// ============================================

export type Phase1Step =
  | 'units'
  | 'offering-types'
  | 'methods'
  | 'document-types'
  | 'subject-groups';

export type Phase2Step =
  | 'majors'
  | 'offerings'
  | 'academic-info';

export interface SelectionContext {
  academicYear: number;
  majorProgramId: number;
  offeringId: number;
  academicInfoId: number;
}

export type Phase3View =
  | { type: 'list' }
  | { type: 'matrix' }
  | { type: 'wizard'; pathId?: number; wizardStep?: number };

export type AdmissionConfigState =
  | { type: 'welcome' }
  | { type: 'phase1'; step: Phase1Step }
  | { type: 'phase2'; step: Phase2Step }
  | { type: 'select-context' }
  | { type: 'phase3'; context: SelectionContext; view: Phase3View };

// ============================================
// NAVIGATION TYPES
// ============================================

export interface NavigationTarget {
  state: AdmissionConfigState;
  replace?: boolean;
}

export interface PhaseProgress {
  completed: number;
  total: number;
  steps: StepStatus[];
}

export interface StepStatus {
  id: string;
  label: string;
  status: 'completed' | 'in-progress' | 'pending';
  enabled: boolean;
}

export interface CoverageSummary {
  totalPaths: number;
  readyPaths: number;
  allReady: boolean;
}

// ============================================
// CRUD TABLE TYPES
// ============================================

export interface CRUDTableAction<T> {
  label: string;
  icon?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
  onClick: (item: T) => void;
  show?: (item: T) => boolean;
}

export interface CRUDTableColumn<T> {
  key: keyof T | string;
  header: string;
  render?: (item: T) => React.ReactNode;
