// src/app/(dashboard)/admin/tuition-discount/_components/TuitionDiscountClient.tsx
"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { format } from "date-fns";
import { vi } from "date-fns/locale";
import { CalendarIcon, Loader2, Pencil, Plus, Trash2, Percent, Banknote } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { PageContainer } from "@/components/layouts/PageContainer";
import { PageHeader } from "@/components/layouts/PageHeader";
import { cn } from "@/lib/utils";

import {
  useTuitionDiscountPolicies,
  useCreateTuitionDiscountPolicy,
  useUpdateTuitionDiscountPolicy,
  useDeleteTuitionDiscountPolicy,
} from "@/hooks/useTuitionDiscount";
import type {
  TuitionDiscountPolicy,
  TuitionDiscountPolicyCreate,
  TuitionDiscountPolicyListResponse,
  DiscountType,
} from "@/types/tuition-discount.types";

// =============================================================================
// FORM SCHEMA
// =============================================================================

const policyFormSchema = z.object({
  code: z
    .string()
    .min(1, "Mã chính sách là bắt buộc")
    .max(50, "Mã không quá 50 ký tự")
    .regex(/^[A-Z0-9_]+$/, "Chỉ chữ in hoa, số và dấu gạch dưới"),
  name: z.string().min(1, "Tên chính sách là bắt buộc").max(200),
  description: z.string().max(2000).optional(),
  discount_type: z.enum(["amount", "percentage"]),
  discount_value: z.number().min(0, "Giá trị phải >= 0"),
  valid_from: z.date().optional().nullable(),
  valid_to: z.date().optional().nullable(),
  is_stackable: z.boolean(),
  priority: z.number().int().min(0),
  max_usage: z.number().int().min(0).optional().nullable(),
  is_active: z.boolean(),
  // JSON fields - applicable_scope
  all_programs: z.boolean(),
  is_heavy_only: z.boolean(),
  degree_levels: z.string().optional(), // Comma-separated: "Cao đẳng, Trung cấp"
  major_program_codes: z.string().optional(), // Comma-separated: "6480201, 6510301"
  offering_types: z.string().optional(), // Comma-separated: "Chính quy, Liên thông"
});

type PolicyFormValues = z.infer<typeof policyFormSchema>;

// =============================================================================
// CLIENT COMPONENT
// =============================================================================

interface TuitionDiscountClientProps {
  initialData?: TuitionDiscountPolicyListResponse;
}

export function TuitionDiscountClient({ initialData }: TuitionDiscountClientProps) {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editPolicy, setEditPolicy] = useState<TuitionDiscountPolicy | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [policyToDelete, setPolicyToDelete] = useState<TuitionDiscountPolicy | null>(null);

  // ⚡ Queries & Mutations with initialData support
  const { data, isLoading } = useTuitionDiscountPolicies(
    { includeExpired: true },
    { initialData }
  );
  const createMutation = useCreateTuitionDiscountPolicy();
  const updateMutation = useUpdateTuitionDiscountPolicy();
  const deleteMutation = useDeleteTuitionDiscountPolicy();

  const form = useForm<PolicyFormValues>({
    resolver: zodResolver(policyFormSchema),
    defaultValues: {
      code: "",
      name: "",
      description: "",
      discount_type: "percentage",
      discount_value: 0,
      valid_from: null,
      valid_to: null,
      is_stackable: false,
      priority: 0,
      max_usage: null,
      is_active: true,
      all_programs: true,
      is_heavy_only: false,
      degree_levels: "",
      major_program_codes: "",
      offering_types: "",
    },
  });

  const isEditMode = !!editPolicy;

  const openCreateDialog = () => {
    setEditPolicy(null);
    form.reset({
      code: "",
      name: "",
      description: "",
      discount_type: "percentage",
      discount_value: 0,
      valid_from: null,
      valid_to: null,
      is_stackable: false,
      priority: 0,
      max_usage: null,
      is_active: true,
      all_programs: true,
      is_heavy_only: false,
      degree_levels: "",
      major_program_codes: "",
      offering_types: "",
    });
    setDialogOpen(true);
  };

  const openEditDialog = (policy: TuitionDiscountPolicy) => {
    setEditPolicy(policy);
    const scope = policy.applicable_scope || {};
    form.reset({
      code: policy.code,
      name: policy.name,
      description: policy.description || "",
      discount_type: policy.discount_type,
      discount_value: policy.discount_value,
      valid_from: policy.valid_from ? new Date(policy.valid_from) : null,
      valid_to: policy.valid_to ? new Date(policy.valid_to) : null,
      is_stackable: policy.is_stackable,
      priority: policy.priority,
      max_usage: policy.max_usage,
      is_active: policy.is_active,
      all_programs: scope.all_programs || false,
      is_heavy_only: scope.is_heavy_only || false,
      degree_levels: Array.isArray(scope.degree_levels) ? scope.degree_levels.join(", ") : "",
      major_program_codes: Array.isArray(scope.major_program_codes) ? scope.major_program_codes.join(", ") : "",
      offering_types: Array.isArray(scope.offering_types) ? scope.offering_types.join(", ") : "",
    });
    setDialogOpen(true);
  };

  // Helper to parse comma-separated string to array
  const parseCommaSeparated = (value: string | undefined): string[] | undefined => {
    if (!value || value.trim() === "") return undefined;
    return value.split(",").map(s => s.trim()).filter(s => s.length > 0);
  };

  const onSubmit = async (values: PolicyFormValues) => {
    const payload: TuitionDiscountPolicyCreate = {
      code: values.code.toUpperCase(),
      name: values.name,
      description: values.description || null,
      discount_type: values.discount_type as DiscountType,
      discount_value: values.discount_value,
      valid_from: values.valid_from?.toISOString().split("T")[0] || null,
      valid_to: values.valid_to?.toISOString().split("T")[0] || null,
      is_stackable: values.is_stackable,
      priority: values.priority,
      max_usage: values.max_usage || null,
      is_active: values.is_active,
      applicable_scope: {
        all_programs: values.all_programs,
        is_heavy_only: values.is_heavy_only,
        degree_levels: parseCommaSeparated(values.degree_levels),
        major_program_codes: parseCommaSeparated(values.major_program_codes),
        offering_types: parseCommaSeparated(values.offering_types),
      },
      target_criteria: {},
    };

    try {
      if (isEditMode && editPolicy) {
        await updateMutation.mutateAsync({
          id: editPolicy.id,
          data: payload,
        });
      } else {
        await createMutation.mutateAsync(payload);
      }
      setDialogOpen(false);
    } catch {
      // Error handled in hook
    }
  };

  const handleDelete = async () => {
    if (!policyToDelete) return;
    try {
      await deleteMutation.mutateAsync({ id: policyToDelete.id });
      setDeleteDialogOpen(false);
      setPolicyToDelete(null);
    } catch {
      // Error handled in hook
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat("vi-VN", {
      style: "currency",
      currency: "VND",
      maximumFractionDigits: 0,
    }).format(value);
  };

  const isSubmitting = createMutation.isPending || updateMutation.isPending;

  return (
    <PageContainer>
      <PageHeader
        title="Quản lý chính sách ưu đãi học phí"
        description="Thiết lập và quản lý các chính sách ưu đãi, giảm giá học phí"
        icon={<Percent className="h-8 w-8" />}
        actions={
          <Button onClick={openCreateDialog}>
            <Plus className="mr-2 h-4 w-4" />
            Thêm chính sách
          </Button>
        }
      />

      <Card>
        <CardContent>
          {isLoading ? (
            <div className="space-y-3">
              {[...Array(5)].map((_, i) => (
                <Skeleton key={i} className="h-12 w-full" />
              ))}
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Mã</TableHead>
                  <TableHead>Tên chính sách</TableHead>
                  <TableHead>Loại</TableHead>
                  <TableHead>Giá trị</TableHead>
                  <TableHead>Hiệu lực</TableHead>
                  <TableHead>Trạng thái</TableHead>
                  <TableHead className="text-right">Thao tác</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {data?.items.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={7} className="text-muted-foreground text-center py-8">
                      Chưa có chính sách nào. Nhấn &quot;Thêm chính sách&quot; để tạo mới.
                    </TableCell>
                  </TableRow>
                )}
                {data?.items.map((policy) => (
                  <TableRow key={policy.id}>
                    <TableCell className="font-mono text-sm">{policy.code}</TableCell>
                    <TableCell>
                      <div className="font-medium">{policy.name}</div>
                      {policy.description && (
                        <div className="text-muted-foreground text-xs truncate max-w-[300px]">
                          {policy.description}
                        </div>
                      )}
                    </TableCell>
                    <TableCell>
                      {policy.discount_type === "percentage" ? (
                        <Badge variant="secondary">
                          <Percent className="mr-1 h-3 w-3" />
                          Phần trăm
                        </Badge>
                      ) : (
                        <Badge variant="outline">
                          <Banknote className="mr-1 h-3 w-3" />
                          Số tiền
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell className="font-medium">
                      {policy.discount_type === "percentage"
                        ? `${policy.discount_value}%`
                        : formatCurrency(policy.discount_value)}
                    </TableCell>
                    <TableCell>
                      {policy.valid_from || policy.valid_to ? (
                        <div className="text-xs">
                          {policy.valid_from && (
                            <div>Từ: {format(new Date(policy.valid_from), "dd/MM/yyyy")}</div>
                          )}
                          {policy.valid_to && (
                            <div>Đến: {format(new Date(policy.valid_to), "dd/MM/yyyy")}</div>
                          )}
                        </div>
                      ) : (
                        <span className="text-muted-foreground text-xs">Không giới hạn</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {policy.is_active ? (
                        policy.is_expired ? (
                          <Badge variant="destructive">Hết hạn</Badge>
                        ) : (
                          <Badge variant="default">Hoạt động</Badge>
                        )
                      ) : (
                        <Badge variant="secondary">Tạm dừng</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openEditDialog(policy)}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          setPolicyToDelete(policy);
                          setDeleteDialogOpen(true);
                        }}
                      >
                        <Trash2 className="text-destructive h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>
              {isEditMode ? "Chỉnh sửa chính sách" : "Tạo chính sách mới"}
            </DialogTitle>
            <DialogDescription>
              {isEditMode
                ? "Cập nhật thông tin chính sách ưu đãi"
                : "Nhập thông tin để tạo chính sách ưu đãi mới"}
            </DialogDescription>
          </DialogHeader>

          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                {/* Code */}
                <FormField
                  control={form.control}
                  name="code"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Mã chính sách *</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="VD: EARLY_BIRD_2025"
                          {...field}
                          onChange={(e) => field.onChange(e.target.value.toUpperCase())}
                          disabled={isEditMode || isSubmitting}
                          className="uppercase"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Priority */}
                <FormField
                  control={form.control}
                  name="priority"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Độ ưu tiên</FormLabel>
                      <FormControl>
                        <Input
                          type="number"
                          placeholder="0"
                          value={field.value}
                          onChange={(e) => field.onChange(e.target.valueAsNumber || 0)}
                          disabled={isSubmitting}
                        />
                      </FormControl>
                      <FormDescription>Cao hơn = áp dụng trước</FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              {/* Name */}
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Tên chính sách *</FormLabel>
                    <FormControl>
                      <Input
                        placeholder="VD: Ưu đãi đăng ký sớm 2025"
                        {...field}
                        disabled={isSubmitting}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Description */}
              <FormField
                control={form.control}
                name="description"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Mô tả</FormLabel>
                    <FormControl>
                      <Textarea
                        placeholder="Mô tả chi tiết về chính sách..."
                        className="resize-none"
                        {...field}
                        disabled={isSubmitting}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <div className="grid grid-cols-2 gap-4">
                {/* Discount Type */}
                <FormField
                  control={form.control}
                  name="discount_type"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Loại ưu đãi *</FormLabel>
                      <Select
                        onValueChange={field.onChange}
                        value={field.value}
                        disabled={isSubmitting}
                      >
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="percentage">Phần trăm (%)</SelectItem>
                          <SelectItem value="amount">Số tiền (VNĐ)</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Discount Value */}
                <FormField
                  control={form.control}
                  name="discount_value"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Giá trị ưu đãi *</FormLabel>
                      <FormControl>
                        <Input
                          type="number"
                          placeholder={
                            form.watch("discount_type") === "percentage" ? "VD: 15" : "VD: 2000000"
                          }
                          value={field.value}
                          onChange={(e) => field.onChange(e.target.valueAsNumber || 0)}
                          disabled={isSubmitting}
                        />
                      </FormControl>
                      <FormDescription>
                        {form.watch("discount_type") === "percentage"
                          ? "Nhập phần trăm (0-100)"
                          : "Nhập số tiền VNĐ"}
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                {/* Valid From */}
                <FormField
                  control={form.control}
                  name="valid_from"
                  render={({ field }) => (
                    <FormItem className="flex flex-col">
                      <FormLabel>Ngày bắt đầu</FormLabel>
                      <Popover>
                        <PopoverTrigger asChild>
                          <FormControl>
                            <Button
                              variant="outline"
                              className={cn(
                                "pl-3 text-left font-normal",
                                !field.value && "text-muted-foreground"
                              )}
                              disabled={isSubmitting}
                            >
                              {field.value ? (
                                format(field.value, "dd/MM/yyyy", { locale: vi })
                              ) : (
                                <span>Chọn ngày</span>
                              )}
                              <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
                            </Button>
                          </FormControl>
                        </PopoverTrigger>
                        <PopoverContent className="w-auto p-0" align="start">
                          <Calendar
                            mode="single"
                            selected={field.value || undefined}
                            onSelect={field.onChange}
                            locale={vi}
                          />
                        </PopoverContent>
                      </Popover>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Valid To */}
                <FormField
                  control={form.control}
                  name="valid_to"
                  render={({ field }) => (
                    <FormItem className="flex flex-col">
                      <FormLabel>Ngày kết thúc</FormLabel>
                      <Popover>
                        <PopoverTrigger asChild>
                          <FormControl>
                            <Button
                              variant="outline"
                              className={cn(
                                "pl-3 text-left font-normal",
                                !field.value && "text-muted-foreground"
                              )}
                              disabled={isSubmitting}
                            >
                              {field.value ? (
                                format(field.value, "dd/MM/yyyy", { locale: vi })
                              ) : (
                                <span>Chọn ngày</span>
                              )}
                              <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
                            </Button>
                          </FormControl>
                        </PopoverTrigger>
                        <PopoverContent className="w-auto p-0" align="start">
                          <Calendar
                            mode="single"
                            selected={field.value || undefined}
                            onSelect={field.onChange}
                            locale={vi}
                          />
                        </PopoverContent>
                      </Popover>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              {/* Max Usage */}
              <FormField
                control={form.control}
                name="max_usage"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Giới hạn số lượt sử dụng</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        placeholder="Để trống = không giới hạn"
                        {...field}
                        value={field.value ?? ""}
                        onChange={(e) => field.onChange(e.target.value ? Number(e.target.value) : null)}
                        disabled={isSubmitting}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Scope Options */}
              <div className="space-y-3 rounded-lg border p-4">
                <div className="text-sm font-medium">Phạm vi áp dụng</div>

                <FormField
                  control={form.control}
                  name="all_programs"
                  render={({ field }) => (
                    <FormItem className="flex items-center justify-between">
                      <div>
                        <FormLabel>Áp dụng tất cả ngành</FormLabel>
                        <FormDescription>Chính sách áp dụng cho mọi chương trình</FormDescription>
                      </div>
                      <FormControl>
                        <Switch
                          checked={field.value}
                          onCheckedChange={field.onChange}
                          disabled={isSubmitting}
                        />
                      </FormControl>
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="is_heavy_only"
                  render={({ field }) => (
                    <FormItem className="flex items-center justify-between">
                      <div>
                        <FormLabel>Chỉ ngành nặng nhọc, độc hại</FormLabel>
                        <FormDescription>Chỉ áp dụng cho ngành có is_heavy = true</FormDescription>
                      </div>
                      <FormControl>
                        <Switch
                          checked={field.value}
                          onCheckedChange={field.onChange}
                          disabled={isSubmitting || form.watch("all_programs")}
                        />
                      </FormControl>
                    </FormItem>
                  )}
                />

                {/* Additional Scope Options - shown when all_programs is false */}
                {!form.watch("all_programs") && (
                  <div className="space-y-3 border-t pt-3">
                    <FormField
                      control={form.control}
                      name="degree_levels"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Trình độ cụ thể</FormLabel>
                          <FormControl>
                            <Input
                              placeholder="VD: Cao đẳng, Trung cấp"
                              {...field}
                              disabled={isSubmitting}
                            />
                          </FormControl>
                          <FormDescription>Phân cách bằng dấu phẩy</FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="major_program_codes"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Mã ngành cụ thể</FormLabel>
                          <FormControl>
                            <Input
                              placeholder="VD: 6480201, 6510301"
                              {...field}
                              disabled={isSubmitting}
                            />
                          </FormControl>
                          <FormDescription>Phân cách bằng dấu phẩy</FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="offering_types"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Loại hình đào tạo</FormLabel>
                          <FormControl>
                            <Input
                              placeholder="VD: Chính quy, Liên thông"
                              {...field}
                              disabled={isSubmitting}
                            />
                          </FormControl>
                          <FormDescription>Phân cách bằng dấu phẩy</FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                )}
              </div>

              {/* Status Options */}
              <div className="space-y-3 rounded-lg border p-4">
                <FormField
                  control={form.control}
                  name="is_stackable"
                  render={({ field }) => (
                    <FormItem className="flex items-center justify-between">
                      <div>
                        <FormLabel>Cho phép cộng dồn</FormLabel>
                        <FormDescription>Có thể kết hợp với ưu đãi khác</FormDescription>
                      </div>
                      <FormControl>
                        <Switch
                          checked={field.value}
                          onCheckedChange={field.onChange}
                          disabled={isSubmitting}
                        />
                      </FormControl>
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="is_active"
                  render={({ field }) => (
                    <FormItem className="flex items-center justify-between">
                      <div>
                        <FormLabel>Trạng thái hoạt động</FormLabel>
                        <FormDescription>Bật/tắt chính sách này</FormDescription>
                      </div>
                      <FormControl>
                        <Switch
                          checked={field.value}
                          onCheckedChange={field.onChange}
                          disabled={isSubmitting}
                        />
                      </FormControl>
                    </FormItem>
                  )}
                />
              </div>

              <DialogFooter>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setDialogOpen(false)}
                  disabled={isSubmitting}
                >
                  Hủy
                </Button>
                <Button type="submit" disabled={isSubmitting}>
                  {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  {isEditMode ? "Cập nhật" : "Tạo mới"}
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Xác nhận xóa</DialogTitle>
            <DialogDescription>
              Bạn có chắc chắn muốn xóa chính sách &quot;{policyToDelete?.name}&quot;?
              Hành động này không thể hoàn tác.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setDeleteDialogOpen(false)}
              disabled={deleteMutation.isPending}
            >
              Hủy
            </Button>
            <Button
              variant="destructive"
              onClick={handleDelete}
              disabled={deleteMutation.isPending}
            >
              {deleteMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Xóa
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </PageContainer>
  );
}

// src/app/(dashboard)/admin/users/_components/AdminUsersClient.tsx
"use client";

/**
 * ✅ PHASE 1 - WEEK 2 - DAY 1: Admin Users Client Component
 *
 * Complex page with:
 * - TanStack Table with sorting, filtering, pagination
 * - Bulk actions (delete, change status)
 * - Multiple dialogs (create, edit, set password, manage roles)
 * - CSV export
 *
 * Server Component (parent) fetches initial data, this handles all interactivity.
 */

import { useState, useMemo, useCallback } from "react";
import Link from "next/link";
import {
  Plus,
  Search,
  Download,
  Trash2,
  MoreVertical,
  Edit,
  Key,
  Shield,
  CheckSquare,
  Square,
  Eye,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
} from "lucide-react";
import {
  useReactTable,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  ColumnDef,
  flexRender,
} from "@tanstack/react-table";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { getAvatarUrl } from "@/lib/utils";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

import { useAdminUsersList, useAdminDeleteUser, useAdminBulkAction } from "@/hooks/useAdminUsers";
import { UserDialog } from "@/components/admin/UserDialog";
import { SetPasswordDialog } from "@/components/admin/SetPasswordDialog";
import { ManageRolesDialog } from "@/components/admin/ManageRolesDialog";
import type { User } from "@/types/api.types";
import { api } from "@/lib/api/client";
import { API_ENDPOINTS } from "@/lib/api/endpoints";
import { toast } from "sonner";
import type { UsersPage } from "@/types/api.types";

interface AdminUsersClientProps {
  initialData: UsersPage; // ✅ Initial data from server
}

export function AdminUsersClient({ initialData }: AdminUsersClientProps) {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [sortBy, setSortBy] = useState<string>("id");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("asc");
  const [rowSelection, setRowSelection] = useState({});
  const [userToDelete, setUserToDelete] = useState<User | null>(null);
  const [userDialogOpen, setUserDialogOpen] = useState(false);
  const [dialogMode, setDialogMode] = useState<"create" | "edit">("create");
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [setPasswordDialogOpen, setSetPasswordDialogOpen] = useState(false);
  const [setPasswordUser, setSetPasswordUser] = useState<User | null>(null);
  const [manageRolesDialogOpen, setManageRolesDialogOpen] = useState(false);
  const [manageRolesUser, setManageRolesUser] = useState<User | null>(null);
  const [bulkDeleteDialogOpen, setBulkDeleteDialogOpen] = useState(false);

  // ✅ Fetch users with filters and sorting (with initialData)
  const { data, isLoading, error } = useAdminUsersList(
    {
      page,
      page_size: 10,
      search: search || undefined,
      role: roleFilter === "all" ? undefined : roleFilter,
      status: statusFilter === "all" ? undefined : statusFilter,
      sort: sortBy,
      order: sortOrder,
    },
    {
      // ✅ Use initialData only for first page, no filters
      initialData:
        page === 1 && !search && roleFilter === "all" && statusFilter === "all"
          ? initialData
          : undefined,
    }
  );

  const deleteUserMutation = useAdminDeleteUser();
  const bulkActionMutation = useAdminBulkAction();

  // Handle column sorting
  const handleSort = useCallback(
    (column: string) => {
      if (sortBy === column) {
        setSortOrder(sortOrder === "asc" ? "desc" : "asc");
      } else {
        setSortBy(column);
        setSortOrder("asc");
      }
      setPage(1);
    },
    [sortBy, sortOrder]
  );

  // Render sort icon for column header
  const getSortIcon = useCallback(
    (column: string) => {
      if (sortBy !== column) {
        return <ArrowUpDown className="ml-2 h-4 w-4" />;
      }
      return sortOrder === "asc" ? (
        <ArrowUp className="ml-2 h-4 w-4" />
      ) : (
        <ArrowDown className="ml-2 h-4 w-4" />
      );
    },
    [sortBy, sortOrder]
  );

  // Table columns definition
  const columns = useMemo<ColumnDef<User>[]>(
    () => [
      {
        id: "select",
        header: ({ table }) => (
          <Checkbox
            checked={table.getIsAllPageRowsSelected()}
            onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
            aria-label="Chọn tất cả"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(!!value)}
            aria-label="Chọn dòng"
          />
        ),
        enableSorting: false,
        enableHiding: false,
      },
      {
        accessorKey: "user",
        header: "Người dùng",
        cell: ({ row }) => {
          const user = row.original;
          return (
            <div className="flex items-center gap-3">
              <Avatar>
                <AvatarImage src={getAvatarUrl(user.avatar_url)} alt={user.username} />
                <AvatarFallback>{user.username.slice(0, 2).toUpperCase()}</AvatarFallback>
              </Avatar>
              <div>
                <p className="font-medium">{user.full_name || user.username}</p>
                <p className="text-muted-foreground text-sm">@{user.username}</p>
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "email",
        header: () => (
          <Button variant="ghost" onClick={() => handleSort("email")} className="-ml-4 h-8">
            Email
            {getSortIcon("email")}
          </Button>
        ),
      },
      {
        accessorKey: "role",
        header: () => (
          <Button variant="ghost" onClick={() => handleSort("role")} className="-ml-4 h-8">
            Vai trò
            {getSortIcon("role")}
          </Button>
        ),
        cell: ({ row }) => {
          const role = row.original.role;
          const variant =
            role === "admin" ? "default" : role === "manager" ? "secondary" : "outline";
          return <Badge variant={variant}>{role}</Badge>;
        },
      },
      {
        accessorKey: "status",
        header: () => (
          <Button variant="ghost" onClick={() => handleSort("status")} className="-ml-4 h-8">
            Trạng thái
            {getSortIcon("status")}
          </Button>
        ),
        cell: ({ row }) => {
          const status = row.original.status;
          const variant =
            status === "active" ? "default" : status === "pending" ? "secondary" : "destructive";
          return <Badge variant={variant}>{status}</Badge>;
        },
      },
      {
        id: "actions",
        cell: ({ row }) => {
          const user = row.original;
          return (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon">
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuLabel>Thao tác</DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuItem asChild>
                  <Link href={`/admin/users/${user.id}`}>
                    <Eye className="mr-2 h-4 w-4" />
                    Xem chi tiết
                  </Link>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleEditUser(user)}>
                  <Edit className="mr-2 h-4 w-4" />
                  Sửa người dùng
                </DropdownMenuItem>
                <DropdownMenuItem
                  onClick={() => {
                    setSetPasswordUser(user);
                    setSetPasswordDialogOpen(true);
                  }}
                >
                  <Key className="mr-2 h-4 w-4" />
                  Đặt mật khẩu
                </DropdownMenuItem>
                <DropdownMenuItem
                  onClick={() => {
                    setManageRolesUser(user);
                    setManageRolesDialogOpen(true);
                  }}
                >
                  <Shield className="mr-2 h-4 w-4" />
                  Quản lý vai trò
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  className="text-destructive focus:text-destructive"
                  onClick={() => setUserToDelete(user)}
                >
                  <Trash2 className="mr-2 h-4 w-4" />
                  Xoá người dùng
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          );
        },
      },
    ],
    [getSortIcon, handleSort]
  );

  // Setup TanStack Table
  const table = useReactTable({
    data: data?.users || [],
    columns,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    onRowSelectionChange: setRowSelection,
    state: {
      rowSelection,
    },
    manualPagination: true,
    pageCount: data ? Math.ceil(data.total_count / 10) : 0,
  });

  const handleEditUser = (user: User) => {
    setSelectedUser(user);
    setDialogMode("edit");
    setUserDialogOpen(true);
  };

  const handleCreateUser = () => {
    setSelectedUser(null);
    setDialogMode("create");
    setUserDialogOpen(true);
  };

  const handleDeleteUser = async () => {
    if (userToDelete) {
      await deleteUserMutation.mutateAsync(userToDelete.id);
      setUserToDelete(null);
    }
  };

  const handleBulkDelete = async () => {
    const selectedRows = table.getFilteredSelectedRowModel().rows;
    const userIds = selectedRows.map((row) => row.original.id);

    if (userIds.length === 0) return;

    await bulkActionMutation.mutateAsync({
      action: "delete",
      user_ids: userIds,
    });

    setRowSelection({});
    setBulkDeleteDialogOpen(false);
  };

  const handleOpenBulkDelete = () => {
    const selectedRows = table.getFilteredSelectedRowModel().rows;
    if (selectedRows.length > 0) {
      setBulkDeleteDialogOpen(true);
    }
  };

  const handleBulkChangeStatus = async (newStatus: "active" | "pending" | "banned") => {
    const selectedRows = table.getFilteredSelectedRowModel().rows;
    const userIds = selectedRows.map((row) => row.original.id);

    if (userIds.length === 0) return;

    await bulkActionMutation.mutateAsync({
      action: "change_status",
      user_ids: userIds,
      status: newStatus,
    });

    setRowSelection({});
  };

  const handleExportCSV = async () => {
    toast.info("Đang xuất CSV...");

    try {
      const params = new URLSearchParams();
      if (search) params.set("search", search);
      if (roleFilter !== "all") params.set("role", roleFilter);
      if (statusFilter !== "all") params.set("status", statusFilter);
      params.set("sort", sortBy);
      params.set("order", sortOrder);

      const url = `${API_ENDPOINTS.ADMIN.USERS.EXPORT_CSV_STREAM}?${params.toString()}`;

      const response = await api.get(url, {
        responseType: "blob",
      });

      const blob = new Blob([response.data], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      const blobUrl = URL.createObjectURL(blob);

      const filename = `users_export_${new Date().toISOString().split("T")[0]}.csv`;

      link.setAttribute("href", blobUrl);
      link.setAttribute("download", filename);
      link.style.visibility = "hidden";
      document.body.appendChild(link);
      link.click();

      document.body.removeChild(link);
      URL.revokeObjectURL(blobUrl);

      toast.success("Xuất CSV thành công.");
    } catch (error) {
      console.error("Error exporting users CSV:", error);
      toast.error("Xuất CSV thất bại");
    }
  };

  const selectedCount = table.getFilteredSelectedRowModel().rows.length;

  if (error) {
    return (
      <div className="space-y-6">
        <header>
          <h1 className="text-3xl font-bold tracking-tight">Quản Lý Người Dùng</h1>
          <p className="text-muted-foreground">Quản lý người dùng, vai trò và quyền hạn.</p>
        </header>
        <Card>
          <CardContent className="pt-6">
            <p className="text-destructive">Lỗi tải người dùng: {error.message}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Quản Lý Người Dùng</h1>
          <p className="text-muted-foreground">Quản lý người dùng, vai trò và quyền hạn.</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleExportCSV} disabled={!data?.users.length}>
            <Download className="mr-2 h-4 w-4" />
            Xuất CSV
          </Button>
          <Button onClick={handleCreateUser}>
            <Plus className="mr-2 h-4 w-4" />
            Thêm Người Dùng
          </Button>
        </div>
      </header>

      {/* Bulk Actions Bar */}
      {selectedCount > 0 && (
        <Card className="border-primary">
          <CardContent className="flex items-center justify-between p-4">
            <div className="flex items-center gap-2">
              <CheckSquare className="text-primary h-5 w-5" />
              <span className="font-medium">{selectedCount} người dùng được chọn</span>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={() => table.resetRowSelection()}>
                <Square className="mr-2 h-4 w-4" />
                Bỏ chọn tất cả
              </Button>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="sm">
                    <Edit className="mr-2 h-4 w-4" />
                    Đổi trạng thái
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuLabel>Đặt trạng thái:</DropdownMenuLabel>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem onClick={() => handleBulkChangeStatus("active")}>
                    Hoạt động
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleBulkChangeStatus("pending")}>
                    Chờ duyệt
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleBulkChangeStatus("banned")}>
                    Bị cấm
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
              <Button variant="destructive" size="sm" onClick={handleOpenBulkDelete}>
                <Trash2 className="mr-2 h-4 w-4" />
                Xoá đã chọn
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Bộ lọc</CardTitle>
          <CardDescription>Tìm kiếm và lọc người dùng</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex flex-col gap-4 md:flex-row">
            <div className="relative flex-1">
              <Search className="text-muted-foreground absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2" />
              <Input
                placeholder="Tìm theo tên hoặc email..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-9"
              />
            </div>
            <Select value={roleFilter} onValueChange={setRoleFilter}>
              <SelectTrigger className="w-full md:w-[180px]">
                <SelectValue placeholder="Tất cả vai trò" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Tất cả vai trò</SelectItem>
                <SelectItem value="admin">Admin</SelectItem>
                <SelectItem value="manager">Quản lý</SelectItem>
                <SelectItem value="officer">Nhân viên</SelectItem>
                <SelectItem value="user">Người dùng</SelectItem>
              </SelectContent>
            </Select>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-full md:w-[180px]">
                <SelectValue placeholder="Tất cả trạng thái" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Tất cả trạng thái</SelectItem>
                <SelectItem value="active">Hoạt động</SelectItem>
                <SelectItem value="pending">Chờ duyệt</SelectItem>
                <SelectItem value="banned">Bị cấm</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Users Table */}
      <Card>
        <CardContent className="p-0">
          {isLoading ? (
            <div className="space-y-2 p-6">
              {Array.from({ length: 5 }).map((_, i) => (
                <Skeleton key={i} className="h-12 w-full" />
              ))}
            </div>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  {table.getHeaderGroups().map((headerGroup) => (
                    <TableRow key={headerGroup.id}>
                      {headerGroup.headers.map((header) => (
                        <TableHead key={header.id}>
                          {header.isPlaceholder
                            ? null
                            : flexRender(header.column.columnDef.header, header.getContext())}
                        </TableHead>
                      ))}
                    </TableRow>
                  ))}
                </TableHeader>
                <TableBody>
                  {table.getRowModel().rows?.length ? (
                    table.getRowModel().rows.map((row) => (
                      <TableRow key={row.id} data-state={row.getIsSelected() && "selected"}>
                        {row.getVisibleCells().map((cell) => (
                          <TableCell key={cell.id}>
                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                          </TableCell>
                        ))}
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={columns.length} className="h-24 text-center">
                        Không tìm thấy người dùng.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Pagination */}
      {data && data.total_count > 10 && (
        <div className="flex items-center justify-between">
          <div className="text-muted-foreground text-sm">
            Hiển thị {(page - 1) * 10 + 1} đến {Math.min(page * 10, data.total_count)} / {data.total_count} người dùng
          </div>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page === 1}
            >
              Trước
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.min(Math.ceil(data.total_count / 10), p + 1))}
              disabled={page === Math.ceil(data.total_count / 10)}
            >
              Sau
            </Button>
          </div>
        </div>
      )}

      {/* Dialogs */}
      <UserDialog
        open={userDialogOpen}
        onOpenChange={setUserDialogOpen}
        user={selectedUser}
        mode={dialogMode}
      />

      {setPasswordUser && (
        <SetPasswordDialog
          open={setPasswordDialogOpen}
          onOpenChange={setSetPasswordDialogOpen}
          user={setPasswordUser}
        />
      )}

      {manageRolesUser && (
        <ManageRolesDialog
          open={manageRolesDialogOpen}
          onOpenChange={setManageRolesDialogOpen}
          user={manageRolesUser}
        />
      )}

      <AlertDialog open={!!userToDelete} onOpenChange={() => setUserToDelete(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Bạn có chắc?</AlertDialogTitle>
            <AlertDialogDescription>
              Thao tác này sẽ xoá vĩnh viễn người dùng <strong>{userToDelete?.username}</strong>. Không thể hoàn tác.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Hủy</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDeleteUser}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Xoá
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={bulkDeleteDialogOpen} onOpenChange={setBulkDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Xoá nhiều người dùng?</AlertDialogTitle>
            <AlertDialogDescription>
              Thao tác này sẽ xoá vĩnh viễn <strong>{selectedCount} người dùng</strong>. Không thể hoàn tác.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Hủy</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleBulkDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              disabled={bulkActionMutation.isPending}
            >
              {bulkActionMutation.isPending ? "Đang xoá..." : "Xoá tất cả"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client"

/**
 * Phase 7: Permission-Based Rendering (ADR-FE-002)
 * 
 * Button visibility is now controlled by backend permissions via can() pattern.
 * - ❌ FORBIDDEN: {isDraft && <Button />}
 * - ✅ REQUIRED: {can('submit') && <Button />}
 */

import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Loader2, Save, Send, GraduationCap, ClipboardCheck, Lock, CheckCircle, XCircle, Trash } from "lucide-react"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog"
import { cn } from "@/lib/utils"
import { usePermissions } from "@/hooks/usePermissions"
import { getStatusConfig } from "@/lib/status-config"
import type { AdmissionProfileResponse } from "@/lib/zod/admissions"

interface AdmissionActionsProps {
  profile: AdmissionProfileResponse
  isSaving: boolean
  isSubmitting: boolean
  isEnrolling: boolean
  onSave: () => void
  onSubmit: () => void
  onEnroll: () => void
  onCheckCondition?: () => void
  // Optional: For Manager actions
  onApprove?: () => void
  onReject?: () => void
  isApproving?: boolean
  isRejecting?: boolean
  // Delete action
  onDelete?: () => void
  isDeleting?: boolean
}

export function AdmissionActions({
  profile,
  isSaving,
  isSubmitting,
  isEnrolling,
  onSave,
  onSubmit,
  onEnroll,
  onCheckCondition,
  onApprove,

  onReject,
  isApproving = false,
  isRejecting = false,
  onDelete,
  isDeleting = false,
}: AdmissionActionsProps) {
  // =========================================================================
  // Phase 7: Permission-Based Button Visibility
  // =========================================================================
  const { can } = usePermissions(profile)
  const statusConfig = getStatusConfig(profile.status)
  
  // Check eligibility from backend (not local calculation)
  const isEligible = profile.eligibility_status === 'eligible'
  
  return (
    <div className="fixed bottom-0 left-0 lg:left-64 right-0 border-t bg-background p-4 z-40 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
      <div className="container max-w-7xl mx-auto flex items-center justify-between">
        {/* Status Badge */}
        <div className="flex items-center gap-4">
          <span className="text-sm font-medium text-muted-foreground hidden sm:inline-block">
            Trạng thái: 
          </span>
          <StatusBadge status={profile.status} config={statusConfig} />
        </div>

        {/* Action Buttons - Permission Controlled */}
        <div className="flex items-center gap-3">
           {/* DELETE - can('delete') - Critical Action */}
           {can('delete') && onDelete && (
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button variant="destructive" disabled={isDeleting}>
                  {isDeleting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Trash className="w-4 h-4 mr-2" />}
                  Xóa
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>Bạn có chắc chắn muốn xóa hồ sơ này?</AlertDialogTitle>
                  <AlertDialogDescription>
                    Hành động này không thể hoàn tác. Hồ sơ tuyển sinh sẽ bị xóa vĩnh viễn khỏi hệ thống.
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel>Hủy</AlertDialogCancel>
                  <AlertDialogAction onClick={onDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                    Xóa hồ sơ
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          )}

          {/* Save Draft - can('save') */}
          {can('save') && (
            <Button variant="outline" onClick={onSave} disabled={isSaving}>
              {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
              Lưu nháp
            </Button>
          )}
          
          {/* Check Condition - can('submit') */}
          {can('submit') && (
            <Button variant="secondary" onClick={onCheckCondition}>
              <ClipboardCheck className="w-4 h-4 mr-2" />
              Kiểm tra điều kiện
            </Button>
          )}

          {/* Submit - can('submit') && isEligible */}
          {can('submit') && (
            <Button 
              onClick={onSubmit} 
              disabled={isSubmitting || !isEligible}
              className={cn(!isEligible && "opacity-80")}
            >
              {isSubmitting ? (
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              ) : !isEligible ? (
                <Lock className="w-4 h-4 mr-2" />
              ) : (
                <Send className="w-4 h-4 mr-2" />
              )}
              Nộp hồ sơ
            </Button>
          )}

          {/* Approve - can('approve') - Manager only */}
          {can('approve') && onApprove && (
            <Button 
              onClick={onApprove} 
              disabled={isApproving}
              className="bg-green-600 hover:bg-green-700"
            >
              {isApproving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle className="w-4 h-4 mr-2" />}
              Phê duyệt
            </Button>
          )}

          {/* Reject - can('reject') - Manager only */}
          {can('reject') && onReject && (
            <Button 
              onClick={onReject} 
              disabled={isRejecting}
              variant="destructive"
            >
              {isRejecting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <XCircle className="w-4 h-4 mr-2" />}
              Từ chối
            </Button>
          )}

          {/* Enroll - can('enroll') */}
          {can('enroll') && (
            <Button onClick={onEnroll} disabled={isEnrolling} className="bg-blue-600 hover:bg-blue-700">
              {isEnrolling ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <GraduationCap className="w-4 h-4 mr-2" />}
              Xác nhận nhập học
            </Button>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * StatusBadge - Uses status-config for consistent styling
 */
interface StatusBadgeProps {
  status: string
  config: ReturnType<typeof getStatusConfig>
}

function StatusBadge({ status, config }: StatusBadgeProps) {
  return <Badge className={config.badgeColor}>{config.label}</Badge>
}

"use client"

import { useState, useEffect, useMemo } from "react"
import { useForm, FormProvider, FieldValues, UseFormReturn } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"

// Phase 7: Reusable status banners
import { StatusBanner, AdmissionPendingBanner } from "@/components/ui/StatusBanner"

import {
  useGetAdmission,
  useUpdateAdmission,
  useSubmitAdmission,
  useEnrollStudent,
  useDeleteAdmission,
} from "@/hooks/admissions"
import {
  admissionProfileUpdateSchema,
  type AdmissionProfileResponse,
  type AdmissionProfileUpdate,
} from "@/lib/zod/admissions"

// Architecture Standards (Phase 7)
import { usePermissions } from "@/hooks/usePermissions"
import { getStatusConfig } from "@/lib/status-config"

// Layout & Components
import { AdmissionLayout } from "./layout/AdmissionLayout"
import { AdmissionActions } from "./AdmissionActions"

// Tabs
import { PersonalInfoTab } from "./tabs/PersonalInfoTab"
import { FamilyTab } from "./tabs/FamilyTab"
import { AcademicHistoryTab } from "./tabs/AcademicHistoryTab"
import { ScoresTab } from "./tabs/ScoresTab"
import { DocumentsTab } from "./tabs/DocumentsTab"
import { TuitionTab } from "./tabs/TuitionTab"
import { FinalizeTab } from "./tabs/FinalizeTab"

interface AdmissionDetailClientProps {
  profileId: number
  initialData: AdmissionProfileResponse
}

export function AdmissionDetailClient({
  profileId,
  initialData,
}: AdmissionDetailClientProps) {
  // =========================================================================
  // 1. Data Fetching
  // =========================================================================
  const { data: profile } = useGetAdmission(profileId, {
    initialData,
    staleTime: 15000, // 15 seconds - auto-refresh when stale
  })

  const updateMutation = useUpdateAdmission(profileId)
  const submitMutation = useSubmitAdmission(profileId)
  const enrollMutation = useEnrollStudent(profileId)
  const deleteMutation = useDeleteAdmission(profileId)

  // =========================================================================
  // 2. Phase 7: Permission-Based Rendering (ADR-FE-002)
  // =========================================================================
  const { can } = usePermissions(profile)
  
  // =========================================================================
  // 3. Phase 7: Status-Driven UI (ADR-FE-003)
  // =========================================================================
  const _statusConfig = useMemo(
    () => getStatusConfig(profile?.status ?? 'draft'),
    [profile?.status]
  )
  
  // =========================================================================
  // 4. Phase 7: Backend-Computed Fields (ADR-FE-001)
  // Read eligibility from backend instead of local calculation
  // =========================================================================
  const isEligible = profile?.eligibility_status === 'eligible'
  const validationErrors = profile?.validation_errors ?? []
  const _completionPercent = profile?.completion_percent ?? 0
  
  // Convert validation errors to missingItems format for AdmissionLayout
  // Note: missingItems is kept for backward compatibility but Header now uses validation_summary
  const missingItems = useMemo(() => 
    validationErrors.map(err => ({
      code: err,
      label: err,
      status: "error" as const
    }))
  , [validationErrors])

  // =========================================================================
  // Phase 0.9: Read step_status from Backend (Architecture Compliant)
  // Backend computes, Frontend renders - NO local calculation
  // =========================================================================
  const stepsStatus = useMemo(() => {
    // Read directly from backend step_status
    const backendStatus = profile?.step_status
    if (backendStatus) {
      // Convert string keys from JSON to number keys for component compatibility
      const converted: Record<number, "success" | "warning" | "error" | "locked"> = {}
      for (const [key, value] of Object.entries(backendStatus)) {
        converted[parseInt(key, 10)] = value as "success" | "warning" | "error" | "locked"
      }
      return converted
    }
    // Fallback for backward compatibility (if backend doesn't return step_status yet)
    return {
      1: "success", 2: "success", 3: "success", 
      4: "success", 5: "success", 6: "success", 7: "locked"
    } as Record<number, "success" | "warning" | "error" | "locked">
  }, [profile?.step_status])

  // =========================================================================
  // 5. Navigation State
  // =========================================================================
  const [currentStep, setCurrentStep] = useState(1)

  // =========================================================================
  // 6. Form Setup
  // =========================================================================
  const form = useForm<AdmissionProfileUpdate>({
    resolver: zodResolver(admissionProfileUpdateSchema),
    mode: "onBlur", // ADR-FE-001: Validate on blur, not on every change
    defaultValues: {
      citizen_id: profile?.citizen_id || "",
      full_name: profile?.full_name || "",
      phone: profile?.phone || "",
      email: profile?.email || "",
      dob: profile?.dob || undefined,
      gender: profile?.gender || "",
      social_insurance_number: profile?.social_insurance_number || "",
      nationality: profile?.nationality || "",
      ethnicity: profile?.ethnicity || "",
      religion: profile?.religion || "",
      disability_type: profile?.disability_type || "",
      permanent_province: profile?.permanent_province || "",
      permanent_district: profile?.permanent_district || "",
      permanent_ward: profile?.permanent_ward || "",
      place_of_birth: profile?.place_of_birth || "",
      native_place: profile?.native_place || "",
      union_entry_date: profile?.union_entry_date || undefined,
      party_entry_date: profile?.party_entry_date || undefined,
      party_official_entry_date: profile?.party_official_entry_date || undefined,
      family_info: profile?.family_info || [],
      academic_history: profile?.academic_history || [],
      admission_scores: profile?.admission_scores || {},
      documents_checklist: profile?.documents_checklist || [],
      version: profile?.version ?? 1,
    },
  })

  // Form Reset on Data Update
  useEffect(() => {
    if (profile) {
      form.reset({
        citizen_id: profile.citizen_id || "",
        full_name: profile.full_name || "",
        phone: profile.phone || "",
        email: profile.email || "",
        dob: profile.dob || undefined,
        gender: profile.gender || "",
        social_insurance_number: profile.social_insurance_number || "",
        nationality: profile.nationality || "",
        ethnicity: profile.ethnicity || "",
        religion: profile.religion || "",
        disability_type: profile.disability_type || "",
        permanent_province: profile.permanent_province || "",
        permanent_district: profile.permanent_district || "",
        permanent_ward: profile.permanent_ward || "",
        place_of_birth: profile.place_of_birth || "",
        native_place: profile.native_place || "",
        union_entry_date: profile.union_entry_date || undefined,
        party_entry_date: profile.party_entry_date || undefined,
        party_official_entry_date: profile.party_official_entry_date || undefined,
        family_info: profile.family_info || [],
        academic_history: profile.academic_history || [],
        admission_scores: profile.admission_scores || {},
        documents_checklist: profile.documents_checklist || [],
        version: profile.version ?? 1,
      })
    }
  }, [profile, form])

  // =========================================================================
  // 7. Handlers
  // =========================================================================
  const handleSave = () => {
    const data = form.getValues()
    const payload = {
      ...data,
      citizen_id: data.citizen_id === "" ? null : data.citizen_id,
      admission_scores: !data.admission_scores?.gpa ? null : data.admission_scores
    }
    updateMutation.mutate(payload)
  }

  const handleSubmit = async () => {
    await submitMutation.mutateAsync()
  }

  const handleEnroll = () => {
    enrollMutation.mutate()
  }

  // Phase 7: Delete Handler
  const handleDelete = () => {
    deleteMutation.mutate()
  }

  const handleCheckCondition = () => {
    // Navigate to first error step
    if (stepsStatus[1] === "error") setCurrentStep(1)
    else if (stepsStatus[4] === "error") setCurrentStep(4)
    else if (stepsStatus[5] === "error") setCurrentStep(5)
  }

  if (!profile) return null

  // =========================================================================
  // 8. Render
  // =========================================================================
  return (
    <FormProvider {...form}>
      <AdmissionLayout 
        profile={profile}
        currentStep={currentStep}
        onStepChange={setCurrentStep}
        stepsStatus={stepsStatus}
        validation={{ isEligible, missingItems }}
      >
        {/* Phase 7: Status-Driven Banners */}
        <StatusBanner status={profile.status} />
        <AdmissionPendingBanner status={profile.status} />
        {/* Phase 0.9: ValidationErrorsBanner removed - validation shown in Header + Sidebar */}

        {/* TAB CONTENT */}
        <div className="bg-white rounded-lg shadow-sm min-h-[500px] p-1">
          {currentStep === 1 && <PersonalInfoTab profile={profile} form={form as unknown as UseFormReturn<FieldValues>} isEditable={can('edit')} />}
          {currentStep === 2 && <FamilyTab form={form as unknown as UseFormReturn<FieldValues>} isEditable={can('edit')} />}
          {currentStep === 3 && <AcademicHistoryTab form={form as unknown as UseFormReturn<FieldValues>} isEditable={can('edit')} />}
          {currentStep === 4 && <ScoresTab form={form as unknown as UseFormReturn<FieldValues>} isEditable={can('edit')} minGpa={profile.applied_rules?.min_gpa ?? 0} appliedRules={profile.applied_rules} profile={profile} />}
          {currentStep === 5 && <DocumentsTab profile={profile} isEditable={can('edit')} />}
          {currentStep === 6 && <TuitionTab profile={profile} />}
          {currentStep === 7 && <FinalizeTab isEligible={isEligible} onSubmit={handleSubmit} isSubmitting={submitMutation.isPending} />}
        </div>

        {/* STICKY ACTIONS (now uses permissions) */}
        <AdmissionActions 
          profile={profile}
          isSaving={updateMutation.isPending}
          isSubmitting={submitMutation.isPending}
          isEnrolling={enrollMutation.isPending}
          onSave={handleSave}
          onSubmit={handleSubmit}
          onEnroll={handleEnroll}
          onDelete={handleDelete}
          isDeleting={deleteMutation.isPending}
          onCheckCondition={handleCheckCondition}
        />
      </AdmissionLayout>
    </FormProvider>
  )
}

"use client"

import { cn } from "@/lib/utils"
import { CheckCircle2, AlertCircle, XCircle, Lock, User, Users, GraduationCap, Calculator, FileText, Wallet, CheckSquare } from "lucide-react"

interface PipelineSidebarProps {
  currentStep: number
  onStepChange: (step: number) => void
  stepsStatus: Record<number, "success" | "warning" | "error" | "locked">
}

const STEPS = [
    { id: 1, label: "Thông tin cá nhân", icon: User },
    { id: 2, label: "Gia đình / Giám hộ", icon: Users },
    { id: 3, label: "Học tập", icon: GraduationCap },
    { id: 4, label: "Điểm & Điều kiện", icon: Calculator },
    { id: 5, label: "Tài liệu pháp lý", icon: FileText },
    { id: 6, label: "Học phí", icon: Wallet },
    { id: 7, label: "Hoàn tất & Nộp", icon: CheckSquare },
]

export function PipelineSidebar({ currentStep, onStepChange, stepsStatus }: PipelineSidebarProps) {
  
  return (
    <nav className="space-y-1">
      {STEPS.map((step) => {
        const status = stepsStatus[step.id] || "locked"
        const isActive = currentStep === step.id
        const Icon = step.icon

        return (
            <button
                key={step.id}
                onClick={() => status !== "locked" && onStepChange(step.id)}
                disabled={status === "locked"}
                className={cn(
                    "w-full flex items-center justify-between px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-200",
                    isActive 
                        ? "bg-primary/10 text-primary hover:bg-primary/15" 
                        : "text-muted-foreground hover:bg-muted hover:text-foreground",
                    status === "locked" && "opacity-50 cursor-not-allowed hover:bg-transparent"
                )}
            >
                <div className="flex items-center gap-3">
                    <div className={cn(
                        "w-8 h-8 rounded-full flex items-center justify-center border",
                        isActive ? "border-primary text-primary" : "border-muted bg-background",
                        status === "success" && !isActive && "bg-green-50 border-green-200 text-green-600",
                        status === "error" && !isActive && "bg-red-50 border-red-200 text-red-600"
                    )}>
                        <span className="text-xs">{step.id}</span>
                    </div>
                    <span>{step.label}</span>
                </div>
                
                {/* Status Icon */}
                <div>
                    {status === "success" && <CheckCircle2 className="w-4 h-4 text-green-600" />}
                    {status === "warning" && <AlertCircle className="w-4 h-4 text-yellow-600" />}
                    {status === "error" && <XCircle className="w-4 h-4 text-red-600" />}
                    {status === "locked" && <Lock className="w-4 h-4 text-muted-foreground/50" />}
                </div>
            </button>
        )
      })}
    </nav>
  )
}

"use client"

import { useFieldArray, UseFormReturn, FieldValues } from "react-hook-form"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from "@/components/ui/form"
import { Plus, Trash2, Users, UserCheck } from "lucide-react"
import { Badge } from "@/components/ui/badge"

interface FamilyMember {
  id: string;
  full_name: string;
  relationship: string;
  phone: string;
  occupation: string;
  is_primary_guardian: boolean;
}

interface FamilyTabProps {
  form: UseFormReturn<FieldValues>
  isEditable: boolean
}

export function FamilyTab({ form, isEditable }: FamilyTabProps) {
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "family_info",
  })

  // Helper to get original index
  const getOriginalIndex = (id: string) => fields.findIndex(f => f.id === id)

  const guardians = fields.filter((f: Partial<FamilyMember>) => f.is_primary_guardian)
  const others = fields.filter((f: Partial<FamilyMember>) => !f.is_primary_guardian)

  const addMember = (isPrimary: boolean) => {
    append({
        full_name: "",
        relationship: isPrimary ? "Bố" : "", // Default hint
