            </div>
            {isPrimary && (
                <div className="absolute top-2 right-2">
                    <Badge variant="secondary" className="bg-blue-100 text-blue-700">Giám hộ chính</Badge>
                </div>
            )}
        </div>
    )
}

"use client"

import { useMemo, useEffect } from "react"
import { UseFormReturn, FieldValues, useWatch } from "react-hook-form"
import { useQuery } from "@tanstack/react-query"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from "@/components/ui/form"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Calculator, CheckCircle2, XCircle, AlertCircle, BookOpen } from "lucide-react"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { configApi } from "@/lib/api/config"
import type { AppliedRules } from "@/lib/zod/admissions"

// Internal interface for UI logic compatibility
interface AdmissionCriterion {
  id: string
  method_name: string
  subject_groups?: string[]
  min_score?: number
  conditions?: string
}

interface ScoresTabProps {
  form: UseFormReturn<FieldValues>
  isEditable: boolean
  minGpa: number
  // Updated to match the actual AppliedRules type from backend/zod
  appliedRules?: AppliedRules | null
  // Phase 7: Backend-computed scores (source of truth)
  profile?: {
    total_score?: number | null
    average_score?: number | null
  }
}

// Vietnamese labels for subject codes
const SUBJECT_LABELS: Record<string, string> = {
  math: "Toán",
  physics: "Vật lí",
  chemistry: "Hóa học",
  biology: "Sinh học",
  literature: "Ngữ văn",
  history: "Lịch sử",
  geography: "Địa lí",
  english: "Tiếng Anh",
  french: "Tiếng Pháp",
  german: "Tiếng Đức",
  russian: "Tiếng Nga",
  japanese: "Tiếng Nhật",
  chinese: "Tiếng Trung",
  korean: "Tiếng Hàn",
  civic_education: "Giáo dục công dân",
  informatics: "Tin học",
  natural_science: "Khoa học tự nhiên",
  social_science: "Khoa học xã hội",
  economic_law: "Giáo dục Kinh tế và pháp luật",
  industrial_tech: "Công nghệ công nghiệp",
  agricultural_tech: "Công nghệ nông nghiệp",
}


export function ScoresTab({ form, isEditable, minGpa, appliedRules, profile }: ScoresTabProps) {
  // Construct criteria from appliedRules
  // Since AppliedRules now represents a snapshot for a SINGLE path,
  // we map it to a single criterion for the UI to consume.
  const criteria = useMemo<AdmissionCriterion[]>(() => {
    if (!appliedRules) return []
    
    // Map the single applied rule configuration to a criterion
    return [{
      id: appliedRules.admission_method_id?.toString() || "default",
      method_name: appliedRules.admission_method || "Phương thức xét tuyển",
      // Map complex SubjectGroupSnapshot to string[] of codes
      subject_groups: appliedRules.subject_groups?.map(g => g.code) || [],
      min_score: appliedRules.min_score ?? undefined,
    }]
  }, [appliedRules])
  
  // Use useWatch for better reactivity
  const selectedCriterionId = useWatch({
    control: form.control,
    name: "admission_scores.selected_criterion_id",
  })
  
  const selectedGroup = useWatch({
    control: form.control,
    name: "admission_scores.selected_group",
  })
  
  const gpa = useWatch({
    control: form.control,
    name: "admission_scores.gpa",
  })
  
  const subjectScoresData = useWatch({
    control: form.control,
    name: "admission_scores.subject_scores",
  })
  
  // Find selected criterion
  const selectedCriterion = useMemo(() => {
    return criteria.find(c => c.id === selectedCriterionId)
  }, [criteria, selectedCriterionId])
  
  // Get available subject groups for selected criterion
  const availableGroups = selectedCriterion?.subject_groups || []
  
  // Fetch all subject groups from API
  const { data: allSubjectGroups, isLoading: isLoadingGroups } = useQuery({
    queryKey: ["subject-groups"],
    queryFn: () => configApi.getSubjectGroups(),
    staleTime: 1000 * 60 * 10, // Cache 10 mins
  })
  
  // Get selected subject group details from API
  const selectedGroupDetails = useMemo(() => {
    if (!selectedGroup || !allSubjectGroups) return null
    return allSubjectGroups.find(g => g.code === selectedGroup) || null
  }, [selectedGroup, allSubjectGroups])
  
  // Get subjects from API data
  const subjects = useMemo(() => {
    return selectedGroupDetails?.subjects || []
  }, [selectedGroupDetails])
  
  // =========================================================================
  // Calculate scores for real-time preview (UX only - backend is source of truth)
  // =========================================================================
  const localTotalScore = useMemo(() => {
    if (!subjectScoresData || typeof subjectScoresData !== 'object') return 0
    return Object.values(subjectScoresData as Record<string, number>).reduce(
      (sum, score) => sum + (typeof score === 'number' ? score : 0),
      0
    )
  }, [subjectScoresData])
  
  // Phase 7: Prefer backend-computed scores (source of truth) with local fallback for preview
  const totalScore = profile?.total_score ?? localTotalScore
  const _averageScore = profile?.average_score ?? (subjects.length > 0 ? localTotalScore / subjects.length : 0)
  
  // Show preview indicator if we're showing local calculation
  const isPreview = !profile?.total_score && localTotalScore > 0
  
  // Initialize subject_scores when group changes
  useEffect(() => {
    if (selectedGroupDetails?.subjects && isEditable && selectedGroup) {
      const currentScores = form.getValues("admission_scores.subject_scores") || {}
      const newScores: Record<string, number | null> = {}
      
      selectedGroupDetails.subjects.forEach((subject) => {
        // Preserve existing score if available
        newScores[subject] = currentScores[subject] ?? null
      })
      
      form.setValue("admission_scores.subject_scores", newScores, { 
        shouldDirty: true,
        shouldValidate: false 
      })
    }
  }, [selectedGroupDetails, selectedGroup, form, isEditable])
  
  // Reset selected_group when criterion changes and group is no longer valid
  useEffect(() => {
    if (isEditable && selectedCriterionId) {
      const currentGroup = form.getValues("admission_scores.selected_group")
      if (currentGroup && !availableGroups.includes(currentGroup)) {
        form.setValue("admission_scores.selected_group", null, { shouldDirty: true })
        form.setValue("admission_scores.subject_scores", {}, { shouldDirty: true })
      }
    }
  }, [selectedCriterionId, availableGroups, form, isEditable])
  
  // Validation
  const currentGpa = gpa ? parseFloat(gpa) : 0
  const minScore = selectedCriterion?.min_score || 0
  
  // Check if this is ONLY a GPA method (no subject groups) or also supports subject-based scoring
  const isGpaOnlyMethod = (
    (selectedCriterion?.method_name?.toLowerCase().includes("học bạ") || 
     selectedCriterion?.method_name?.toLowerCase().includes("gpa")) &&
    (!selectedCriterion?.subject_groups || selectedCriterion.subject_groups.length === 0)
  )
  
  // Method supports subject-based scoring if it has subject_groups
  const supportsSubjectScoring = availableGroups.length > 0
  
  const isQualified = isGpaOnlyMethod 
    ? currentGpa >= minGpa && currentGpa > 0
    : totalScore >= minScore && totalScore > 0
  
  // No criteria available
  if (criteria.length === 0) {
    return (
      <Alert variant="default">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>
          Chưa có thông tin phương thức xét tuyển. Hãy liên hệ quản trị viên để cập nhật.
        </AlertDescription>
      </Alert>
    )
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* LEFT: INPUTS */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Calculator className="w-5 h-5" />
              Nhập điểm xét tuyển
            </CardTitle>
            <CardDescription>
              Chọn phương thức và nhập điểm để hệ thống đánh giá
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Step 1: Select Admission Method */}
            <FormField
              control={form.control}
              name="admission_scores.selected_criterion_id"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="flex items-center gap-2">
                    <BookOpen className="w-4 h-4" />
                    Phương thức xét tuyển *
                  </FormLabel>
                  <Select
                    disabled={!isEditable}
                    value={field.value || ""}
                    onValueChange={field.onChange}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Chọn phương thức xét tuyển" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {criteria.map((c) => (
                        <SelectItem key={c.id} value={c.id}>
                          {c.method_name}
                          {c.min_score && ` (≥ ${c.min_score} điểm)`}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Step 2: Select Subject Group (if applicable) */}
            {selectedCriterion && availableGroups.length > 0 && (
              <FormField
                control={form.control}
                name="admission_scores.selected_group"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Tổ hợp môn xét tuyển *</FormLabel>
                    <Select
                      disabled={!isEditable || isLoadingGroups}
                      value={field.value || ""}
                      onValueChange={field.onChange}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder={isLoadingGroups ? "Đang tải..." : "Chọn tổ hợp môn"} />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {isLoadingGroups ? (
                          <div className="p-2">
                            <Skeleton className="h-6 w-full" />
                          </div>
                        ) : (
                          availableGroups.map((group) => {
                            const groupInfo = allSubjectGroups?.find(g => g.code === group)
                            return (
                              <SelectItem key={group} value={group}>
                                <span className="font-medium">{group}</span>
                                {groupInfo && (
                                  <span className="ml-2 text-muted-foreground">({groupInfo.name})</span>
                                )}
                              </SelectItem>
                            )
                          })
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            )}

            {/* Step 3A: GPA Input (for GPA-only methods) */}
            {selectedCriterion && isGpaOnlyMethod && (
              <FormField
                control={form.control}
                name="admission_scores.gpa"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Điểm trung bình (GPA) *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        step="0.1"
                        min={0}
                        max={10}
                        disabled={!isEditable}
                        {...field}
                        value={field.value ?? ""}
                        onChange={(e) =>
                          field.onChange(
                            e.target.value ? parseFloat(e.target.value) : undefined
                          )
                        }
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            )}

            {/* Step 3B: Subject Score Inputs (for methods with subject_groups) */}
            {selectedCriterion && supportsSubjectScoring && selectedGroup && (
              <div className="space-y-4">
                <p className="text-sm font-medium text-muted-foreground">
                  Nhập điểm các môn trong tổ hợp {selectedGroup}:
                </p>
                
                {/* Loading state */}
                {isLoadingGroups && (
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                    <Skeleton className="h-16 w-full" />
                    <Skeleton className="h-16 w-full" />
                    <Skeleton className="h-16 w-full" />
                  </div>
                )}
                
                {/* No subjects found */}
                {!isLoadingGroups && subjects.length === 0 && (
                  <Alert variant="destructive">
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription>
                      Không tìm thấy thông tin môn học cho tổ hợp {selectedGroup}. 
                      Vui lòng liên hệ quản trị viên để cấu hình.
                    </AlertDescription>
                  </Alert>
                )}
                
                {/* Subject inputs */}
                {!isLoadingGroups && subjects.length > 0 && (
                  <>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                      {subjects.map((subject) => (
                        <FormField
                          key={subject}
                          control={form.control}
                          name={`admission_scores.subject_scores.${subject}`}
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>{SUBJECT_LABELS[subject] || subject}</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  step="0.1"
                                  min={0}
                                  max={10}
                                  disabled={!isEditable}
                                  {...field}
                                  value={field.value ?? ""}
                                  onChange={(e) =>
                                    field.onChange(
                                      e.target.value ? parseFloat(e.target.value) : null
                                    )
                                  }
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      ))}
                    </div>

                    {/* Auto-calculated Total */}
                    <div className="pt-4 border-t">
                      <div className="flex justify-between items-center text-sm">
                        <span className="font-medium">
                          Tổng điểm:
                          {isPreview && (
                            <span className="text-xs text-muted-foreground ml-1">(preview)</span>
                          )}
                        </span>
                        <span className="text-lg font-bold text-primary">
                          {totalScore.toFixed(1)} / 30
                        </span>
                      </div>
                    </div>
                  </>
                )}
              </div>
            )}
          </CardContent>
        </Card>

        {/* RIGHT: RESULT PANEL */}
        <Card
          className={
            !selectedCriterion
              ? "bg-muted/50"
              : isQualified
              ? "bg-green-50 border-green-200"
              : "bg-red-50 border-red-200"
          }
        >
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              {!selectedCriterion ? (
                <AlertCircle className="text-muted-foreground" />
              ) : isQualified ? (
                <CheckCircle2 className="text-green-600" />
              ) : (
                <XCircle className="text-red-600" />
              )}
              KẾT QUẢ XÉT TUYỂN
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {!selectedCriterion ? (
              <p className="text-sm text-muted-foreground">
                Vui lòng chọn phương thức xét tuyển để xem kết quả.
              </p>
            ) : (
              <>
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span>Phương thức:</span>
                    <span className="font-medium">{selectedCriterion.method_name}</span>
                  </div>
                  {selectedGroup && (
                    <div className="flex justify-between">
                      <span>Tổ hợp môn:</span>
                      <span className="font-medium">{selectedGroup}</span>
                    </div>
                  )}
                  <div className="flex justify-between">
                    <span>Điểm chuẩn:</span>
                    <span className="font-medium">
                      {isGpaOnlyMethod ? `GPA ≥ ${minGpa}` : `≥ ${minScore} điểm`}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span>Điểm đạt được:</span>
                    <span className="font-medium">
                      {isGpaOnlyMethod
                    ? currentGpa.toFixed(1)
                    : totalScore.toFixed(1)}
                    </span>
                  </div>
                </div>

                <div className="pt-4 border-t border-dashed">
                  <div className="flex justify-between items-center font-semibold">
                    <span>Kết quả:</span>
                    <span className={isQualified ? "text-green-700" : "text-red-700"}>
                      {isQualified ? "ĐẠT" : "CHƯA ĐẠT"}
                    </span>
                  </div>
                  {!isQualified && (
                    <p className="text-xs text-red-600 mt-2">
                      → Thiếu:{" "}
                      {isGpaOnlyMethod
                        ? "GPA thấp hơn điểm chuẩn"
                        : "Tổng điểm thấp hơn điểm chuẩn"}
                    </p>
                  )}
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

// src/app/(dashboard)/dashboard/officer/page.tsx
"use client";

import { useState } from "react";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { AlertCircle } from "lucide-react";
import { WorkloadCard } from "@/components/officer/WorkloadCard";
import { PerformanceChart } from "@/components/officer/PerformanceChart";
import { FunnelChart } from "@/components/officer/FunnelChart";
import { TodaySchedule } from "@/components/officer/TodaySchedule";
import { 
  KPICardsGrid, 
  PriorityActionsPanel, 
  WeeklyLeaderboard, 
  SmartHeader,
  RecommendationsPanel,
  AnnualProgressCard
} from "@/components/officer/dashboard";
import { DashboardDateProvider } from "@/contexts/DashboardDateContext";
import { useDashboardStats, type DashboardScope } from "@/hooks/useDashboardStats";
import { api } from "@/lib/api/client";
import { toast } from "sonner";

/**
 * Officer Command Center - Enhanced Dashboard for officers
 *
 * Features:
 * - Date Range Filter for all dashboard data
 * - KPI Cards with trends
 * - Priority Actions
 * - Real-time stats with Socket.IO updates
 * - Performance trends
 * - Sales funnel visualization
 * - Scope filter for manager/admin (Phase 3)
 */

// =============================================================================
// INNER CONTENT (must be inside DashboardDateProvider to use useDashboardDate)
// =============================================================================

function DashboardContent() {
  // Scope state for manager/admin view switching
  const [scope, setScope] = useState<DashboardScope>("personal");
  
  // Pass scope to useDashboardStats hook
  const { stats, teamStats, isLoading, error, refetch } = useDashboardStats({ scope });

  // === LOADING STATE ===
  if (isLoading) {
    return (
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <Skeleton className="h-10 w-64" />
          <Skeleton className="h-10 w-80" />
        </div>

        {/* KPI Cards Skeleton */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <Skeleton key={i} className="h-32" />
          ))}
        </div>

        <div className="grid gap-6 md:grid-cols-2">
          <Skeleton className="h-96" />
          <Skeleton className="h-96" />
        </div>
      </div>
    );
  }

  // === ERROR STATE ===
  if (error) {
    return (
      <div className="container mx-auto p-6">
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>
            Không thể tải thống kê dashboard. Vui lòng thử lại.
            <button
              onClick={() => refetch()}
              className="ml-4 underline"
            >
              Thử lại
            </button>
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  if (!stats) {
    return null;
  }

  // === DATA TRANSFORMERS ===
  const performanceTrends = (stats.performance_trends ?? []).map((t) => ({
    date: t.date,
    leads_assigned: t.assigned,
    consultations: t.consultations,
    converted: t.converted,
  }));

  const salesFunnel = (stats.sales_funnel ?? []).map((s) => ({
    stage_id: s.stage_id,
    stage_name: s.stage_name,
    stage_order: s.stage_order,
    lead_count: s.lead_count,
    is_final_stage: s.is_final_stage,
    conversion_rate: s.conversion_rate,
    outcome_breakdown: s.outcome_breakdown,
  }));

  // Quick action handler
  const handleQuickAction = (action: "new_lead" | "log_call" | "schedule") => {
    switch (action) {
      case "new_lead":
        window.location.href = "/leads?action=create";
        break;
      case "log_call":
        toast.info("Tính năng đang phát triển");
        break;
      case "schedule":
        toast.info("Tính năng đang phát triển");
        break;
    }
  };

  // Calculate if daily goal is met for sparkle icon
  const isGoalMet = stats.kpis.consultations_target > 0 && 
    stats.kpis.consultations_today >= stats.kpis.consultations_target;

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header with Date Range Filter and Scope Filter */}
      <SmartHeader
        isGoalMet={isGoalMet}
        onQuickAction={handleQuickAction}
        scope={scope}
        onScopeChange={setScope}
      />

      {/* KPI Cards Row */}
      <KPICardsGrid kpis={stats.kpis} />

      {/* Main Content: Bento Grid 75/25 */}
      <div className="grid gap-6 lg:grid-cols-[1fr_350px]">
        {/* Left Column - Charts + Recommendations */}
        <div className="space-y-6">
          <div className="grid gap-6 md:grid-cols-2">
            <PerformanceChart 
              trends={performanceTrends} 
              dailyGoal={stats.kpis.consultations_target}
              teamAverage={teamStats?.team_avg_consultations}
            />
            <FunnelChart funnel={salesFunnel} />
          </div>
          {/* Phase 7: Recommendations Panel */}
          <RecommendationsPanel />
        </div>

        {/* Right Column - Action Center */}
        <div className="space-y-6">
          {/* Phase 6: Annual Progress */}
          <AnnualProgressCard progress={stats.annual_progress} />
          <WorkloadCard statusOverview={stats.status_overview} />
          <TodaySchedule />
          <PriorityActionsPanel actions={stats.priority_actions} />
          <WeeklyLeaderboard />
        </div>
      </div>
    </div>
  );
}

// =============================================================================
// PAGE EXPORT (wraps content with DashboardDateProvider)
// =============================================================================

export default function OfficerDashboardPage() {
  return (
    <DashboardDateProvider defaultPreset="7d">
      <DashboardContent />
    </DashboardDateProvider>
  );
}

// src/app/(dashboard)/leads/[id]/_components/LeadSidebar.tsx
/**
 * LeadSidebar - Complete lead information sidebar
 * 
 * Shows ALL lead fields with N/A for empty values
 * Officers can see what info is missing to ask the lead
 */

"use client";

import { 
  Phone, 
  Mail, 
  MapPin, 
  GraduationCap, 
  Building, 
  UserPlus, 
  Calendar, 
  TrendingUp, 
  Clock, 
  History,
  Briefcase,
  User,
  Hash,
  Globe,
  Target,
  Star,
} from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import { STAGE_COLORS } from "@/types/pipeline.types";
import { LEAD_SOURCE_OPTIONS } from "@/constants";
import { CopyableCell } from "@/components/common/CopyableCell";
import type { Lead, TimelineItem } from "@/types/lead.types";

interface LeadSidebarProps {
  lead: Lead;
  timeline?: TimelineItem[];
  onAssign?: () => void;
  hideHeader?: boolean; // Hide name/score header when shown in top bar
}

const getInitials = (name: string) => {
  return name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);
};

const getEducationLevelLabel = (level: string | null | undefined) => {
  if (!level) return null;
  const labels: Record<string, string> = {
    high_school: "THPT",
    diploma: "Trung cấp/Cao đẳng",
    bachelor: "Đại học",
    master: "Thạc sĩ",
    phd: "Tiến sĩ",
    other: "Khác",
  };
  return labels[level] || level;
};

const getSourceLabel = (source: string | null | undefined) => {
  if (!source) return null;
  return LEAD_SOURCE_OPTIONS.find((o) => o.value === source)?.label || source;
};

const getScoreColor = (score: number) => {
  if (score >= 70) return "bg-green-100 text-green-700 border-green-200";
  if (score >= 50) return "bg-blue-100 text-blue-700 border-blue-200";
  if (score >= 30) return "bg-yellow-100 text-yellow-700 border-yellow-200";
  return "bg-gray-100 text-gray-600 border-gray-200";
};

const getScoreLabel = (score: number) => {
  if (score >= 70) return "Tiềm năng cao";
  if (score >= 50) return "Trung bình";
  if (score >= 30) return "Thấp";
  return "Rất thấp";
};

const getLocationProximityLabel = (value: number | null | undefined) => {
  if (value === null || value === undefined) return null;
  const labels: Record<number, string> = {
    0: "Xa",
    1: "Lân cận",
    2: "Gần",
  };
  return labels[value] || null;
};

const getOccupationRelevanceLabel = (value: number | null | undefined) => {
  if (value === null || value === undefined) return null;
  const labels: Record<number, string> = {
    0: "Không liên quan",
    1: "Gián tiếp",
    2: "Trực tiếp",
  };
  return labels[value] || null;
};

const getAcademicPerformanceLabel = (value: number | null | undefined) => {
  if (value === null || value === undefined) return null;
  const labels: Record<number, string> = {
    0: "Yếu",
    1: "Trung bình",
    2: "Khá",
    3: "Giỏi",
  };
  return labels[value] || null;
};

// Info row component with N/A support
function InfoRow({ 
  icon: Icon, 
  label, 
  value, 
  isLink,
  href,
  action,
}: { 
  icon: React.ElementType; 
  label: string; 
  value: string | number | null | undefined;
  isLink?: boolean;
  href?: string;
  action?: React.ReactNode;
}) {
  const displayValue = value ?? "N/A";
  const isEmpty = value === null || value === undefined || value === "";
  
  return (
    <div className="flex items-center justify-between py-1.5">
      <div className="flex items-center gap-2 min-w-0 flex-1">
        <Icon className={cn("h-3.5 w-3.5 shrink-0", isEmpty ? "text-muted-foreground/50" : "text-muted-foreground")} />
        <span className="text-xs text-muted-foreground shrink-0">{label}:</span>
        {isLink && href && !isEmpty ? (
          <a href={href} className="text-sm text-blue-600 hover:underline truncate">
            {displayValue}
          </a>
        ) : (
          <span className={cn("text-sm truncate", isEmpty && "text-muted-foreground/50 italic")}>
            {displayValue}
          </span>
        )}
      </div>
      {action && !isEmpty && action}
    </div>
  );
}

export function LeadSidebar({ lead, timeline, onAssign, hideHeader }: LeadSidebarProps) {
  const stageColor = lead.pipeline_stage?.color_code || STAGE_COLORS[lead.pipeline_stage?.id || 0];
  const daysInPipeline = Math.floor(
    (new Date().getTime() - new Date(lead.created_at).getTime()) / (1000 * 60 * 60 * 24)
  );

  return (
    <div className="flex h-full flex-col bg-muted/30 border-r overflow-y-auto">
      {/* Lead Identity - Hidden when shown in top bar */}
      {!hideHeader && (
        <>
          <div className="p-4 space-y-3">
            <div className="flex items-center gap-3">
              <Avatar className="h-12 w-12 border-2 border-background shadow-sm">
                <AvatarFallback className="bg-primary/10 text-primary text-base font-semibold">
                  {getInitials(lead.full_name)}
                </AvatarFallback>
              </Avatar>
              <div className="min-w-0 flex-1">
                <h2 className="font-semibold text-base truncate">{lead.full_name}</h2>
                <p className="text-xs text-muted-foreground">Lead #{lead.id}</p>
              </div>
            </div>

            {/* Score Badge */}
            <div className={cn(
              "flex items-center justify-between rounded-lg border p-2.5",
              getScoreColor(lead.lead_score)
            )}>
              <div className="flex items-center gap-2">
                <TrendingUp className="h-4 w-4" />
                <span className="font-medium text-sm">Điểm</span>
              </div>
              <div className="text-right">
                <div className="font-bold text-lg">{lead.lead_score}</div>
                <div className="text-xs opacity-80">{getScoreLabel(lead.lead_score)}</div>
              </div>
            </div>

            {/* Pipeline Stage */}
            {lead.pipeline_stage && (
              <Badge
                variant="outline"
                className={cn("w-full justify-center py-1.5 border-0 font-medium", stageColor && "text-white")}
                style={{ backgroundColor: stageColor || undefined }}
              >
                {lead.pipeline_stage.name}
              </Badge>
            )}
          </div>

          <Separator />
        </>
      )}

      {/* Contact Info */}
      <div className="px-4 py-3 space-y-0.5">
        <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Liên hệ</h4>
        
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3 text-sm">
            <Phone className="text-muted-foreground h-4 w-4 shrink-0" />
            <CopyableCell
              value={lead.phone}
              label="số điện thoại"
              className="font-mono text-sm"
            />
          </div>
          <Button
            variant="ghost"
            size="sm"
            className="h-6 px-2 text-xs text-blue-600 hover:bg-blue-50"
            onClick={() => window.open(`tel:${lead.phone}`, "_blank")}
          >
            Gọi
          </Button>
        </div>
        
        {lead.phone2 && (
          <div className="flex items-center gap-3 text-sm">
            <Phone className="text-muted-foreground h-4 w-4 shrink-0" />
            <CopyableCell
              value={lead.phone2}
              label="số điện thoại phụ"
              className="font-mono text-sm text-muted-foreground"
            />
          </div>
        )}
        
        {lead.email && (
          <div className="flex items-center gap-3 text-sm">
            <Mail className="text-muted-foreground h-4 w-4 shrink-0" />
            <CopyableCell
              value={lead.email}
              label="email"
              displayValue={
                <a
                  href={`mailto:${lead.email}`}
                  className="text-blue-600 hover:underline truncate"
                >
                  {lead.email}
                </a>
              }
            />
          </div>
        )}
        
        <InfoRow icon={MapPin} label="Địa chỉ" value={lead.location} />
      </div>

      <Separator />

      {/* Personal Info */}
      <div className="px-4 py-3 space-y-0.5">
        <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Thông tin cá nhân</h4>
        
        <InfoRow icon={Calendar} label="Năm sinh" value={lead.birth_year} />
        <InfoRow icon={Target} label="Vị trí địa lý" value={getLocationProximityLabel(lead.location_proximity)} />
        <InfoRow icon={Briefcase} label="Liên quan nghề" value={getOccupationRelevanceLabel(lead.occupation_relevance)} />
      </div>

      <Separator />

      {/* Education Info */}
      <div className="px-4 py-3 space-y-0.5">
        <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Học vấn</h4>
        
        <InfoRow icon={GraduationCap} label="Trình độ" value={getEducationLevelLabel(lead.education_level)} />
        <InfoRow icon={Star} label="Học lực" value={getAcademicPerformanceLabel(lead.academic_performance)} />
        <InfoRow icon={Hash} label="GPA" value={lead.gpa} />
      </div>

      <Separator />

      {/* Program & Assignment */}
      <div className="px-4 py-3 space-y-0.5">
        <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Đăng ký</h4>
        
        <InfoRow icon={Globe} label="Nguồn" value={getSourceLabel(lead.source)} />
        <InfoRow 
          icon={Building} 
          label="Ngành" 
          value={lead.offering?.program?.name || lead.offering?.offering_type || null} 
        />
        {lead.assigned_officer ? (
          <InfoRow icon={User} label="Tư vấn viên" value={lead.assigned_officer.full_name} />
        ) : (
          <div className="pt-2">
            <Button 
              variant="outline" 
              size="sm" 
              className="w-full h-8"
              onClick={onAssign}
            >
              <UserPlus className="mr-1.5 h-3.5 w-3.5" />
              Phân công ngay
            </Button>
          </div>
        )}
      </div>

      <Separator />

      {/* Quick Stats */}
      <div className="px-4 py-3 space-y-2">
        <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Thống kê</h4>
        
        <div className="grid grid-cols-2 gap-2">
          <div className="bg-background rounded-md p-2 border">
            <div className="flex items-center gap-1 text-muted-foreground mb-0.5">
              <Clock className="h-3 w-3" />
              <span className="text-[10px]">Trong pipeline</span>
            </div>
            <div className="font-semibold text-sm">{daysInPipeline} ngày</div>
          </div>
          <div className="bg-background rounded-md p-2 border">
            <div className="flex items-center gap-1 text-muted-foreground mb-0.5">
              <History className="h-3 w-3" />
              <span className="text-[10px]">Số lần tư vấn</span>
            </div>
            <div className="font-semibold text-sm">{lead.consultation_count}</div>
          </div>
        </div>

        <div className="text-[10px] text-muted-foreground flex items-center gap-1 pt-1">
          <Calendar className="h-3 w-3" />
          Ngày tạo: {new Date(lead.created_at).toLocaleDateString("vi-VN")}
        </div>
      </div>
    </div>
  );
}

