/**
 * ✅ NOTIFICATION 2.0: Map category to icon emoji
 */
function getCategoryIcon(category: string): string {
  const iconMap: Record<string, string> = {
    lead: "👤",
    consultation: "💬",
    application: "📝",
    finance: "💰",
    dorm: "🏠",
    asset: "🔧",
    system: "🔔",
  };
  return iconMap[category] || "🔔";
}

