interface NotificationRuleWizardProps {
  ruleId?: number;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function NotificationRuleWizard({
  ruleId,
  open,
  onOpenChange,
  onSuccess,
}: NotificationRuleWizardProps) {
  const [currentStep, setCurrentStep] = useState(1);
  const isEditMode = !!ruleId;

  // User selection state (for specific_users recipient)
  const [selectedUserIds, setSelectedUserIds] = useState<number[]>([]);
  const [userPickerOpen, setUserPickerOpen] = useState(false);

  // Condition builder state
  const [conditionEnabled, setConditionEnabled] = useState(false);
  const [conditionField, setConditionField] = useState<string>("");
  const [conditionOperator, setConditionOperator] = useState<string>("==");
  const [conditionValue, setConditionValue] = useState<string>("");

  // Fetch users for user picker
  const { data: usersData } = useAdminUsersList({
    page: 1,
    page_size: 100,
  });

  // ✅ NOTIFICATION 2.0: Fetch metadata for dynamic builder
  const { data: metadata } = useNotificationMetadata();

  // Fetch existing rule if in edit mode
  const { isLoading: loadingRule } = useNotificationRule(ruleId);

  // Mutations
  const createMutation = useCreateNotificationRule();
  const updateMutation = useUpdateNotificationRule();

  // Form
  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      event: "",
      title_template: "",
      message_template: "",
      notification_type: "info",
      link_template: "",
      channels: ["browser"], // ✅ Channel for in-browser notifications
      recipient_config: { resolver_type: "lead_owner", params: {} },
      condition: null,
      enabled: true,
      actions: [ // ✅ NOTIFICATION 2.0: Default single-step action
        {
          step: 1,
          channel: "browser",
          template_code: null,
          delay_minutes: 0,
          config: null,
        },
      ],
    },
  });

  // Watch form values for dynamic behavior
  const selectedEvent = form.watch("event");
  const selectedRecipient = form.watch("recipient_config.resolver_type") as string;
  const titleTemplate = form.watch("title_template");
  const messageTemplate = form.watch("message_template");

  // ✅ NOTIFICATION 2.0: Dynamic data from metadata
  // Convert metadata events to EventOption format
  const dynamicEvents = useMemo<EventOption[]>(() => {
    if (!metadata?.events) return SYSTEM_EVENTS; // Fallback to hardcoded
    return metadata.events.map((event) => ({
      value: event.event,
      label: event.display_name,
      category: event.category,
      description: event.description,
      icon: getCategoryIcon(event.category),
    }));
  }, [metadata]);

  // Dynamic channels from metadata (convert to full format with labels)
  const dynamicChannels = useMemo(() => {
    const channelLabels: Record<string, { label: string; description: string }> = {
      browser: { label: "Browser (Real-time)", description: "Hiển thị popup trong trình duyệt ngay lập tức" },
      email: { label: "Email", description: "Gửi email đến hộp thư của người dùng" },
      zalo: { label: "Zalo", description: "Gửi tin nhắn qua Zalo OA" },
      sms: { label: "SMS", description: "Gửi tin nhắn SMS" },
    };

    const channels = metadata?.channels || ["browser", "email", "zalo", "sms"];
    return channels.map((channel) => ({
      value: channel,
      label: channelLabels[channel]?.label || channel,
      description: channelLabels[channel]?.description || "",
    }));
  }, [metadata]);

  // Dynamic resolver types from metadata
  const dynamicResolverTypes = useMemo<RecipientOption[]>(() => {
    if (!metadata?.resolver_types) return RECIPIENT_OPTIONS; // Fallback
    return metadata.resolver_types.map((resolver) => ({
      value: resolver.value,
      label: resolver.label,
      description: resolver.description,
      example: resolver.example,
    }));
  }, [metadata]);

  // Get category from selected event (using dynamic events)
  const selectedEventData = useMemo(() => {
    return dynamicEvents.find((e) => e.value === selectedEvent);
  }, [selectedEvent, dynamicEvents]);

  // Get metadata for selected event
  const selectedEventMetadata = useMemo(() => {
    if (!metadata?.events || !selectedEvent) return null;
    return metadata.events.find((e) => e.event === selectedEvent);
  }, [metadata, selectedEvent]);

  // Get template variables for selected event (from metadata)
  const availableVariables = useMemo(() => {
    if (!selectedEventMetadata?.variables) {
      // Fallback to hardcoded
      if (!selectedEventData) return [];
      return TEMPLATE_VARIABLES[selectedEventData.category] || [];
    }
    return selectedEventMetadata.variables.map((v) => ({
      variable: `$${v.name}`,
      label: v.description,
      description: `${v.type}${v.required ? " (bắt buộc)" : ""}`,
    }));
  }, [selectedEventMetadata, selectedEventData]);

  // Group events by category (✅ NOTIFICATION 2.0: Using dynamic events)
  const groupedEvents = useMemo(() => {
    const groups: Record<string, EventOption[]> = {};
    dynamicEvents.forEach((event) => {
      if (!groups[event.category]) {
        groups[event.category] = [];
      }
      groups[event.category].push(event);
    });
    return groups;
  }, [dynamicEvents]);

  // Insert variable into template
  const insertVariable = (field: "title_template" | "message_template", variable: string) => {
    const currentValue = form.getValues(field);
    form.setValue(field, `${currentValue}${variable} `);
  };

  // Update condition in form
  const updateCondition = (field: string, operator: string, value: string) => {
    if (!field || !value) {
      form.setValue("condition", null);
      return;
    }

    // Build condition object based on backend format
    const condition = {
      type: "simple",
      field: field,
      operator: operator,
      value: value,
    };

    form.setValue("condition", condition);
  };

  const onSubmit = async (data: FormValues) => {
    try {
      if (isEditMode && ruleId) {
        await updateMutation.mutateAsync({
          ruleId,
          data,
        });
        toast.success("✅ Đã cập nhật quy tắc thông báo");
      } else {
        await createMutation.mutateAsync(data);
        toast.success("✅ Đã tạo quy tắc thông báo mới");
      }
      onOpenChange(false);
      form.reset();
      setCurrentStep(1);
      onSuccess?.();
    } catch {
      toast.error(
        isEditMode
          ? "❌ Không thể cập nhật quy tắc"
          : "❌ Không thể tạo quy tắc"
      );
    }
  };

  const isPending = createMutation.isPending || updateMutation.isPending;

  const nextStep = () => {
    setCurrentStep((prev) => Math.min(prev + 1, 5)); // ✅ NOTIFICATION 2.0: Changed from 4 to 5
  };

  const prevStep = () => {
    setCurrentStep((prev) => Math.max(prev - 1, 1));
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            {isEditMode ? "Chỉnh sửa quy tắc thông báo" : "Tạo quy tắc thông báo mới"}
          </DialogTitle>
          <DialogDescription>
            {isEditMode
              ? "Cập nhật cấu hình quy tắc thông báo"
              : "Hướng dẫn từng bước để tạo quy tắc thông báo tự động"}
          </DialogDescription>
        </DialogHeader>

        {loadingRule && isEditMode ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        ) : (
          <>
            {/* Step Indicator */}
            {/* ✅ NOTIFICATION 2.0: 5 steps total */}
            <StepIndicator currentStep={currentStep} />

            {/* Quick Templates */}
            {currentStep === 1 && !isEditMode && (
              <Card className="bg-gradient-to-r from-blue-50 to-indigo-50 border-blue-200">
                <CardHeader className="pb-3">
                  <CardTitle className="text-sm flex items-center gap-2">
                    <Zap className="h-4 w-4 text-blue-600" />
                    Kịch bản mẫu - Bắt đầu nhanh
                    <HelpTooltip content="Click vào kịch bản mẫu để tự động điền form theo các trường hợp phổ biến" />
                  </CardTitle>
                  <CardDescription className="text-xs">
                    Click để áp dụng kịch bản và tùy chỉnh sau
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                    {/* Template 1: Manager creates lead */}
                    <Button
                      type="button"
                      variant="outline"
                      className="h-auto py-3 px-4 justify-start text-left"
                      onClick={() => {
                        form.setValue("event", "lead_created");
                        form.setValue("recipient_config", {
                          resolver_type: "unit_staff",
                          params: {},
                        });
                        setConditionEnabled(true);
                        setConditionField("actor.role");
                        setConditionOperator("==");
                        setConditionValue("manager");
                        updateCondition("actor.role", "==", "manager");
                        form.setValue("title_template", "Lead mới từ Manager: $lead_name");
                        form.setValue("message_template", "Manager vừa tạo lead $lead_name ($lead_phone). Các officer cùng đơn vị vui lòng theo dõi.");
                        form.setValue("notification_type", "info");
                        setCurrentStep(2);
                      }}
                    >
                      <div className="space-y-1">
                        <p className="font-medium text-sm">Manager tạo lead → Gửi cho Officers</p>
                        <p className="text-xs text-muted-foreground">
                          Khi manager tạo lead, gửi thông báo cho tất cả officers cùng đơn vị
                        </p>
                      </div>
                    </Button>

                    {/* Template 2: Lead assigned */}
                    <Button
                      type="button"
                      variant="outline"
                      className="h-auto py-3 px-4 justify-start text-left"
                      onClick={() => {
                        form.setValue("event", "lead_assigned");
                        form.setValue("recipient_config", {
                          resolver_type: "lead_owner",
                          params: {},
                        });
                        form.setValue("title_template", "Lead được phân công: $lead_name");
                        form.setValue("message_template", "Bạn vừa được phân công lead $lead_name ($lead_phone). Vui lòng liên hệ sớm.");
                        form.setValue("notification_type", "success");
                        setCurrentStep(2);
                      }}
                    >
                      <div className="space-y-1">
                        <p className="font-medium text-sm">Lead được phân công</p>
                        <p className="text-xs text-muted-foreground">
                          Thông báo cho officer khi được gán lead mới
                        </p>
                      </div>
                    </Button>

                    {/* Template 3: Lead assignment failed */}
                    <Button
                      type="button"
                      variant="outline"
                      className="h-auto py-3 px-4 justify-start text-left"
                      onClick={() => {
                        form.setValue("event", "lead_assignment_failed");
                        form.setValue("recipient_config", {
                          resolver_type: "unit_managers",
                          params: {},
                        });
                        form.setValue("title_template", "Cảnh báo: Phân công lead thất bại");
                        form.setValue("message_template", "Không thể tự động phân công lead $lead_name. Lý do: $reason. Vui lòng phân công thủ công.");
                        form.setValue("notification_type", "warning");
                        setCurrentStep(2);
                      }}
                    >
                      <div className="space-y-1">
                        <p className="font-medium text-sm">Phân công thất bại → Gửi Manager</p>
                        <p className="text-xs text-muted-foreground">
                          Cảnh báo manager khi không thể phân công lead tự động
                        </p>
                      </div>
                    </Button>

                    {/* Template 4: Consultation reminder */}
                    <Button
                      type="button"
                      variant="outline"
                      className="h-auto py-3 px-4 justify-start text-left"
                      onClick={() => {
                        form.setValue("event", "consultation_reminder");
                        form.setValue("recipient_config", {
                          resolver_type: "lead_owner",
                          params: {},
                        });
                        form.setValue("title_template", "Nhắc nhở: Tư vấn với $lead_name");
                        form.setValue("message_template", "Bạn có lịch tư vấn với $lead_name ($lead_phone) trong $minutes_until phút nữa.");
                        form.setValue("notification_type", "info");
                        setCurrentStep(2);
                      }}
                    >
                      <div className="space-y-1">
                        <p className="font-medium text-sm">Nhắc lịch tư vấn</p>
                        <p className="text-xs text-muted-foreground">
                          Nhắc officer trước khi đến giờ tư vấn
                        </p>
                      </div>
                    </Button>
                  </div>
                </CardContent>
              </Card>
            )}

            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                {/* STEP 1: Event Selection */}
                {currentStep === 1 && (
                  <div className="space-y-6 animate-in fade-in-0 slide-in-from-right-4 duration-300">
                    <div>
                      <h3 className="text-lg font-semibold mb-1 flex items-center gap-2">
                        <Bell className="h-5 w-5 text-primary" />
                        Bước 1: Khi nào gửi thông báo?
                        <HelpTooltip content="Chọn sự kiện hệ thống sẽ kích hoạt thông báo này. Ví dụ: khi có lead mới, khi phân công lead, v.v." />
                      </h3>
                      <p className="text-sm text-muted-foreground">
                        Chọn sự kiện hệ thống sẽ kích hoạt thông báo này
                      </p>
                    </div>

                    <FormField
                      control={form.control}
                      name="event"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Chọn sự kiện</FormLabel>
                          <FormControl>
                            <div className="space-y-4">
                              {EVENT_CATEGORIES.map((category) => {
                                const categoryEvents = groupedEvents[category.value] || [];
                                if (categoryEvents.length === 0) return null;

                                return (
                                  <Card key={category.value}>
                                    <CardHeader className="pb-3">
                                      <CardTitle className="text-sm flex items-center gap-2">
                                        <span className="text-lg">{category.icon}</span>
                                        {category.label}
                                      </CardTitle>
                                    </CardHeader>
                                    <CardContent>
                                      <RadioGroup
                                        value={field.value}
                                        onValueChange={field.onChange}
                                      >
                                        <div className="space-y-2">
                                          {categoryEvents.map((event) => (
                                            <div
                                              key={event.value}
                                              className={`
                                                flex items-start space-x-3 rounded-lg border p-3 cursor-pointer transition-all
                                                ${field.value === event.value ? "border-primary bg-primary/5" : "hover:bg-muted/50"}
                                              `}
                                              onClick={() => field.onChange(event.value)}
                                            >
                                              <RadioGroupItem value={event.value} id={event.value} />
                                              <div className="flex-1">
                                                <label
                                                  htmlFor={event.value}
                                                  className="text-sm font-medium cursor-pointer"
                                                >
                                                  {event.icon} {event.label}
                                                </label>
                                                <p className="text-xs text-muted-foreground mt-0.5">
                                                  {event.description}
                                                </p>
                                              </div>
                                            </div>
                                          ))}
                                        </div>
                                      </RadioGroup>
                                    </CardContent>
                                  </Card>
                                );
                              })}
                            </div>
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                )}

                {/* STEP 2: Recipient Selection */}
                {currentStep === 2 && (
                  <div className="space-y-6 animate-in fade-in-0 slide-in-from-right-4 duration-300">
                    <div>
                      <h3 className="text-lg font-semibold mb-1 flex items-center gap-2">
                        <Users className="h-5 w-5 text-primary" />
                        Bước 2: Ai sẽ nhận thông báo?
                        <HelpTooltip content="Xác định ai sẽ nhận thông báo khi sự kiện xảy ra. Ví dụ: cán bộ phụ trách, manager đơn vị, v.v." />
                      </h3>
                      <p className="text-sm text-muted-foreground">
                        Xác định người nhận thông báo
                      </p>
                    </div>

                    <FormField
                      control={form.control}
                      name="recipient_config.resolver_type"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Chọn người nhận</FormLabel>
                          <FormControl>
                            <RadioGroup
                              value={field.value as string}
                              onValueChange={(value) => {
                                field.onChange(value);
                                form.setValue("recipient_config", {
                                  resolver_type: value,
                                  params: {},
                                });
                              }}
                            >
                              <div className="space-y-3">
                                {/* ✅ NOTIFICATION 2.0: Dynamic resolvers */}
                                {dynamicResolverTypes.map((option) => (
                                  <Card
                                    key={option.value}
                                    className={`
                                      cursor-pointer transition-all
                                      ${field.value === option.value ? "border-primary bg-primary/5" : "hover:bg-muted/50"}
                                    `}
                                    onClick={() => {
                                      field.onChange(option.value);
                                      form.setValue("recipient_config", {
                                        resolver_type: option.value,
                                        params: {},
                                      });
                                    }}
                                  >
                                    <CardContent className="pt-4">
                                      <div className="flex items-start space-x-3">
                                        <RadioGroupItem value={option.value} id={option.value} />
                                        <div className="flex-1">
                                          <label
                                            htmlFor={option.value}
                                            className="text-sm font-medium cursor-pointer block"
                                          >
                                            {option.label}
                                          </label>
                                          <p className="text-xs text-muted-foreground mt-1">
                                            {option.description}
                                          </p>
                                          <div className="mt-2 bg-blue-50 border-l-2 border-blue-400 px-2 py-1.5 rounded">
                                            <p className="text-xs text-blue-700">
                                              💡 {option.example}
                                            </p>
                                          </div>
                                        </div>
                                      </div>
                                    </CardContent>
                                  </Card>
                                ))}
                              </div>
                            </RadioGroup>
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {/* User Picker - Only show when specific_users is selected */}
                    {selectedRecipient === "specific_users" && (
                      <Card>
                        <CardHeader>
                          <CardTitle className="text-sm">Chọn người dùng cụ thể</CardTitle>
                          <CardDescription>Chọn người sẽ nhận thông báo từ danh sách</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-3">
                          <Popover open={userPickerOpen} onOpenChange={setUserPickerOpen}>
                            <PopoverTrigger asChild>
                              <Button
                                variant="outline"
                                role="combobox"
                                aria-expanded={userPickerOpen}
                                className="w-full justify-between"
                              >
                                {selectedUserIds.length > 0
                                  ? `${selectedUserIds.length} người được chọn`
                                  : "Chọn người dùng..."}
                                <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                              </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-full p-0" align="start">
                              <Command>
                                <CommandInput placeholder="Tìm theo tên hoặc username..." />
                                <CommandList>
                                  <CommandEmpty>Không tìm thấy người dùng</CommandEmpty>
                                  <CommandGroup>
                                    {usersData?.users?.map((user) => (
                                      <CommandItem
                                        key={user.id}
                                        value={`${user.username} ${user.full_name || ""}`}
                                        onSelect={() => {
                                          setSelectedUserIds((prev) =>
                                            prev.includes(user.id)
                                              ? prev.filter((id) => id !== user.id)
                                              : [...prev, user.id]
                                          );
                                          // Update form value
                                          const currentIds = selectedUserIds.includes(user.id)
                                            ? selectedUserIds.filter((id) => id !== user.id)
                                            : [...selectedUserIds, user.id];
                                          form.setValue("recipient_config", {
                                            resolver_type: "specific_users",
                                            params: { user_ids: currentIds },
                                          });
                                        }}
                                      >
                                        <Check
                                          className={cn(
                                            "mr-2 h-4 w-4",
                                            selectedUserIds.includes(user.id)
                                              ? "opacity-100"
                                              : "opacity-0"
                                          )}
                                        />
                                        <div className="flex-1">
                                          <div className="font-medium text-sm">
                                            {user.full_name || user.username}
                                          </div>
                                          <div className="text-xs text-muted-foreground">
                                            @{user.username} • {user.role}
                                          </div>
                                        </div>
                                      </CommandItem>
                                    ))}
                                  </CommandGroup>
                                </CommandList>
                              </Command>
                            </PopoverContent>
                          </Popover>

                          {/* Display selected users */}
                          {selectedUserIds.length > 0 && (
                            <div className="flex flex-wrap gap-2">
                              {selectedUserIds.map((userId) => {
                                const user = usersData?.users?.find((u) => u.id === userId);
                                if (!user) return null;
                                return (
                                  <Badge key={userId} variant="secondary" className="gap-1">
                                    {user.full_name || user.username}
                                    <button
                                      type="button"
                                      className="ml-1 hover:text-destructive"
                                      onClick={() => {
                                        setSelectedUserIds((prev) =>
                                          prev.filter((id) => id !== userId)
                                        );
                                        const currentIds = selectedUserIds.filter((id) => id !== userId);
                                        form.setValue("recipient_config", {
                                          resolver_type: "specific_users",
                                          params: { user_ids: currentIds },
                                        });
                                      }}
                                    >
                                      ×
                                    </button>
                                  </Badge>
                                );
                              })}
                            </div>
                          )}
                        </CardContent>
                      </Card>
                    )}
                  </div>
                )}

                {/* STEP 3: Conditions (Optional) */}
                {currentStep === 3 && (
                  <div className="space-y-6 animate-in fade-in-0 slide-in-from-right-4 duration-300">
                    <div>
                      <h3 className="text-lg font-semibold mb-1 flex items-center gap-2">
                        <Filter className="h-5 w-5 text-primary" />
                        Bước 3: Điều kiện (Tùy chọn)
                        <HelpTooltip content="Thêm điều kiện để chỉ gửi thông báo khi thỏa mãn tiêu chí. Ví dụ: chỉ gửi khi người thực hiện là Manager. Bạn có thể bỏ qua bước này." />
                      </h3>
                      <p className="text-sm text-muted-foreground">
                        Chỉ gửi thông báo khi đáp ứng điều kiện (có thể bỏ qua)
                      </p>
                    </div>

                    {/* Enable/Disable Condition */}
                    <div className="flex items-center justify-between rounded-lg border p-4">
                      <div className="space-y-0.5">
                        <p className="text-sm font-medium">Bật điều kiện lọc</p>
                        <p className="text-xs text-muted-foreground">
                          Chỉ gửi thông báo khi đáp ứng điều kiện
                        </p>
                      </div>
                      <Switch
                        checked={conditionEnabled}
                        onCheckedChange={(checked) => {
                          setConditionEnabled(checked);
                          if (!checked) {
                            form.setValue("condition", null);
                            setConditionField("");
                            setConditionOperator("==");
                            setConditionValue("");
                          }
                        }}
                      />
                    </div>

                    {/* Visual Condition Builder */}
                    {conditionEnabled && (
                      <Card>
                        <CardHeader>
                          <CardTitle className="text-sm">Thiết lập điều kiện</CardTitle>
                          <CardDescription>
                            Chỉ gửi thông báo khi thỏa mãn điều kiện dưới đây
                          </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                          {/* Condition Field */}
                          <div className="space-y-2">
                            <label className="text-sm font-medium">Trường dữ liệu</label>
                            <Select
                              value={conditionField}
                              onValueChange={(value) => {
                                setConditionField(value);
                                updateCondition(value, conditionOperator, conditionValue);
                              }}
                            >
                              <SelectTrigger>
                                <SelectValue placeholder="Chọn trường..." />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="actor.role">Vai trò người thực hiện</SelectItem>
                                <SelectItem value="actor.unit_id">Đơn vị người thực hiện</SelectItem>
                                <SelectItem value="lead.status">Trạng thái lead</SelectItem>
                                <SelectItem value="lead.source">Nguồn lead</SelectItem>
                                <SelectItem value="application.status">Trạng thái hồ sơ</SelectItem>
                                <SelectItem value="amount">Số tiền</SelectItem>
                              </SelectContent>
                            </Select>
                            <p className="text-xs text-muted-foreground">
                              💡 VD: &ldquo;actor.role&rdquo; để lọc theo vai trò của người thực hiện hành động
                            </p>
                          </div>

                          {/* Condition Operator */}
                          <div className="space-y-2">
                            <label className="text-sm font-medium">Phép so sánh</label>
                            <Select
                              value={conditionOperator}
                              onValueChange={(value) => {
                                setConditionOperator(value);
                                updateCondition(conditionField, value, conditionValue);
                              }}
                            >
                              <SelectTrigger>
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="==">Bằng (==)</SelectItem>
                                <SelectItem value="!=">Khác (!=)</SelectItem>
                                <SelectItem value=">">Lớn hơn ({">"}</SelectItem>
                                <SelectItem value="<">Nhỏ hơn ({"<"})</SelectItem>
                                <SelectItem value=">=">Lớn hơn hoặc bằng ({">"}=)</SelectItem>
                                <SelectItem value="<=">Nhỏ hơn hoặc bằng ({"<"}=)</SelectItem>
                                <SelectItem value="contains">Chứa (contains)</SelectItem>
                              </SelectContent>
                            </Select>
                          </div>

                          {/* Condition Value */}
                          <div className="space-y-2">
                            <label className="text-sm font-medium">Giá trị</label>
                            {conditionField === "actor.role" ? (
                              <Select
                                value={conditionValue}
                                onValueChange={(value) => {
                                  setConditionValue(value);
                                  updateCondition(conditionField, conditionOperator, value);
                                }}
                              >
                                <SelectTrigger>
                                  <SelectValue placeholder="Chọn vai trò..." />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="manager">Manager</SelectItem>
                                  <SelectItem value="officer">Officer</SelectItem>
                                  <SelectItem value="admin">Admin</SelectItem>
                                  <SelectItem value="support">Support</SelectItem>
                                </SelectContent>
                              </Select>
                            ) : (
                              <Input
                                placeholder={
                                  conditionField === "amount"
                                    ? "VD: 10000000"
                                    : "VD: manager"
                                }
                                value={conditionValue}
                                onChange={(e) => {
                                  setConditionValue(e.target.value);
                                  updateCondition(conditionField, conditionOperator, e.target.value);
                                }}
                              />
                            )}
                            <p className="text-xs text-muted-foreground">
                              💡 Giá trị để so sánh với trường dữ liệu
                            </p>
                          </div>

                          {/* Preview */}
                          {conditionField && conditionValue && (
                            <div className="bg-blue-50 border-l-2 border-blue-400 px-3 py-2 rounded">
                              <p className="text-xs font-medium text-blue-900 mb-1">
                                📝 Điều kiện hiện tại:
                              </p>
                              <code className="text-xs text-blue-700">
                                {conditionField} {conditionOperator} &ldquo;{conditionValue}&rdquo;
                              </code>
                            </div>
                          )}
                        </CardContent>
                      </Card>
                    )}

                    {/* Example scenarios */}
                    <Card className="bg-muted/50">
                      <CardHeader className="pb-3">
                        <CardTitle className="text-sm">💡 Ví dụ điều kiện phổ biến</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2 text-xs">
                          <div className="flex items-start gap-2">
                            <span className="text-muted-foreground">•</span>
                            <div>
                              <p className="font-medium">Chỉ gửi khi Manager tạo lead:</p>
                              <code className="text-muted-foreground">actor.role == &ldquo;manager&rdquo;</code>
                            </div>
                          </div>
                          <div className="flex items-start gap-2">
                            <span className="text-muted-foreground">•</span>
                            <div>
                              <p className="font-medium">Chỉ gửi khi thanh toán trên 10 triệu:</p>
                              <code className="text-muted-foreground">amount {">"} 10000000</code>
                            </div>
                          </div>
                          <div className="flex items-start gap-2">
                            <span className="text-muted-foreground">•</span>
                            <div>
                              <p className="font-medium">Chỉ gửi khi hồ sơ được duyệt:</p>
                              <code className="text-muted-foreground">application.status == &ldquo;approved&rdquo;</code>
                            </div>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  </div>
                )}

                {/* STEP 4: Content & Template */}
                {currentStep === 4 && (
                  <div className="space-y-6 animate-in fade-in-0 slide-in-from-right-4 duration-300">
                    <div>
                      <h3 className="text-lg font-semibold mb-1 flex items-center gap-2">
                        <MessageSquare className="h-5 w-5 text-primary" />
                        Bước 4: Nội dung thông báo
                        <HelpTooltip content="Tạo tiêu đề và nội dung thông báo. Click vào các biến bên dưới để chèn thông tin tự động như tên lead, số điện thoại, v.v." />
                      </h3>
                      <p className="text-sm text-muted-foreground">
                        Soạn tiêu đề và nội dung thông báo
                      </p>
                    </div>

                    {/* Template Variables Helper */}
                    {availableVariables.length > 0 && (
                      <Card className="bg-blue-50 border-blue-200">
                        <CardHeader className="pb-3">
                          <CardTitle className="text-sm flex items-center gap-2">
                            <Sparkles className="h-4 w-4 text-blue-600" />
                            Biến tự động
                            <HelpTooltip content="Click vào biến để chèn vào tiêu đề hoặc nội dung. Giá trị sẽ tự động thay thế khi gửi thông báo." />
                          </CardTitle>
                          <CardDescription className="text-xs">
                            Click để chèn biến vào tiêu đề hoặc nội dung
                          </CardDescription>
                        </CardHeader>
                        <CardContent>
                          <div className="flex flex-wrap gap-2">
                            {availableVariables.map((v) => (
                              <TooltipProvider key={v.variable} delayDuration={0}>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <Button
                                      type="button"
                                      variant="outline"
                                      size="sm"
                                      className="text-xs h-7"
                                      onClick={() => {
                                        // Insert into the field that's currently focused, or default to message
                                        const activeElement = document.activeElement;
                                        if (activeElement?.id === "title_template") {
                                          insertVariable("title_template", v.variable);
                                        } else {
                                          insertVariable("message_template", v.variable);
                                        }
                                      }}
                                    >
                                      {v.label}
                                    </Button>
                                  </TooltipTrigger>
                                  <TooltipContent>
                                    <p className="text-xs">
                                      <code className="font-mono">{v.variable}</code> - {v.description}
                                    </p>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>
                            ))}
                          </div>
                        </CardContent>
                      </Card>
                    )}

                    {/* Title Template */}
                    <FormField
                      control={form.control}
                      name="title_template"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Tiêu đề thông báo</FormLabel>
                          <FormControl>
                            <Input
                              id="title_template"
                              placeholder="VD: Lead mới: $lead_name"
                              {...field}
                            />
                          </FormControl>
                          <FormDescription>
                            Tiêu đề ngắn gọn, súc tích. Click biến phía trên để chèn tự động.
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {/* Message Template */}
                    <FormField
                      control={form.control}
                      name="message_template"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Nội dung thông báo</FormLabel>
                          <FormControl>
                            <Textarea
                              id="message_template"
                              placeholder="VD: Lead $lead_name ($lead_phone) đã được phân công cho bạn."
                              rows={4}
                              {...field}
                            />
                          </FormControl>
                          <FormDescription>
                            Mô tả chi tiết nội dung thông báo. Click biến phía trên để chèn tự động.
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <Separator />

                    {/* Notification Type */}
                    <FormField
                      control={form.control}
                      name="notification_type"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Loại thông báo</FormLabel>
                          <Select onValueChange={field.onChange} value={field.value}>
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              {NOTIFICATION_TYPES.map((type) => (
                                <SelectItem key={type.value} value={type.value}>
                                  <div className="flex items-center gap-2">
                                    <Badge className={type.color} variant="secondary">
                                      {type.label}
                                    </Badge>
                                    <span className="text-xs text-muted-foreground">
                                      - {type.description}
                                    </span>
                                  </div>
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <FormDescription>
                            Mức độ ưu tiên của thông báo
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {/* Link Template (Optional) */}
                    <FormField
                      control={form.control}
                      name="link_template"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>
                            Liên kết (Tùy chọn)
                            <HelpTooltip content="Đường dẫn để điều hướng khi click vào thông báo. VD: /leads/$lead_id" />
                          </FormLabel>
                          <FormControl>
                            <Input
                              placeholder="VD: /leads/$lead_id"
                              {...field}
                            />
                          </FormControl>
                          <FormDescription>
                            Người dùng sẽ được chuyển đến trang này khi click thông báo
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {/* Channels */}
                    <FormField
                      control={form.control}
                      name="channels"
                      render={() => (
                        <FormItem>
                          <FormLabel>
                            Kênh gửi
                            <HelpTooltip content="Chọn cách thức gửi thông báo: trong trình duyệt, qua email, hoặc SMS" />
                          </FormLabel>
                          <FormDescription>
                            Chọn các kênh để gửi thông báo
                          </FormDescription>
                          <div className="space-y-2">
                            {/* ✅ NOTIFICATION 2.0: Dynamic channels */}
                            {dynamicChannels.map((channel) => (
                              <FormField
                                key={channel.value}
                                control={form.control}
                                name="channels"
                                render={({ field }) => (
                                  <FormItem className="flex items-start space-x-3 space-y-0 rounded-lg border p-3">
                                    <FormControl>
                                      <Checkbox
                                        checked={field.value?.includes(channel.value)}
                                        onCheckedChange={(checked) => {
                                          const current = field.value || [];
                                          if (checked) {
                                            field.onChange([...current, channel.value]);
                                          } else {
                                            field.onChange(
                                              current.filter((v) => v !== channel.value)
                                            );
                                          }
                                        }}
                                      />
                                    </FormControl>
                                    <div className="flex-1">
                                      <FormLabel className="text-sm font-medium cursor-pointer">
                                        {channel.label}
                                      </FormLabel>
                                      <p className="text-xs text-muted-foreground">
                                        {channel.description}
                                      </p>
                                    </div>
                                  </FormItem>
                                )}
                              />
                            ))}
                          </div>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    {/* Enabled Switch */}
                    <FormField
                      control={form.control}
                      name="enabled"
                      render={({ field }) => (
                        <FormItem className="flex items-center justify-between rounded-lg border p-4">
                          <div className="space-y-0.5">
                            <FormLabel className="text-base">Kích hoạt ngay</FormLabel>
                            <FormDescription>
                              Bật quy tắc này ngay sau khi tạo
                            </FormDescription>
                          </div>
                          <FormControl>
                            <Switch
                              checked={field.value}
                              onCheckedChange={field.onChange}
                            />
                          </FormControl>
                        </FormItem>
                      )}
                    />

                    {/* Preview */}
                    {(titleTemplate || messageTemplate) && (
                      <Card className="bg-muted/50">
                        <CardHeader className="pb-3">
                          <CardTitle className="text-sm flex items-center gap-2">
                            <Bell className="h-4 w-4" />
                            Xem trước thông báo
                          </CardTitle>
                        </CardHeader>
                        <CardContent>
                          <div className="bg-background rounded-lg border p-4 space-y-2">
                            {titleTemplate && (
                              <p className="font-semibold text-sm">{titleTemplate}</p>
                            )}
                            {messageTemplate && (
                              <p className="text-sm text-muted-foreground">{messageTemplate}</p>
                            )}
                            <p className="text-xs text-muted-foreground/70">
                              Vừa xong
                            </p>
                          </div>
                        </CardContent>
                      </Card>
                    )}
                  </div>
                )}

                {/* STEP 5: Multi-Step Workflow ✅ NOTIFICATION 2.0 */}
                {currentStep === 5 && (
                  <div className="space-y-6 animate-in fade-in-0 slide-in-from-right-4 duration-300">
                    <div>
                      <h3 className="text-lg font-semibold mb-1 flex items-center gap-2">
                        <Layers className="h-5 w-5 text-primary" />
                        Bước 5: Quy trình gửi thông báo
                        <HelpTooltip content="Cấu hình quy trình gửi thông báo qua nhiều kênh với độ trễ khác nhau. Ví dụ: Gửi Browser ngay, sau 30 phút gửi Email nhắc nhở." />
                      </h3>
                      <p className="text-sm text-muted-foreground">
                        Tạo quy trình gửi thông báo qua nhiều bước với các kênh khác nhau
                      </p>
                    </div>

                    <FormField
                      control={form.control}
                      name="actions"
                      render={({ field }) => (
                        <FormItem>
                          <FormControl>
                            {/* ✅ NOTIFICATION 2.0: Dynamic channels */}
                            <MultiStepActionEditor
                              actions={field.value || []}
                              onChange={field.onChange}
                              availableChannels={metadata?.channels || ["browser", "email", "zalo", "sms"]}
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                )}

                {/* Navigation Footer */}
                <DialogFooter className="flex items-center justify-between sm:justify-between border-t pt-4">
                  <div>
                    {currentStep > 1 && (
                      <Button
                        type="button"
                        variant="outline"
                        onClick={prevStep}
                        disabled={isPending}
                      >
                        <ChevronLeft className="mr-2 h-4 w-4" />
                        Quay lại
                      </Button>
                    )}
                  </div>
                  <div className="flex gap-2">
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={() => {
                        onOpenChange(false);
                        setCurrentStep(1);
                      }}
                      disabled={isPending}
                    >
                      Hủy
                    </Button>
                    {/* ✅ NOTIFICATION 2.0: Changed from 4 to 5 */}
                    {currentStep < 5 ? (
                      <Button
                        type="button"
                        onClick={nextStep}
                        disabled={!selectedEvent && currentStep === 1}
                      >
                        Tiếp theo
                        <ChevronRight className="ml-2 h-4 w-4" />
                      </Button>
                    ) : (
                      <Button type="submit" disabled={isPending}>
                        {isPending ? (
                          <>
                            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                            {isEditMode ? "Đang cập nhật..." : "Đang tạo..."}
                          </>
                        ) : (
                          <>
                            <Save className="mr-2 h-4 w-4" />
                            {isEditMode ? "Cập nhật" : "Tạo quy tắc"}
                          </>
                        )}
                      </Button>
                    )}
                  </div>
                </DialogFooter>
              </form>
            </Form>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

// src/components/admin/organization/SubjectGroupsSelector.tsx
"use client";

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command";
import { Checkbox } from "@/components/ui/checkbox";
import { Skeleton } from "@/components/ui/skeleton";
import { Search, X, ChevronDown, BookOpen } from "lucide-react";
import { configApi, type SubjectGroup } from "@/lib/api/config";
import { cn } from "@/lib/utils";

interface SubjectGroupsSelectorProps {
  value: string; // Comma-separated string "A00, A01, D01"
  onChange: (value: string) => void;
  disabled?: boolean;
  placeholder?: string;
}

export function SubjectGroupsSelector({
  value,
  onChange,
  disabled = false,
  placeholder = "Chọn tổ hợp môn...",
}: SubjectGroupsSelectorProps) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");

  // Fetch subject groups from API
  const { data: subjectGroups, isLoading } = useQuery({
    queryKey: ["subject-groups"],
    queryFn: () => configApi.getSubjectGroups(),
    staleTime: 1000 * 60 * 10, // Cache 10 minutes
  });

  // Parse selected codes from comma-separated string
  const selectedCodes = useMemo(() => {
    if (!value) return [];
    return value.split(",").map((s) => s.trim()).filter(Boolean);
  }, [value]);

  // Filter groups by search
  const filteredGroups = useMemo(() => {
    if (!subjectGroups) return [];
    if (!search) return subjectGroups;
    const searchLower = search.toLowerCase();
    return subjectGroups.filter(
      (g) =>
        g.code.toLowerCase().includes(searchLower) ||
        g.name.toLowerCase().includes(searchLower)
    );
  }, [subjectGroups, search]);

  // Group by prefix (A, B, C, D, etc.)
  const groupedByPrefix = useMemo(() => {
    const groups: Record<string, SubjectGroup[]> = {};
    for (const group of filteredGroups) {
      const prefix = group.code.charAt(0);
      if (!groups[prefix]) groups[prefix] = [];
      groups[prefix].push(group);
    }
    return groups;
  }, [filteredGroups]);

  // Toggle selection
  const toggleGroup = (code: string) => {
    const newCodes = selectedCodes.includes(code)
      ? selectedCodes.filter((c) => c !== code)
      : [...selectedCodes, code];
    onChange(newCodes.join(", "));
  };

  // Remove single selection
  const removeCode = (code: string) => {
    const newCodes = selectedCodes.filter((c) => c !== code);
    onChange(newCodes.join(", "));
  };

  // Clear all
  const clearAll = () => {
    onChange("");
  };

  return (
    <div className="space-y-2">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            disabled={disabled}
            className="w-full justify-between"
          >
            <span className="truncate">
              {selectedCodes.length > 0
                ? `Đã chọn ${selectedCodes.length} tổ hợp`
                : placeholder}
            </span>
            <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-[400px] p-0" align="start">
          <div className="p-2 border-b">
            <div className="flex items-center gap-2">
              <Search className="h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Tìm mã tổ hợp (VD: A00, D01)..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="border-0 focus-visible:ring-0 h-8"
              />
            </div>
          </div>

          {isLoading ? (
            <div className="p-4 space-y-2">
              <Skeleton className="h-6 w-full" />
              <Skeleton className="h-6 w-full" />
              <Skeleton className="h-6 w-3/4" />
            </div>
          ) : (
            <div className="max-h-[300px] overflow-y-auto p-2">
              {Object.keys(groupedByPrefix).length === 0 ? (
                <div className="p-4 text-center text-sm text-muted-foreground">
                  Không tìm thấy tổ hợp môn
                </div>
              ) : (
                Object.entries(groupedByPrefix)
                  .sort(([a], [b]) => a.localeCompare(b))
                  .map(([prefix, groups]) => (
                    <div key={prefix} className="mb-3">
                      <div className="text-xs font-semibold text-muted-foreground uppercase mb-1 px-2">
                        Khối {prefix}
                      </div>
                      <div className="space-y-1">
                        {groups.map((group) => {
                          const isSelected = selectedCodes.includes(group.code);
                          return (
                            <div
                              key={group.code}
                              onClick={() => toggleGroup(group.code)}
                              className={cn(
                                "flex items-center gap-2 px-2 py-1.5 rounded-md cursor-pointer hover:bg-muted/50 transition-colors",
                                isSelected && "bg-primary/10"
                              )}
                            >
                              <Checkbox
                                checked={isSelected}
                                onCheckedChange={() => toggleGroup(group.code)}
                                className="pointer-events-none"
                              />
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2">
                                  <span className="font-medium text-sm">{group.code}</span>
                                  <span className="text-xs text-muted-foreground truncate">
                                    {group.name}
                                  </span>
                                </div>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))
              )}
            </div>
          )}

          {selectedCodes.length > 0 && (
            <div className="border-t p-2 flex justify-between items-center">
              <span className="text-xs text-muted-foreground">
                {selectedCodes.length} đã chọn
              </span>
              <Button
                variant="ghost"
                size="sm"
                onClick={clearAll}
                className="h-7 text-xs"
              >
                Xóa tất cả
              </Button>
            </div>
          )}
        </PopoverContent>
      </Popover>

      {/* Display selected badges */}
      {selectedCodes.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {selectedCodes.map((code) => (
            <Badge
              key={code}
              variant="secondary"
              className="gap-1 pr-1"
            >
              <BookOpen className="h-3 w-3" />
              {code}
              {!disabled && (
                <button
                  type="button"
                  onClick={() => removeCode(code)}
                  className="ml-1 rounded-full hover:bg-muted p-0.5"
                >
                  <X className="h-3 w-3" />
                </button>
              )}
            </Badge>
          ))}
        </div>
      )}
    </div>
  );
}

// src/components/common/ActivityIndicator.tsx
/**
 * ActivityIndicator - Visual indicator for lead activity and urgency
 * 
 * Features:
 * - Relative time display ("2 ngày trước" instead of date)
 * - Activity status via colored text (active/warm/cold/frozen)
 * - Small dot indicator
 * - All details in tooltip (clean UI)
 */

"use client";

import React, { useMemo } from "react";
import { differenceInDays, differenceInHours, isPast, isToday, format } from "date-fns";
import { vi } from "date-fns/locale";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

// =============================================================================
// TYPES
// =============================================================================

export type ActivityLevel = "hot" | "active" | "warm" | "cold" | "frozen";

interface ActivityIndicatorProps {
  /** Date to calculate activity from (usually created_at or last consultation) */
  date: string | null | undefined;
  /** Optional next activity date (for follow-up reminders) */
  nextActivityAt?: string | null;
  /** Number of days to consider "cold" */
  coldThresholdDays?: number;
  /** Number of days to consider "frozen" */
  frozenThresholdDays?: number;
  /** Additional class names */
  className?: string;
}

// =============================================================================
// CONSTANTS
// =============================================================================

const ACTIVITY_CONFIG: Record<ActivityLevel, { 
  textColor: string; 
  dotColor: string;
  label: string;
}> = {
  hot: {
    textColor: "text-red-600 dark:text-red-400",
    dotColor: "bg-red-500",
    label: "Nóng",
  },
  active: {
    textColor: "text-green-600 dark:text-green-400",
    dotColor: "bg-green-500",
    label: "Hoạt động",
  },
  warm: {
    textColor: "text-blue-600 dark:text-blue-400",
    dotColor: "bg-blue-500",
    label: "Ấm",
  },
  cold: {
    textColor: "text-yellow-600 dark:text-yellow-400",
    dotColor: "bg-yellow-500",
    label: "Lạnh",
  },
  frozen: {
    textColor: "text-muted-foreground",
    dotColor: "bg-gray-400",
    label: "Đóng băng",
  },
};

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

function getActivityLevel(
  daysSinceActivity: number,
  coldThreshold: number = 7,
  frozenThreshold: number = 14
): ActivityLevel {
  if (daysSinceActivity <= 1) return "active";
  if (daysSinceActivity <= 3) return "warm";
  if (daysSinceActivity <= coldThreshold) return "cold";
  if (daysSinceActivity <= frozenThreshold) return "cold";
  return "frozen";
}

function formatRelativeTime(date: Date): string {
  const now = new Date();
  const hoursDiff = differenceInHours(now, date);
  const daysDiff = differenceInDays(now, date);
  
  if (hoursDiff < 1) return "Vừa xong";
  if (hoursDiff < 24) return `${hoursDiff}h trước`;
  if (daysDiff === 1) return "Hôm qua";
  if (daysDiff < 7) return `${daysDiff} ngày`;
  if (daysDiff < 14) return "1 tuần";
  if (daysDiff < 30) return `${Math.floor(daysDiff / 7)} tuần`;
  if (daysDiff < 60) return "1 tháng";
  return `${Math.floor(daysDiff / 30)} tháng`;
}

// =============================================================================
// MAIN COMPONENT
// =============================================================================

export function ActivityIndicator({
  date,
  nextActivityAt,
  coldThresholdDays = 7,
  frozenThresholdDays = 14,
  className,
}: ActivityIndicatorProps) {
  const activityInfo = useMemo(() => {
    if (!date) return null;
    
    const dateObj = new Date(date);
    const now = new Date();
    const daysSince = differenceInDays(now, dateObj);
    const level = getActivityLevel(daysSince, coldThresholdDays, frozenThresholdDays);
    const config = ACTIVITY_CONFIG[level];
    const relativeTime = formatRelativeTime(dateObj);
    const exactDate = format(dateObj, "dd/MM/yyyy HH:mm", { locale: vi });
    
    return {
      level,
      config,
      relativeTime,
      daysSince,
      exactDate,
    };
  }, [date, coldThresholdDays, frozenThresholdDays]);

  const followUpInfo = useMemo(() => {
    if (!nextActivityAt) return null;
    
    const nextDate = new Date(nextActivityAt);
    const now = new Date();
    const isPastDue = isPast(nextDate) && !isToday(nextDate);
    const isDueToday = isToday(nextDate);
    const exactDate = format(nextDate, "dd/MM/yyyy HH:mm", { locale: vi });
    
    return {
      isPastDue,
      isDueToday,
      exactDate,
      status: isPastDue ? "Quá hạn" : isDueToday ? "Hôm nay" : "Đã lên lịch",
    };
  }, [nextActivityAt]);

  if (!activityInfo) {
    return <span className="text-muted-foreground text-xs">—</span>;
  }

  const { config, relativeTime, level, exactDate, daysSince } = activityInfo;
  
  // Determine if we should show a pulse animation (for urgent items)
  const showPulse = followUpInfo?.isPastDue || followUpInfo?.isDueToday;

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <div className={cn(
            "inline-flex items-center cursor-default",
            className
          )}>
            {/* Relative time - colored text only */}
            <span className={cn(
              "text-xs tabular-nums whitespace-nowrap",
              config.textColor
            )}>
              {relativeTime}
            </span>
          </div>
        </TooltipTrigger>
        
        {/* Tooltip with all details */}
        <TooltipContent side="top" className="text-xs space-y-1 max-w-[200px]">
          <div className="font-medium">{config.label}</div>
          <div className="text-muted-foreground">
            Tạo: {exactDate}
          </div>
          <div className="text-muted-foreground">
            ({daysSince} ngày trước)
          </div>
          
          {/* Follow-up info in tooltip */}
          {followUpInfo && (
            <div className={cn(
              "pt-1 border-t mt-1",
              followUpInfo.isPastDue ? "text-red-500" : 
              followUpInfo.isDueToday ? "text-orange-500" : 
              "text-blue-500"
            )}>
              📅 {followUpInfo.status}: {followUpInfo.exactDate}
            </div>
          )}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

// =============================================================================
// SIMPLE DOT COMPONENT (for ultra-compact display)
// =============================================================================

interface ActivityDotProps {
  date: string | null | undefined;
  coldThresholdDays?: number;
  frozenThresholdDays?: number;
  className?: string;
}

export function ActivityDot({
  date,
  coldThresholdDays = 7,
  frozenThresholdDays = 14,
  className,
}: ActivityDotProps) {
  if (!date) return null;
  
  const dateObj = new Date(date);
  const daysSince = differenceInDays(new Date(), dateObj);
  const level = getActivityLevel(daysSince, coldThresholdDays, frozenThresholdDays);
  const config = ACTIVITY_CONFIG[level];

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <div className={cn(
            "h-2 w-2 rounded-full shrink-0",
            config.dotColor,
            className
          )} />
        </TooltipTrigger>
        <TooltipContent side="top" className="text-xs">
          {config.label} • {daysSince} ngày trước
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

export default ActivityIndicator;

// src/components/common/table/DataTable.tsx
"use client";

import * as React from "react";
import {
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
  type ColumnFiltersState,
  type VisibilityState,
  type RowSelectionState,
} from "@tanstack/react-table";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";
import { Pagination } from "./Pagination";
import { DataTableToolbar } from "./DataTableToolbar";

// =============================================================================
// TYPES
// =============================================================================

export interface DataTableProps<TData, TValue> {
  /** Column definitions */
  columns: ColumnDef<TData, TValue>[];
  /** Data to display */
  data: TData[];
  /** Loading state */
  isLoading?: boolean;
  /** Show toolbar */
  showToolbar?: boolean;
  /** Show search in toolbar */
  showSearch?: boolean;
  /** Search placeholder */
  searchPlaceholder?: string;
  /** Searchable columns */
  searchableColumns?: string[];
  /** Show column visibility toggle */
  showColumnToggle?: boolean;
  /** Show pagination */
  showPagination?: boolean;
  /** Server-side pagination */
  serverSidePagination?: boolean;
  /** Total items (for server-side pagination) */
  totalItems?: number;
  /** Current page (for server-side pagination) */
  page?: number;
  /** Page size (for server-side pagination) */
  pageSize?: number;
  /** Callback when page changes (for server-side pagination) */
  onPageChange?: (page: number) => void;
  /** Callback when page size changes (for server-side pagination) */
  onPageSizeChange?: (size: number) => void;
  /** Enable row selection */
  enableRowSelection?: boolean;
  /** Callback when selection changes */
  onRowSelectionChange?: (rows: TData[]) => void;
  /** Empty state message */
  emptyMessage?: string;
  /** Table container class name */
  containerClassName?: string;
  /** Table class name */
  tableClassName?: string;
}

// =============================================================================
// SKELETON LOADER
// =============================================================================

function TableSkeleton({ columns, rows = 5 }: { columns: number; rows?: number }) {
  return (
    <TableBody>
      {Array.from({ length: rows }).map((_, rowIndex) => (
        <TableRow key={rowIndex}>
          {Array.from({ length: columns }).map((_, colIndex) => (
            <TableCell key={colIndex}>
              <Skeleton className="h-4 w-full" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </TableBody>
  );
}

// =============================================================================
// EMPTY STATE
// =============================================================================

function EmptyState({ colSpan, message }: { colSpan: number; message: string }) {
  return (
    <TableBody>
      <TableRow>
        <TableCell colSpan={colSpan} className="h-24 text-center">
          <div className="flex flex-col items-center justify-center text-muted-foreground">
            <p>{message}</p>
          </div>
        </TableCell>
      </TableRow>
    </TableBody>
  );
}

// =============================================================================
// MAIN COMPONENT
// =============================================================================

export function DataTable<TData, TValue>({
  columns,
  data,
  isLoading = false,
  showToolbar = true,
  showSearch = true,
  searchPlaceholder = "Tim kiem...",
  searchableColumns, // ✅ TECHNICAL DEBT FIX: Implement column-specific search
  showColumnToggle = true,
  showPagination = true,
  serverSidePagination = false,
  totalItems,
  page = 1,
  pageSize = 10,
  onPageChange,
  onPageSizeChange,
  enableRowSelection = false,
  onRowSelectionChange,
  emptyMessage = "Khong co du lieu",
  containerClassName,
  tableClassName,
}: DataTableProps<TData, TValue>) {
  // State
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([]);
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({});
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});
  const [globalFilter, setGlobalFilter] = React.useState("");

  // ✅ TECHNICAL DEBT FIX: Custom global filter function for column-specific search
  const columnSpecificFilter = React.useCallback(
    (row: { getValue: (columnId: string) => unknown }, columnId: string, filterValue: string) => {
      // If searchableColumns is specified, only filter those columns
      if (searchableColumns && searchableColumns.length > 0) {
        // Check if any of the searchable columns match
        for (const column of searchableColumns) {
          const value = row.getValue(column);
          if (value && String(value).toLowerCase().includes(filterValue.toLowerCase())) {
            return true;
          }
        }
        return false;
      }
      
      // Default behavior: filter the current column
      const value = row.getValue(columnId);
      return value ? String(value).toLowerCase().includes(filterValue.toLowerCase()) : false;
    },
    [searchableColumns]
  );

  // Initialize table
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    // Sorting
    onSortingChange: setSorting,
    getSortedRowModel: getSortedRowModel(),
    // Filtering
    onColumnFiltersChange: setColumnFilters,
    getFilteredRowModel: getFilteredRowModel(),
    onGlobalFilterChange: setGlobalFilter,
    globalFilterFn: searchableColumns && searchableColumns.length > 0 ? columnSpecificFilter : "includesString",
    // Visibility
    onColumnVisibilityChange: setColumnVisibility,
    // Selection
    onRowSelectionChange: setRowSelection,
    enableRowSelection,
    // Pagination (client-side)
    getPaginationRowModel: serverSidePagination ? undefined : getPaginationRowModel(),
    // State
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
      globalFilter,
      pagination: serverSidePagination
        ? undefined
        : {
            pageIndex: 0,
            pageSize,
          },
    },
  });

  // Handle row selection change
  React.useEffect(() => {
    if (onRowSelectionChange) {
      const selectedRows = table.getSelectedRowModel().rows.map((row) => row.original);
      onRowSelectionChange(selectedRows);
    }
  }, [rowSelection, table, onRowSelectionChange]);

  // Calculate pagination values
  const paginationTotal = serverSidePagination
    ? totalItems || 0
    : table.getFilteredRowModel().rows.length;
  const paginationPage = serverSidePagination ? page : table.getState().pagination.pageIndex + 1;
  const paginationPageSize = serverSidePagination ? pageSize : table.getState().pagination.pageSize;

  // Handle client-side page change
  const handlePageChange = React.useCallback(
    (newPage: number) => {
      if (serverSidePagination && onPageChange) {
        onPageChange(newPage);
      } else {
        table.setPageIndex(newPage - 1);
      }
    },
    [serverSidePagination, onPageChange, table]
  );

  // Handle page size change
  const handlePageSizeChange = React.useCallback(
    (newSize: number) => {
      if (serverSidePagination && onPageSizeChange) {
        onPageSizeChange(newSize);
      } else {
        table.setPageSize(newSize);
      }
    },
    [serverSidePagination, onPageSizeChange, table]
  );

  return (
    <div className={cn("space-y-4", containerClassName)}>
      {/* Toolbar */}
      {showToolbar && (
        <DataTableToolbar
          table={table}
          showSearch={showSearch}
          searchPlaceholder={searchPlaceholder}
          globalFilter={globalFilter}
          onGlobalFilterChange={setGlobalFilter}
          showColumnToggle={showColumnToggle}
          isLoading={isLoading}
        />
      )}

      {/* Table */}
      <div className="rounded-md border">
        <Table className={tableClassName}>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>

          {/* Loading state */}
          {isLoading && <TableSkeleton columns={columns.length} />}

          {/* Empty state */}
          {!isLoading && data.length === 0 && (
            <EmptyState colSpan={columns.length} message={emptyMessage} />
          )}

          {/* Data rows */}
          {!isLoading && data.length > 0 && (
            <TableBody>
              {table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          )}
        </Table>
      </div>

      {/* Pagination */}
      {showPagination && paginationTotal > 0 && (
        <Pagination
          page={paginationPage}
          pageSize={paginationPageSize}
          total={paginationTotal}
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
          isLoading={isLoading}
        />
      )}
    </div>
  );
}

