// src/components/forms/ChangePasswordForm.tsx
"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useQuery } from "@tanstack/react-query";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { AlertTriangle, ShieldAlert } from "lucide-react";
import { PasswordStrengthIndicator } from "@/components/admin/PasswordStrengthIndicator";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage, // ✅ Thêm FormMessage chuẩn từ shadcn/ui
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { useAuth } from "@/hooks/useAuth";
import { getActiveSessions } from "@/lib/api/sessions";
import type { ChangePasswordSchema } from "@/types/api.types";

// Schema validation
const changePasswordSchema = z
  .object({
    old_password: z.string().min(1, { message: "Mật khẩu hiện tại là bắt buộc" }),
    new_password: z
      .string()
      .min(1, { message: "Mật khẩu là bắt buộc" })
      .min(8, { message: "Mật khẩu phải có ít nhất 8 ký tự" })
      .regex(/[A-Z]/, { message: "Phải chứa chữ cái viết hoa" })
      .regex(/[a-z]/, { message: "Phải chứa chữ cái viết thường" })
      .regex(/[0-9]/, { message: "Phải chứa số" })
      .regex(/[^A-Za-z0-9]/, { message: "Phải chứa ký tự đặc biệt" }),
    confirm_new_password: z.string().min(1, { message: "Vui lòng xác nhận mật khẩu" }),
  })
  // ✅ SECURITY: Ensure new password is different from old password
  .refine((data) => data.new_password !== data.old_password, {
    message: "Mật khẩu mới phải khác mật khẩu hiện tại",
    path: ["new_password"],
  })
  .refine((data) => data.new_password === data.confirm_new_password, {
    message: "Mật khẩu mới không khớp",
    path: ["confirm_new_password"],
  });

type ChangePasswordFormValues = z.infer<typeof changePasswordSchema>;

export function ChangePasswordForm() {
  const { changePassword, isLoading: isChangingPassword } = useAuth();
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);
  const [pendingData, setPendingData] = useState<ChangePasswordFormValues | null>(null);
  
  // C2 SECURITY FIX: Check if user was forced to change password
  const searchParams = useSearchParams();
  const isForced = searchParams.get("forced") === "true";

  // Fetch active sessions count
  const { data: sessionsData, isLoading: isLoadingSessions } = useQuery({
    queryKey: ["sessions"],
    queryFn: getActiveSessions,
    retry: 1,
    staleTime: 5000, // 5 seconds - refresh faster after session changes
    refetchOnWindowFocus: true, // Refetch when user switches back to this tab
  });

  const activeSessionsCount = sessionsData?.total || 0;

  const form = useForm<ChangePasswordFormValues>({
    resolver: zodResolver(changePasswordSchema),
    defaultValues: { old_password: "", new_password: "", confirm_new_password: "" },
    mode: "onChange", // ✅ FIX: Changed from onTouched to onChange for realtime validation
  });

  // Watch new_password for strength indicator
  const newPassword = form.watch("new_password");

  function onSubmit(values: ChangePasswordFormValues) {
    // Show confirmation dialog instead of submitting directly
    setPendingData(values);
    setShowConfirmDialog(true);
  }

  function handleConfirmChange() {
    if (!pendingData) return;

    const apiData: ChangePasswordSchema & { confirm_new_password: string } = {
      old_password: pendingData.old_password,
      new_password: pendingData.new_password,
      confirm_new_password: pendingData.confirm_new_password,
    };

    changePassword(apiData, {
      onSuccess: () => {
        form.reset();
        setShowConfirmDialog(false);
        setPendingData(null);
      },
      onError: () => {
        // Keep dialog open on error so user can retry
        setShowConfirmDialog(false);
      },
    });
  }

  return (
    <div className="w-full max-w-xl space-y-4">
      <h2 className="text-xl font-semibold">Đổi Mật Khẩu</h2>

      {/* C2 SECURITY FIX: Forced password change warning */}
      {isForced && (
        <Alert className="border-red-500 bg-red-50">
          <ShieldAlert className="h-5 w-5 text-red-600" />
          <AlertTitle className="text-red-800">Yêu cầu Đổi Mật Khẩu</AlertTitle>
          <AlertDescription className="text-red-700">
            <p>
              Tài khoản của bạn đã được đánh dấu cần <strong>đổi mật khẩu ngay lập tức</strong>.
              Điều này có thể do bạn đã báo cáo một đăng nhập đáng ngờ.
            </p>
            <p className="mt-2 text-sm">
              Vui lòng đổi mật khẩu để tiếp tục sử dụng hệ thống.
            </p>
          </AlertDescription>
        </Alert>
      )}

      {/* Security Warning Alert */}
      <Alert variant="destructive">
        <AlertTriangle className="h-4 w-4" />
        <AlertTitle>Lưu ý Bảo mật</AlertTitle>
        <AlertDescription className="space-y-2">
          <p>
            Đổi mật khẩu sẽ <strong>đăng xuất bạn khỏi tất cả thiết bị</strong>. Bạn sẽ
            cần đăng nhập lại với mật khẩu mới.
          </p>
          {isLoadingSessions ? (
            <Skeleton className="h-4 w-64" />
          ) : activeSessionsCount > 1 ? (
            <p className="mt-2 text-sm">
              📱 Bạn đang đăng nhập trên <strong>{activeSessionsCount} thiết bị</strong>.
            </p>
          ) : null}
          {activeSessionsCount > 1 && (
            <p className="mt-2 text-sm">
              💡 Mẹo:{" "}
              <Link href="/settings/sessions" className="underline font-medium hover:text-destructive-foreground">
                Xem các phiên đang hoạt động
              </Link>{" "}
              trước khi đổi mật khẩu để phát hiện đăng nhập đáng ngờ.
            </p>
          )}
        </AlertDescription>
      </Alert>

      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
          <FormField
            control={form.control}
            name="old_password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Mật khẩu hiện tại</FormLabel>
                <FormControl>
                  <Input
                    type="password"
                    placeholder="••••••••"
                    disabled={isChangingPassword}
                    {...field}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="new_password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Mật khẩu mới</FormLabel>
                <FormControl>
                  <Input
                    type="password"
                    placeholder="••••••••"
                    disabled={isChangingPassword}
                    {...field}
                  />
                </FormControl>
                {/* ✅ UX FIX: Show password strength indicator */}
                {newPassword && <PasswordStrengthIndicator password={newPassword} />}
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="confirm_new_password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Xác nhận mật khẩu mới</FormLabel>
                <FormControl>
                  <Input
                    type="password"
                    placeholder="••••••••"
                    disabled={isChangingPassword}
                    {...field}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <Button type="submit" disabled={isChangingPassword} className="mt-4">
            {isChangingPassword ? "Đang đổi..." : "Đổi Mật Khẩu"}
          </Button>
        </form>
      </Form>

      {/* Confirmation Dialog */}
      <AlertDialog open={showConfirmDialog} onOpenChange={setShowConfirmDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Xác nhận Đổi Mật Khẩu</AlertDialogTitle>
            <AlertDialogDescription>
              Bạn sẽ bị đăng xuất khỏi{" "}
              <strong>
                {activeSessionsCount === 1 ? "thiết bị này" : `tất cả ${activeSessionsCount} thiết bị`}
              </strong>
              . Bạn có chắc chắn muốn tiếp tục?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isChangingPassword}>Hủy</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmChange}
              disabled={isChangingPassword}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isChangingPassword ? "Đang đổi..." : "Có, Đổi Mật Khẩu"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// src/components/forms/ResetPasswordForm.tsx
"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useSearchParams, useRouter } from "next/navigation"; // Import hooks
import Link from "next/link";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { useAuth } from "@/hooks/useAuth";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Terminal } from "lucide-react";
import { PasswordStrengthIndicator } from "@/components/admin/PasswordStrengthIndicator";
// Tạm định nghĩa
interface ResetPasswordSchema {
  token: string;
  new_password: string;
}

// Schema validation (khớp ResetPasswordSchema backend và thêm confirm password)
const resetPasswordSchema = z
  .object({
    new_password: z
      .string()
      .min(8, { message: "Mật khẩu phải có ít nhất 8 ký tự" })
      .regex(/[A-Z]/, { message: "Phải chứa chữ cái viết hoa" })
      .regex(/[a-z]/, { message: "Phải chứa chữ cái viết thường" })
      .regex(/[0-9]/, { message: "Phải chứa số" })
      .regex(/[^A-Za-z0-9]/, { message: "Phải chứa ký tự đặc biệt" }),
    confirm_new_password: z.string(),
  })
  .refine((data) => data.new_password === data.confirm_new_password, {
    message: "Mật khẩu không khớp",
    path: ["confirm_new_password"],
  });

type ResetPasswordFormValues = z.infer<typeof resetPasswordSchema>;

export function ResetPasswordForm() {
  const { resetPassword, isLoading } = useAuth();
  const searchParams = useSearchParams();
  const router = useRouter();
  const token = searchParams.get("token"); // Lấy token từ URL query param

  const form = useForm<ResetPasswordFormValues>({
    resolver: zodResolver(resetPasswordSchema),
    defaultValues: { new_password: "", confirm_new_password: "" },
    mode: "onChange", // ✅ FIX: Realtime validation
  });

  // Watch new_password for strength indicator
  const newPassword = form.watch("new_password");

  function onSubmit(values: ResetPasswordFormValues) {
    if (!token) return; // Không submit nếu không có token
    // Gửi cả token và password mới (bao gồm confirm để zod refine kiểm tra)
    const apiData: ResetPasswordSchema & { confirm_new_password: string } = {
      token,
      new_password: values.new_password,
      confirm_new_password: values.confirm_new_password,
    };
    resetPassword(apiData);
  }

  // Hiển thị lỗi nếu không có token trong URL
  if (!token) {
    return (
      <div className="mx-auto w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <Terminal className="h-4 w-4" />
          <AlertTitle>Lỗi</AlertTitle>
          <AlertDescription>
            Token đặt lại mật khẩu không hợp lệ hoặc thiếu. Vui lòng yêu cầu liên kết mới.
          </AlertDescription>
        </Alert>
        <Button onClick={() => router.push("/forgot-password")} variant="outline">
          Yêu cầu Liên kết Mới
        </Button>
      </div>
    );
  }

  return (
    <div className="bg-card mx-auto w-full max-w-md space-y-6 rounded border p-6 shadow-md md:p-8">
      <div className="space-y-2 text-center">
        <h1 className="text-2xl font-bold">Đặt Lại Mật Khẩu</h1>
        <p className="text-muted-foreground">Nhập mật khẩu mới của bạn dưới đây.</p>
      </div>
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
          <FormField
            control={form.control}
            name="new_password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Mật khẩu mới</FormLabel>
                <FormControl>
                  <Input type="password" placeholder="••••••••" disabled={isLoading} {...field} />
                </FormControl>
                {/* ✅ UX FIX: Show password strength indicator */}
                {newPassword && <PasswordStrengthIndicator password={newPassword} />}
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="confirm_new_password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Xác nhận mật khẩu mới</FormLabel>
                <FormControl>
                  <Input type="password" placeholder="••••••••" disabled={isLoading} {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <Button type="submit" className="w-full" disabled={isLoading}>
            {isLoading ? "Đang đặt lại..." : "Đặt Lại Mật Khẩu"}
          </Button>
        </form>
      </Form>
      <p className="text-muted-foreground mt-4 text-center text-sm">
        Đã nhớ mật khẩu?{" "}
        <Link href="/login" className="text-primary font-medium hover:underline">
          Đăng nhập
        </Link>
      </p>
    </div>
  );
}

// components/layouts/SocketHandler.tsx
"use client";

import { useEffect, useRef, useState } from "react";
import { useAuthStore } from "@/lib/stores/auth.store";
import { socketService } from "@/lib/socket/client";
import { toast } from "sonner";
import { useAddNotification, useMarkAsRead } from "@/hooks/useNotifications";
import { useNotificationPreferences } from "@/hooks/useNotificationPreferences";
import { playNotificationSound, showBrowserNotification } from "@/lib/sound";
import type { Notification } from "@/types/api.types";
import { useQueryClient } from "@tanstack/react-query";
import { leadsKeys } from "@/hooks/useLeads";

/**
 * Component "vô hình" (không render)
 * Quản lý kết nối Socket.IO và lắng nghe các sự kiện auth toàn cục.
 */
export function SocketHandler() {
  const { isAuthenticated, logout, user } = useAuthStore();
  const addNotification = useAddNotification();
  const markAsRead = useMarkAsRead();  // ✅ For marking as read when user clicks toast action
  const { data: preferences } = useNotificationPreferences();
  const queryClient = useQueryClient();

  // ✅ CẢI TIẾN: Dùng ref cho hàm logout để tránh "stale closure"
  const logoutRef = useRef(logout);
  useEffect(() => {
    logoutRef.current = logout;
  }, [logout]);

  // ✅ FIX: Track socket connection state to trigger listener setup
  const [isSocketConnected, setIsSocketConnected] = useState(false);

  // ✅ SECURITY FIX: Manage Socket.io connection based on authentication state
  // No longer tracks JTI or token - backend reads auth from httpOnly cookies
  // ✅ PHASE 1.1.3: Staggered reconnection with random delay (Thundering Herd protection)
  useEffect(() => {
    if (isAuthenticated) {
      // ✅ PHASE 1.1.3: Add random delay 0-5000ms before connecting
      // This prevents Thundering Herd when backend restarts and all users reconnect simultaneously
      // Connections are spread over 5 seconds instead of all at once
      const delay = Math.random() * 5000;

      console.log(
        `[SocketHandler] User authenticated, connecting Socket.io in ${Math.round(delay)}ms...`
      );

      const timeoutId = setTimeout(() => {
        socketService.connect();
        console.log("[SocketHandler] Socket.io connection initiated after delay");
      }, delay);

      // Cleanup: clear timeout if effect re-runs before connection
      return () => {
        clearTimeout(timeoutId);
        socketService.disconnect();
        setIsSocketConnected(false);
      };
    } else {
      // When not authenticated, disconnect immediately (no delay needed)
      console.log("[SocketHandler] User not authenticated, disconnecting Socket.io...");
      socketService.disconnect();
      // Use queueMicrotask to avoid synchronous setState in effect
      queueMicrotask(() => setIsSocketConnected(false));
      return undefined;
    }
  }, [isAuthenticated]); // Chạy lại khi `isAuthenticated` thay đổi

  // ✅ FIX: Listen for socket connection to trigger listener setup
  useEffect(() => {
    const checkConnection = () => {
      const socket = socketService.getSocket();
      if (socket?.connected && !isSocketConnected) {
        console.log("[SocketHandler] Socket connected, setting up listeners...");
        setIsSocketConnected(true);
      }
    };

    // Check immediately
    checkConnection();

    // Also check when socket emits 'connect' event
    const socket = socketService.getSocket();
    if (socket) {
      const handleConnect = () => {
        console.log("[SocketHandler] Socket 'connect' event received");
        setIsSocketConnected(true);
      };
      socket.on("connect", handleConnect);
      return () => {
        socket.off("connect", handleConnect);
      };
    }

    // Polling fallback for connection state
    const intervalId = setInterval(checkConnection, 500);
    return () => clearInterval(intervalId);
  }, [isAuthenticated, isSocketConnected]);

  // 2. Lắng nghe sự kiện - NOW DEPENDS ON isSocketConnected
  useEffect(() => {
    const socket = socketService.getSocket();
    if (!socket || !isSocketConnected) {
      // Socket chưa sẵn sàng - effect sẽ chạy lại khi isSocketConnected thay đổi
      console.log("[SocketHandler] Socket not ready, waiting...", {
        hasSocket: !!socket,
        isSocketConnected,
      });
      return;
    }

    console.log("[SocketHandler] ✅ Registering event listeners (socket connected)");

    // ✅ SECURITY FIX: Simplified force logout handlers
    // Backend emits to user_room_{user_id}, so all sessions receive the event
    // No need to track JTI client-side - backend manages session invalidation

    // Lắng nghe sự kiện "thu hồi batch" (specific sessions revoked)
    const handleForceLogoutBatch = (data: { revoked_jtis: string[] }) => {
      console.log("[SocketHandler] Received 'force_logout_batch'", data);

      toast.error("Phiên của bạn đã bị thu hồi", {
        description: "Đăng xuất tự động...",
        duration: 5000,
      });

      // Gửi xác nhận về server
      socket.emit("logout_confirmed", {});

      logoutRef.current(); // Clear auth state
      
      // ✅ FIX: Redirect to login page after clearing state
      // logout() only clears state, doesn't redirect
      setTimeout(() => {
        window.location.href = "/login";
      }, 1500); // Short delay to show toast
    };

    // Lắng nghe sự kiện "thu hồi tất cả" (ví dụ: đổi mật khẩu)
    const handleForceLogoutAll = (data: { reason: string }) => {
      console.log("[SocketHandler] Received 'force_logout_all'", data);
      toast.error("Tất cả các phiên đã bị vô hiệu hóa", {
        description: `Lý do: ${data.reason}. Đăng xuất tự động...`,
        duration: 5000,
      });

      // Gửi xác nhận về server
      socket.emit("logout_confirmed", { reason: data.reason });

