"use client";

import { useEffect } from "react";
import { Control, useFieldArray, Path } from "react-hook-form";
import {
  FormControl,
  FormField,
  FormItem,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { ChecklistItem } from "@/types/lead.types";
import type { ApplicationFormValues } from "./LeadApplicationForm";

// TODO: Refactor to use ResolvedDocumentResponse from admission-paths API
// instead of the deprecated admission_method.required_documents
// See: GET /api/admission-config/paths/{id}/documents
interface AdmissionMethodWithDocs {
  id: string | number;
  required_documents?: Array<{
    code: string;
    label: string;
  }> | null;
}

interface DocumentChecklistProps {
  control: Control<ApplicationFormValues>;
  admissionMethod: AdmissionMethodWithDocs | null;
}

export function DocumentChecklist({ control, admissionMethod }: DocumentChecklistProps) {
  const { fields, replace } = useFieldArray({
    control,
    name: "documents.checklist" as const,
  });

  // Update checklist when admission method changes
  useEffect(() => {
    // Handle null case
    if (!admissionMethod) {
      replace([]);
      return;
    }
    
    if (admissionMethod.required_documents) {
      const newChecklist: ChecklistItem[] = admissionMethod.required_documents.map((doc) => ({
        code: doc.code,
        label: doc.label,
        status: "missing" as const,
        submission_type: "N/A" as const,
        notes: "",
      }));
      replace(newChecklist);
    } else {
      replace([]);
    }
  }, [admissionMethod?.id, admissionMethod?.required_documents, replace]);

  if (!fields.length) {
    return (
      <div className="text-center text-muted-foreground py-8">
        Không có hồ sơ bắt buộc cho phương thức này
      </div>
    );
  }

  return (
    <div className="border rounded-lg overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="w-[250px]">Tên Hồ sơ</TableHead>
            <TableHead className="w-[150px]">Trạng thái</TableHead>
            <TableHead className="w-[150px]">Loại hồ sơ</TableHead>
            <TableHead>Ghi chú</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {fields.map((field, index) => (
            <TableRow key={field.id}>
              {/* Tên Hồ sơ (Readonly) */}
              <TableCell className="font-medium">
                <FormField
                  control={control}
                  name={`documents.checklist.${index}.label` as Path<ApplicationFormValues>}
                  render={({ field }) => (
                    <FormItem>
                      <FormControl>
                        <div className="text-sm">{field.value as string}</div>
                      </FormControl>
                    </FormItem>
                  )}
                />
              </TableCell>

              {/* Trạng thái */}
              <TableCell>
                <FormField
                  control={control}
                  name={`documents.checklist.${index}.status` as Path<ApplicationFormValues>}
                  render={({ field }) => (
                    <FormItem>
                      <Select onValueChange={field.onChange} value={field.value as string}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="missing">Missing</SelectItem>
                          <SelectItem value="submitted">Submitted</SelectItem>
                          <SelectItem value="verified">Verified</SelectItem>
                          <SelectItem value="rejected">Rejected</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </TableCell>

              {/* Loại hồ sơ */}
              <TableCell>
                <FormField
                  control={control}
                  name={`documents.checklist.${index}.submission_type` as Path<ApplicationFormValues>}
                  render={({ field }) => (
                    <FormItem>
                      <Select onValueChange={field.onChange} value={field.value as string}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="N/A">N/A</SelectItem>
                          <SelectItem value="photocopy">Photocopy</SelectItem>
                          <SelectItem value="notarized">Notarized</SelectItem>
                          <SelectItem value="original">Original</SelectItem>
                          <SelectItem value="incomplete">Incomplete</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </TableCell>

              {/* Ghi chú */}
              <TableCell>
                <FormField
                  control={control}
                  name={`documents.checklist.${index}.notes` as Path<ApplicationFormValues>}
                  render={({ field }) => (
                    <FormItem>
                      <FormControl>
                        <Input
                          placeholder="Nhập ghi chú..."
                          {...field}
                          value={field.value as string}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

