                    <FormItem>
                      <FormLabel className="flex items-center gap-1.5">
                        <MapPin className="h-3.5 w-3.5" />
                        Địa chỉ
                      </FormLabel>
                      <FormControl>
                        <Input
                          placeholder="TP. Hồ Chí Minh"
                          {...field}
                          value={field.value ?? ""}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="location_proximity"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Khu vực</FormLabel>
                      <Select
                        onValueChange={(val) => field.onChange(parseInt(val))}
                        value={field.value?.toString() || "0"}
                      >
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Đánh giá khoảng cách" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="0">Xa / Không xác định</SelectItem>
                          <SelectItem value="1">Tỉnh lân cận (+2đ)</SelectItem>
                          <SelectItem value="2">Gần cơ sở (+5đ)</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <FormField
                control={form.control}
                name="occupation_relevance"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Nghề nghiệp</FormLabel>
                    <Select
                      onValueChange={(val) => field.onChange(parseInt(val))}
                      value={field.value?.toString() || "0"}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Đánh giá độ phù hợp" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="0">Không liên quan / Chưa xác định</SelectItem>
                        <SelectItem value="1">Liên quan gián tiếp (+2đ)</SelectItem>
                        <SelectItem value="2">Liên quan trực tiếp (+5đ)</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                disabled={isSubmitting}
              >
                Hủy
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {isCreate ? "Tạo Lead" : "Lưu thay đổi"}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </FormDialog>
  );
}

// src/components/leads/LeadTimelineTab.tsx
"use client";

import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Clock,
  User,
  FileText,
  Phone,
  Mail,
  MessageSquare,
  Calendar,
  UserPlus,
  Video,
  Trash2,
  Edit,
  MoreVertical,
} from "lucide-react";
import { useLeadTimeline, useDeleteConsultation } from "@/hooks/useLeads";
import { format, isToday, isYesterday, parseISO } from "date-fns";
import { vi } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { ConsultationDialog } from "./ConsultationDialog";
import type { Consultation, TimelineItem as TimelineItemBase } from "@/types/lead.types";

// Extended timeline type for backward compatibility with old structure
type TimelineItem = TimelineItemBase & {
  data?: Consultation | { method?: string } | Record<string, unknown>;
};

interface LeadTimelineTabProps {
  leadId: number;
  /** Maximum items to show initially. Set 0 or undefined to show all. */
  maxItems?: number;
}

// Get icon and color based on event type and method
const getEventConfig = (eventType: string, method?: string) => {
  // Consultation events - differentiate by method
  if (eventType === "consultation") {
    switch (method) {
      case "phone":
        return {
          icon: Phone,
          color: "text-slate-600",
          bgColor: "bg-slate-100",
          ringColor: "ring-slate-200",
          label: "Cuộc gọi",
        };
      case "email":
        return {
          icon: Mail,
          color: "text-slate-600",
          bgColor: "bg-slate-100",
          ringColor: "ring-slate-200",
          label: "Email",
        };
      case "video":
        return {
          icon: Video,
          color: "text-slate-600",
          bgColor: "bg-slate-100",
          ringColor: "ring-slate-200",
          label: "Video call",
        };
      case "in_person":
        return {
          icon: User,
          color: "text-slate-600",
          bgColor: "bg-slate-100",
          ringColor: "ring-slate-200",
          label: "Gặp trực tiếp",
        };
      default:
        return {
          icon: MessageSquare,
          color: "text-slate-600",
          bgColor: "bg-slate-100",
          ringColor: "ring-slate-200",
          label: "Tư vấn",
        };
    }
  }

  // Assignment events (backend sends "assignment", frontend may use "assigned")
  if (eventType === "assignment" || eventType === "assigned") {
    return {
      icon: UserPlus,
      color: "text-slate-600",
      bgColor: "bg-slate-100",
      ringColor: "ring-slate-200",
      label: "Phân công",
    };
  }

  // Default
  return {
    icon: Clock,
    color: "text-slate-600",
    bgColor: "bg-slate-100",
    ringColor: "ring-slate-200",
    label: "Hoạt động",
  };
};

// Format date for grouping
const formatDateGroup = (dateString: string) => {
  const date = parseISO(dateString);
  if (isToday(date)) return "Hôm nay";
  if (isYesterday(date)) return "Hôm qua";
  return format(date, "EEEE, dd/MM/yyyy", { locale: vi });
};

// Group timeline by date
const groupTimelineByDate = (timeline: TimelineItem[]) => {
  const groups: Record<string, typeof timeline> = {};

  // Sort by date descending (newest first)
  const sorted = [...timeline].sort((a, b) => {
    const dateA = new Date(a.timestamp || 0);
    const dateB = new Date(b.timestamp || 0);
    return dateB.getTime() - dateA.getTime();
  });

  sorted.forEach((event) => {
    const dateKey = format(
      parseISO(event.timestamp || new Date().toISOString()),
      "yyyy-MM-dd"
    );
    if (!groups[dateKey]) {
      groups[dateKey] = [];
    }
    groups[dateKey].push(event);
  });

  return groups;
};

// Get initials from name
const getInitials = (name: string) => {
  return name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);
};

export function LeadTimelineTab({ leadId, maxItems }: LeadTimelineTabProps) {
  const { data: timeline, isLoading } = useLeadTimeline(leadId);
  const deleteMutation = useDeleteConsultation();
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedConsultationId, setSelectedConsultationId] = useState<number | null>(null);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingConsultation, setEditingConsultation] = useState<Consultation | null>(null);
  const [showAll, setShowAll] = useState(false);

  if (isLoading || !timeline) {
    return (
      <div className="space-y-4">
        {[...Array(3)].map((_, i) => (
          <Skeleton key={i} className="h-24 w-full rounded-lg" />
        ))}
      </div>
    );
  }

  if (timeline.length === 0) {
    return (
      <div className="text-center py-12 text-muted-foreground bg-slate-50/50 rounded-lg border border-dashed">
        <MessageSquare className="h-10 w-10 mx-auto mb-3 opacity-20" />
        <p className="font-medium">Chưa có hoạt động nào</p>
        <p className="text-xs mt-1">Lịch sử tương tác sẽ xuất hiện tại đây</p>
      </div>
    );
  }

  const groupedTimeline = groupTimelineByDate(timeline);
  const dateKeys = Object.keys(groupedTimeline).sort().reverse();

  // Calculate items to show based on maxItems prop
  const hasLimit = maxItems && maxItems > 0 && !showAll;
  const totalItems = timeline.length;
  const remainingItems = hasLimit ? Math.max(0, totalItems - maxItems) : 0;
  
  // Limit items if maxItems is set and showAll is false
  const itemsToShow = hasLimit ? maxItems : totalItems;
  let itemCount = 0;

  const handleEditConsultation = (consultation: Consultation) => {
    setEditingConsultation(consultation);
    setEditDialogOpen(true);
  };

  const handleDeleteConsultation = (consultationId: number) => {
    setSelectedConsultationId(consultationId);
    setDeleteDialogOpen(true);
  };

  const confirmDelete = () => {
    if (selectedConsultationId) {
      deleteMutation.mutate(
        { leadId, consultationId: selectedConsultationId },
        {
          onSuccess: () => {
            setDeleteDialogOpen(false);
            setSelectedConsultationId(null);
          },
        }
      );
    }
  };

  return (
    <>
      <div className="space-y-8">
        {dateKeys.map((dateKey) => {
          // Get items for this date
          const dateItems = groupedTimeline[dateKey];
          
          // Filter items based on limit
          const visibleItems = dateItems.filter(() => {
            if (!hasLimit) return true;
            if (itemCount >= itemsToShow) return false;
            itemCount++;
            return true;
          });

          // Skip entire date group if no visible items
          if (visibleItems.length === 0) return null;

          return (
          <div key={dateKey}>
            {/* Date Header */}
            <div className="flex items-center gap-3 mb-4">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm font-semibold text-foreground">
                {formatDateGroup(dateKey + "T00:00:00")}
              </span>
              <div className="flex-1 h-px bg-border" />
            </div>

            {/* Events for this date - with connecting line */}
            <div className="relative pl-6 space-y-6">
              {/* Connecting line */}
              <div className="absolute left-[15px] top-3 bottom-3 w-0.5 bg-gradient-to-b from-border via-border to-transparent" />

              {visibleItems.map((event, index) => {
                const eventType = event.type || "lead_created";
                // ✅ TECHNICAL DEBT FIX: Use typed event data instead of `as any`
                const eventData = event.data || {};

                // Type guard helpers for typed data access
                const getConsultationData = () => eventData as import("@/types/lead.types").ConsultationEventData;
                const getAssignmentData = () => eventData as import("@/types/lead.types").AssignmentEventData;

                // ✅ FIX: Match actual backend event types ("consultation", "assignment")
                // Backend sends: type: "consultation" | "assignment"
                // NOT "consultation_added", "consultation_updated", or "assigned"
                const isConsultation = eventType === "consultation" || eventType === "consultation_added" || eventType === "consultation_updated";
                const isAssignment = eventType === "assignment" || eventType === "assigned";

                const config = getEventConfig(
                  eventType,
                  isConsultation ? (eventData.method as string) : undefined
                );
                const Icon = config.icon;

                // Generate title and subtitle
                let title = "";
                let subtitle = "";
                let actorName = "";
                
                // Type assertion for consultation data (used in JSX below)
                const consultData = isConsultation ? (eventData as Consultation) : null;

                if (isConsultation && consultData) {
                  const statusName = consultData.consultation_status?.name || "Tư vấn";
                  title = statusName;

                  // Only show notes if it's not the auto-generated "Ghi nhận nhanh: {status}" format
                  const autoNotePattern = `Ghi nhận nhanh: ${statusName}`;
                  const notes = consultData.notes || "";
                  if (notes && notes !== autoNotePattern) {
                    subtitle = notes;
                  }

                  actorName = consultData.officer?.full_name || "";
                } else if (isAssignment) {
                  // Type assertion for assignment data
                  const assignData = eventData as { reason?: string; officer?: { full_name?: string } };
                  title = "Phân công lead";
                  subtitle = assignData.reason || "Lead được gán cho officer";
                  actorName = assignData.officer?.full_name || "";
                }

                return (
                  <div key={index} className="relative flex gap-3 group">
                    {/* Timeline Dot (Icon) - smaller and neutral */}
                    <div
                      className={cn(
                        "relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 border-white shadow-sm transition-all ring-1",
                        config.bgColor,
                        config.ringColor
                      )}
                    >
                      <Icon className={cn("h-3.5 w-3.5", config.color)} />
                    </div>

                    {/* Content Block */}
                    <div className="flex-1 bg-card rounded-lg border shadow-sm transition-all hover:shadow-md hover:border-primary/30">
                      <div className="p-4">
                        {/* Header: Title, Actor, Time, Actions */}
                        <div className="flex items-start justify-between gap-3 mb-2">
                          <div className="flex-1 min-w-0">
                            {/* Title with method badge */}
                            <div className="flex items-center gap-2 mb-1">
                              <h4 className="font-semibold text-sm text-foreground">
                                {title}
                              </h4>
                              {isConsultation && consultData?.method && (
                                <Badge
                                  variant="secondary"
                                  className="text-[10px] px-1.5 py-0 font-normal"
                                >
                                  {config.label}
                                </Badge>
                              )}
                            </div>

                            {/* Actor and time */}
                            <div className="flex items-center gap-2 text-xs text-muted-foreground">
                              {actorName && (
                                <>
                                  <Avatar className="h-4 w-4">
                                    <AvatarFallback className="text-[8px] bg-primary/10">
                                      {getInitials(actorName)}
                                    </AvatarFallback>
                                  </Avatar>
                                  <span className="font-medium">{actorName}</span>
                                  <span>•</span>
                                </>
                              )}
                              <time>
                                {format(parseISO(event.timestamp || ""), "HH:mm")}
                              </time>
                            </div>
                          </div>

                          {/* Actions Menu */}
                          {isConsultation && consultData?.id && (
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  className="h-7 w-7 p-0 opacity-0 group-hover:opacity-100 transition-opacity"
                                >
                                  <MoreVertical className="h-4 w-4 text-muted-foreground" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem
                                  onClick={() => handleEditConsultation(consultData)}
                                >
                                  <Edit className="h-4 w-4 mr-2" />
                                  Sửa
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  className="text-destructive focus:text-destructive"
                                  onClick={() => handleDeleteConsultation(consultData.id)}
                                >
                                  <Trash2 className="h-4 w-4 mr-2" />
                                  Xóa
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          )}
                        </div>

                        {/* Body: Description/Notes - only if not redundant */}
                        {subtitle && (
                          <div className="text-sm text-muted-foreground leading-relaxed mb-3">
                            <div className="flex items-start gap-2">
                              <FileText className="h-3.5 w-3.5 shrink-0 mt-0.5 opacity-40" />
                              <p className="flex-1">{subtitle}</p>
                            </div>
                          </div>
                        )}

                        {/* Footer: Metadata badges */}
                        {(isConsultation || isAssignment) && (
                          <div className="flex flex-wrap gap-2">
                            {/* Consultation: Scheduled follow-up */}
                            {isConsultation && consultData?.scheduled_at && (
                              <Badge
                                variant="outline"
                                className="text-xs font-normal gap-1 border-blue-200 bg-blue-50 text-blue-700"
                              >
                                <Calendar className="h-3 w-3" />
                                Hẹn: {format(parseISO(consultData.scheduled_at), "dd/MM HH:mm")}
                              </Badge>
                            )}

                            {/* Consultation: Duration */}
                            {isConsultation && consultData?.duration_minutes && consultData.duration_minutes > 0 && (
                              <Badge
                                variant="outline"
                                className="text-xs font-normal gap-1 border-slate-200 bg-slate-50 text-slate-600"
                              >
                                <Clock className="h-3 w-3" />
                                {consultData.duration_minutes} phút
                              </Badge>
                            )}

                            {/* Assignment: Method (automatic, officer_reassign, manual) */}
                            {isAssignment && (eventData as { method?: string }).method && (
                              <Badge
                                variant="outline"
                                className={cn(
                                  "text-xs font-normal gap-1",
                                  (eventData as { method?: string }).method === "automatic" && "border-purple-200 bg-purple-50 text-purple-700",
                                  (eventData as { method?: string }).method === "officer_reassign" && "border-blue-200 bg-blue-50 text-blue-700",
                                  (eventData as { method?: string }).method === "manual" && "border-orange-200 bg-orange-50 text-orange-700"
                                )}
                              >
                                {(eventData as { method?: string }).method === "automatic" && "Tự động"}
                                {(eventData as { method?: string }).method === "officer_reassign" && "Yêu cầu phân công lại"}
                                {(eventData as { method?: string }).method === "manual" && "Thủ công"}
                              </Badge>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
          );
        })}
      </div>

      {/* Load more button */}
      {remainingItems > 0 && (
        <div className="mt-4 text-center">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowAll(true)}
            className="text-muted-foreground hover:text-foreground"
          >
            Tải thêm ({remainingItems} mục)
          </Button>
        </div>
      )}

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Xóa ghi nhận tư vấn?</AlertDialogTitle>
            <AlertDialogDescription>
              Hành động này không thể hoàn tác. Ghi nhận tư vấn sẽ bị xóa vĩnh viễn khỏi timeline.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Hủy</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Xóa
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Edit Consultation Dialog */}
      <ConsultationDialog
        open={editDialogOpen}
        onOpenChange={setEditDialogOpen}
        leadId={leadId}
        consultation={editingConsultation}
        mode="edit"
      />
    </>
  );
}

// src/components/leads/QuickConsultationSection.tsx
"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { format, addMinutes, addHours, addDays, set } from "date-fns";
import { vi } from "date-fns/locale";
import {
  Loader2,
  Clock,
  CalendarClock,
  ArrowRight,
  HelpCircle,
  PhoneForwarded,
  BookmarkCheck,
  NotebookPen,
  Phone,
  MessageSquare,
  Mail,
  Video,
  User,
  CheckCircle2
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { DateTimePicker } from "@/components/common/form";
import { cn } from "@/lib/utils";
import { useAllowedNextStatuses } from "@/hooks/usePipeline";
import { useAddConsultation, useLead } from "@/hooks/useLeads";
import type { ConsultationStatus, ConsultationCreate, ConsultationMethod } from "@/types/lead.types";

interface QuickConsultationSectionProps {
  leadId: number;
  onSuccess?: () => void;
}

// Schedule option type
type ScheduleOption = "none" | "30m" | "1h" | "tomorrow" | "custom";

// Method options configuration
const methodOptions: { value: ConsultationMethod; label: string; icon: React.ElementType }[] = [
  { value: "phone", label: "Gọi điện", icon: Phone },
  { value: "email", label: "Email", icon: Mail },
  { value: "video_call", label: "Video", icon: Video },
  { value: "sms", label: "SMS", icon: MessageSquare },
  { value: "in_person", label: "Gặp mặt", icon: User },
];

// Get scheduled datetime based on option
const getScheduledDateTime = (option: ScheduleOption, customDate?: Date): string | null => {
  const now = new Date();

  switch (option) {
    case "none":
      return null;
    case "30m":
      return addMinutes(now, 30).toISOString();
    case "1h":
      return addHours(now, 1).toISOString();
    case "tomorrow":
      // Tomorrow at 9:00 AM
      const tomorrow = addDays(now, 1);
      return set(tomorrow, { hours: 9, minutes: 0, seconds: 0, milliseconds: 0 }).toISOString();
    case "custom":
      return customDate ? customDate.toISOString() : null;
    default:
      return null;
  }
};

// Get preview text for schedule option
const getSchedulePreviewText = (option: ScheduleOption, customDate?: Date): string => {
  const now = new Date();
  switch (option) {
    case "30m":
      return format(addMinutes(now, 30), "'Gọi lại lúc' HH:mm", { locale: vi });
    case "1h":
      return format(addHours(now, 1), "'Gọi lại lúc' HH:mm", { locale: vi });
    case "tomorrow":
      return "Gọi lại lúc 09:00 ngày mai";
    case "custom":
      return customDate
        ? format(customDate, "'Gọi lại lúc' HH:mm, EEEE dd/MM", { locale: vi })
        : "Chọn thời gian...";
    default:
      return "";
  }
};



export function QuickConsultationSection({ leadId, onSuccess }: QuickConsultationSectionProps) {
  // Get lead data to determine current consultation status
  const { data: lead } = useLead(leadId);
  const currentStatusId = lead?.consultation_status_id;

  // Get allowed next statuses based on state machine
  const {
    data: statuses = [],
    isLoading: statusesLoading,
    error,
    isError,
  } = useAllowedNextStatuses(currentStatusId);
  const addConsultation = useAddConsultation();

  // Form state
  const [notes, setNotes] = useState("");
  const [scheduleOption, setScheduleOption] = useState<ScheduleOption>("none");
  const [customDateTime, setCustomDateTime] = useState<Date | undefined>(undefined);
  const [savingStatusId, setSavingStatusId] = useState<string | null>(null);
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false);
  const [method, setMethod] = useState<ConsultationMethod>("phone");

  // ✅ DELAYED COMMIT STATE
  const COUNTDOWN_SECONDS = 3;
  const [pendingStatus, setPendingStatus] = useState<ConsultationStatus | null>(null);
  const [countdown, setCountdown] = useState(COUNTDOWN_SECONDS);
  const countdownRef = useRef<NodeJS.Timeout | null>(null);

  // Cleanup timer on unmount
  useEffect(() => {
    return () => {
      if (countdownRef.current) {
        clearInterval(countdownRef.current);
      }
    };
  }, []);

  // Countdown logic - when countdown reaches 0, commit the save
  useEffect(() => {
    if (pendingStatus && countdown === 0) {
      commitSave(pendingStatus);
    }
  }, [countdown, pendingStatus]);

  // Start countdown when pending status is set
  const startCountdown = (status: ConsultationStatus) => {
    // Clear any existing timer
    if (countdownRef.current) {
      clearInterval(countdownRef.current);
    }
    
    setPendingStatus(status);
    setCountdown(COUNTDOWN_SECONDS);
    
    countdownRef.current = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          if (countdownRef.current) {
            clearInterval(countdownRef.current);
          }
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  // Cancel pending save
  const cancelPending = () => {
    if (countdownRef.current) {
      clearInterval(countdownRef.current);
    }
    setPendingStatus(null);
    setCountdown(COUNTDOWN_SECONDS);
  };

  // Commit the save immediately
  const commitSave = async (status: ConsultationStatus) => {
    if (countdownRef.current) {
      clearInterval(countdownRef.current);
    }
    
    // Determine scheduled_at based on option
    let scheduledAt: string | null = null;
    if (scheduleOption === "custom" && customDateTime) {
      scheduledAt = customDateTime.toISOString();
    } else {
      scheduledAt = getScheduledDateTime(scheduleOption);
    }

    const payload: ConsultationCreate = {
      status_id: status.id,
      method: method,
      notes: notes.trim() || `Ghi nhận: ${status.name}`,
      scheduled_at: scheduledAt,
    };

    try {
      setSavingStatusId(status.id);
      setPendingStatus(null);
      setCountdown(COUNTDOWN_SECONDS);
      
      await addConsultation.mutateAsync({ leadId, data: payload });

      // Reset form on success
      setNotes("");
      setScheduleOption("none");
      setCustomDateTime(undefined);

      onSuccess?.();
    } catch {
      // Error is handled by the mutation
    } finally {
      setSavingStatusId(null);
    }
  };

  // Handle status badge click - start delayed commit
  const handleStatusClick = (status: ConsultationStatus) => {
    // If clicking the same pending status, do nothing
    if (pendingStatus?.id === status.id) return;
    
    // If there's a different pending status, switch to new one
    startCountdown(status);
  };

  // ✅ Drag-to-scroll using callback refs
  // Callback refs are called when element mounts, guaranteeing element exists
  const resultHasDraggedRef = useRef(false);
  const universalHasDraggedRef = useRef(false);
  
  const setupDragToScroll = (element: HTMLDivElement | null, hasDraggedRef: React.MutableRefObject<boolean>) => {
    if (!element) return;
    
    const isDragging = { current: false };
    const startX = { current: 0 };
    const scrollLeftStart = { current: 0 };
    
    // Wheel scroll handler
    const handleWheel = (e: WheelEvent) => {
      if (e.deltaY === 0) return;
      if (element.scrollWidth <= element.clientWidth) return;

      const { scrollLeft: sl, scrollWidth, clientWidth } = element;
      const maxScrollLeft = scrollWidth - clientWidth;

      if (e.deltaY > 0 && sl >= maxScrollLeft - 1) return;
      if (e.deltaY < 0 && sl <= 1) return;

      e.preventDefault();
      element.scrollLeft += e.deltaY;
    };

    const handleMouseDown = (e: MouseEvent) => {
      if (e.button !== 0) return;
      hasDraggedRef.current = false;
      isDragging.current = true;
      startX.current = e.pageX - element.offsetLeft;
      scrollLeftStart.current = element.scrollLeft;
      element.style.cursor = "grabbing";
      element.style.userSelect = "none";
    };

    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging.current) return;
      e.preventDefault();
      const x = e.pageX - element.offsetLeft;
      const walk = (x - startX.current) * 1.5;
      if (Math.abs(x - startX.current) > 5) hasDraggedRef.current = true;
      element.scrollLeft = scrollLeftStart.current - walk;
    };

    const handleMouseUp = () => {
      if (!isDragging.current) return;
      isDragging.current = false;
      element.style.cursor = "grab";
      element.style.removeProperty("user-select");
    };

    const handleMouseLeave = () => {
      if (isDragging.current) {
        isDragging.current = false;
        element.style.cursor = "grab";
        element.style.removeProperty("user-select");
      }
    };

    element.style.cursor = "grab";
    element.addEventListener("wheel", handleWheel, { passive: false });
    element.addEventListener("mousedown", handleMouseDown);
    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleMouseUp);
    element.addEventListener("mouseleave", handleMouseLeave);
  };
  
  // Callback refs that setup listeners when elements mount
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
  const universalScrollRef = useRef<HTMLDivElement | null>(null);
  
  // Setup when component mounts
  useEffect(() => {
    if (scrollContainerRef.current) {
      setupDragToScroll(scrollContainerRef.current, resultHasDraggedRef);
    }
    if (universalScrollRef.current) {
      setupDragToScroll(universalScrollRef.current, universalHasDraggedRef);
    }
  }, [statuses]); // Re-run when statuses change (containers might re-render)

  // ✅ REFACTORED GROUPING LOGIC (Previous -> Same -> Next)
  const groupedStatuses = useMemo(() => {
    // 1. Universal (Toàn cục - Row 1)
    const universal: ConsultationStatus[] = [];
    
    // 2. Result Groups (Kết quả - Row 2)
    const previousStage: ConsultationStatus[] = [];
    const sameStage: ConsultationStatus[] = [];
    const nextStage: ConsultationStatus[] = [];

    // Find current status to determine current stage order
    // We try to find it in the fetched statuses first (since backend includes current status now)
    const currentStatusObj = statuses.find(s => s.id === currentStatusId);
    const currentStageOrder = currentStatusObj?.stage?.order ?? -1;
    const currentStageId = currentStatusObj?.stage_id;

    const displayStatuses = statuses.filter(s => {
      if (s.is_universal) {
        universal.push(s);
        return false; // Move to universal array
      }
      return true;
    });

    displayStatuses.forEach((status) => {
      // Logic: Previous vs Same vs Next
      // We rely on stage.order. If stage info is missing, fallback to 'next' or 'same'?
      // Since we updated schema, status.stage should be available.
      const statusStageOrder = status.stage?.order ?? -1;

      // Grouping logic
      if (statusStageOrder < currentStageOrder && statusStageOrder !== -1 && currentStageOrder !== -1) {
        // PREVIOUS STAGE (Revert)
        previousStage.push(status);
      } else if (statusStageOrder === currentStageOrder || status.stage_id === currentStageId) {
        // SAME STAGE (Sibling / Current)
        sameStage.push(status);
      } else {
        // NEXT STAGE (Progress)
        nextStage.push(status);
      }
    });

    // Sort Previous desc (closest to current first? or asc?) -> Let's do Ascending order
    previousStage.sort((a, b) => (a.stage?.order ?? 0) - (b.stage?.order ?? 0));
    
    // Sort Next asc
    nextStage.sort((a, b) => (a.stage?.order ?? 0) - (b.stage?.order ?? 0));

    // Sort Same Stage: Current status first, then others by name
    sameStage.sort((a, b) => {
      if (a.id === currentStatusId) return -1;
      if (b.id === currentStatusId) return 1;
      return a.name.localeCompare(b.name);
    });

    return { universal, previousStage, sameStage, nextStage };
  }, [statuses, currentStatusId]);

  // Loading state
  if (statusesLoading) {
    return (
      <div className="flex items-center justify-center p-4">
        <Loader2 className="text-muted-foreground h-5 w-5 animate-spin" />
      </div>
    );
  }

  // Error state
  if (isError) {
    return (
      <div className="rounded-md bg-red-50 p-4 text-sm text-red-600">
        <p className="font-medium">Không thể tải trạng thái</p>
        <p className="mt-1 text-xs">{error?.message || "Lỗi không xác định"}</p>
      </div>
    );
  }

  // Empty state
  if (statuses.length === 0) {
    return (
      <div className="text-muted-foreground bg-muted/50 rounded-md p-4 text-sm">
        <p>Không có trạng thái nào được cấu hình.</p>
        <p className="mt-1 text-xs">Vui lòng liên hệ Admin để thiết lập.</p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Method Selector */}
      <div className="space-y-1.5">
        <Label className="text-muted-foreground flex items-center gap-1 text-xs">
          <Phone className="h-3 w-3" />
          Phương thức
        </Label>
        <ToggleGroup
          type="single"
          value={method}
          onValueChange={(value) => value && setMethod(value as ConsultationMethod)}
          className="flex justify-start gap-1"
        >
          {methodOptions.map((opt) => {
            const Icon = opt.icon;
            return (
              <ToggleGroupItem
                key={opt.value}
                value={opt.value}
                size="sm"
                className={cn(
                  "h-8 gap-1.5 px-2.5 text-xs",
                  "data-[state=on]:bg-primary data-[state=on]:text-primary-foreground"
                )}
              >
                <Icon className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">{opt.label}</span>
              </ToggleGroupItem>
            );
          })}
        </ToggleGroup>
      </div>

      {/* Notes Input */}
      <div className="space-y-1.5">
        <Label
          htmlFor="quick-notes"
          className="text-muted-foreground flex items-center gap-1 text-xs"
        >
          <NotebookPen className="h-3 w-3" />
          Nội dung tư vấn (tùy chọn)
        </Label>
        <Textarea
          id="quick-notes"
          placeholder="VD: KH hẹn gọi lại lúc 3h chiều..."
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={2}
          className="resize-none text-sm"
        />
      </div>

      {/* Schedule Section with ToggleGroup */}
      <div className="space-y-2">
        <Label className="text-muted-foreground flex items-center gap-1.5 text-xs">
          <Clock className="h-3 w-3" />
          Hẹn gọi lại
        </Label>

        <ToggleGroup
          type="single"
          value={scheduleOption}
          onValueChange={(value) => {
            if (value) {
              setScheduleOption(value as ScheduleOption);
              // Tự động mở DateTimePicker khi chọn "Tùy chọn"
              if (value === "custom") {
                setIsDatePickerOpen(true);
              }
            }
          }}
          className="flex flex-wrap justify-start gap-1"
        >
          <ToggleGroupItem
            value="none"
            size="sm"
            className="data-[state=on]:bg-primary data-[state=on]:text-primary-foreground h-7 px-2.5 text-xs"
          >
            Không
          </ToggleGroupItem>
          <ToggleGroupItem
            value="30m"
            size="sm"
            className="data-[state=on]:bg-primary data-[state=on]:text-primary-foreground h-7 px-2.5 text-xs"
          >
            30p
          </ToggleGroupItem>
          <ToggleGroupItem
            value="1h"
            size="sm"
            className="data-[state=on]:bg-primary data-[state=on]:text-primary-foreground h-7 px-2.5 text-xs"
          >
            1h
          </ToggleGroupItem>
          <ToggleGroupItem
            value="tomorrow"
            size="sm"
            className="data-[state=on]:bg-primary data-[state=on]:text-primary-foreground h-7 px-2.5 text-xs"
          >
            Ngày mai
          </ToggleGroupItem>
          <ToggleGroupItem
            value="custom"
            size="sm"
            className="data-[state=on]:bg-primary data-[state=on]:text-primary-foreground h-7 px-2.5 text-xs"
          >
            <CalendarClock className="mr-1 h-3 w-3" />
            Tùy chọn
          </ToggleGroupItem>
        </ToggleGroup>

        {/* Custom DateTime Picker */}
        {scheduleOption === "custom" && (
          <div className="pt-2">
            <DateTimePicker
              value={customDateTime}
              onChange={(date) => setCustomDateTime(date)}
              placeholder="Chọn ngày giờ"
              minDate={new Date()}
              className="h-8 text-xs"
              open={isDatePickerOpen}
              onOpenChange={setIsDatePickerOpen}
              hideTrigger
            />
          </div>
        )}

        {/* Enhanced Schedule Preview */}
        {scheduleOption !== "none" && (
          <div className="flex items-center gap-2 rounded-md border border-blue-100 bg-blue-50 px-3 py-2">
            <CalendarClock className="h-4 w-4 flex-shrink-0 text-blue-600" />
            <span className="text-sm font-medium text-blue-700">
              {getSchedulePreviewText(scheduleOption, customDateTime)}
            </span>
          </div>
        )}
      </div>

      {/* Divider */}
      <div className="border-t pt-3">
        {/* ROW 1: Universal Statuses (Trạng thái liên hệ) */}
        {groupedStatuses.universal.length > 0 && (
          <div className="mb-4">
            <div className="text-muted-foreground mb-2 flex items-center gap-2 text-xs">
              <PhoneForwarded className="h-3 w-3" />
              <span className="font-medium">Trạng thái liên hệ</span>
              <Badge
                variant="secondary"
                className="ml-1 h-4 bg-amber-100 px-1.5 text-[10px] text-amber-700"
              >
                không đổi trạng thái
              </Badge>
            </div>
            {/* ✅ Horizontal scroll container with drag-to-scroll */}
            <div
              ref={universalScrollRef}
              className="flex flex-nowrap items-center gap-2.5 cursor-grab overflow-x-auto overflow-y-hidden overscroll-x-contain [-ms-overflow-style:none] [scrollbar-width:none] active:cursor-grabbing [&::-webkit-scrollbar]:hidden"
            >
              {groupedStatuses.universal.map((status) => (
                <Button
                  key={status.id}
                  variant="ghost"
                  size="sm"
                  className={cn(
                    "h-7 flex-shrink-0 px-2.5 text-xs",
                    "border border-amber-200 bg-amber-50 text-amber-700 hover:bg-amber-100",
                    "transition-all hover:scale-[1.02]",
                    // Pending highlight
                    pendingStatus?.id === status.id && "ring-2 ring-blue-500 ring-offset-1 scale-105"
                  )}
                  onClick={() => {
                    if (universalHasDraggedRef.current) {
                      universalHasDraggedRef.current = false;
                      return;
                    }
                    handleStatusClick(status);
                  }}
                  disabled={addConsultation.isPending}
                >
                  {savingStatusId === status.id ? (
                    <Loader2 className="mr-1.5 h-3 w-3 animate-spin" />
                  ) : (
                    <span
                      className="mr-1.5 h-1.5 w-1.5 flex-shrink-0 rounded-full"
                      style={{ backgroundColor: status.color_code }}
                    />
                  )}
                  {status.name}
                </Button>
              ))}
            </div>
          </div>
        )}

        {/* ROW 2: Result Statuses (Kết quả liên hệ) - Sorted by Stage Progression */}
        {(groupedStatuses.previousStage.length > 0 || groupedStatuses.sameStage.length > 0 || groupedStatuses.nextStage.length > 0) && (
          <div className="space-y-2">
            {/* Header with help tooltip */}
            <div className="flex items-center gap-1">
              <BookmarkCheck className="text-muted-foreground h-3 w-3 text-xs" />
              <Label className="text-muted-foreground text-xs">Kết quả liên hệ ({lead?.pipeline_stage?.name})</Label>
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <HelpCircle className="text-muted-foreground/60 h-3.5 w-3.5 cursor-help" />
                  </TooltipTrigger>
                  <TooltipContent side="top" className="max-w-[200px] text-xs">
                    <p>Cuộn chuột hoặc kéo để xem thêm. Click vào trạng thái để lưu ngay.</p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            </div>

            {/* Scrollable Container with wheel scroll */}
            <div className="relative">
              {/* Horizontal scroll container - hidden scrollbar, uses wheel scroll */}
              <div
                ref={scrollContainerRef}
                className="flex flex-nowrap items-center gap-2.5 cursor-grab overflow-x-auto overflow-y-hidden overscroll-x-contain [-ms-overflow-style:none] [scrollbar-width:none] active:cursor-grabbing [&::-webkit-scrollbar]:hidden"
              >
                  {/* GROUP 1: PREVIOUS STAGE (Revert) */}
                  {groupedStatuses.previousStage.length > 0 && (
                    <>
                      {groupedStatuses.previousStage.map((status) => (
                        <Button
                          key={status.id}
                          variant="ghost"
                          size="sm"
                          className={cn(
                            "h-7 flex-shrink-0 px-2.5 text-xs font-normal",
                            // Previous Stage: Slate (neutral/revert)
                            "border border-slate-300 bg-slate-100 text-slate-600 hover:bg-slate-200",
                            "transition-all hover:scale-[1.02]",
                            // Pending highlight
                            pendingStatus?.id === status.id && "ring-2 ring-blue-500 ring-offset-1 scale-105"
                          )}
                          onClick={() => {
                            if (resultHasDraggedRef.current) {
                              resultHasDraggedRef.current = false;
                              return;
                            }
                            handleStatusClick(status);
                          }}
                          disabled={addConsultation.isPending}
                        >
                          {savingStatusId === status.id ? (
                            <Loader2 className="mr-1.5 h-3 w-3 animate-spin" />
                          ) : (
                            <span
                              className="mr-1.5 h-1.5 w-1.5 flex-shrink-0 rounded-full"
                              style={{ backgroundColor: status.color_code }}
                            />
                          )}
                          {status.name}
                        </Button>
                      ))}

                      <ArrowRight className="text-muted-foreground/30 mx-1 h-3 w-3 flex-shrink-0" />
                    </>
                  )}

                  {/* GROUP 2: SAME STAGE (Current & Siblings) */}
                  {groupedStatuses.sameStage.length > 0 && (
                    <>
                      {groupedStatuses.sameStage.map((status) => {
                        return (
                          <Button
                            key={status.id}
                            variant="ghost"
                            size="sm"
                            className={cn(
                              "h-7 flex-shrink-0 px-2.5 text-xs font-normal",
                              // Same Stage: Blue (current focus)
                              status.id === currentStatusId
                                ? "border-2 border-blue-500 bg-blue-100 font-medium text-blue-800 hover:bg-blue-150"
                                : "border border-blue-200 bg-blue-50 text-blue-700 hover:bg-blue-100",
                              "transition-all hover:scale-[1.02]",
                              // Pending highlight
                              pendingStatus?.id === status.id && "ring-2 ring-blue-500 ring-offset-1 scale-105"
                            )}
                            onClick={() => {
                              if (resultHasDraggedRef.current) {
                                resultHasDraggedRef.current = false;
                                return;
                              }
                              handleStatusClick(status);
                            }}
                            disabled={addConsultation.isPending}
                          >
                            {savingStatusId === status.id ? (
                              <Loader2 className="mr-1.5 h-3 w-3 animate-spin" />
                            ) : (
                              <span
                                className="mr-1.5 h-1.5 w-1.5 flex-shrink-0 rounded-full"
                                style={{ backgroundColor: status.color_code }}
                              />
                            )}
                            {status.name}
                          </Button>
                        );
                      })}
                    </>
                  )}

                  {/* ARROW SEPARATOR */}
                  {groupedStatuses.sameStage.length > 0 && groupedStatuses.nextStage.length > 0 && (
                    <ArrowRight className="text-muted-foreground/50 mx-1 h-4 w-4 flex-shrink-0" />
                  )}

                  {/* GROUP 3: NEXT STAGE (Progress) */}
                  {groupedStatuses.nextStage.length > 0 && (
                    <>
                      {groupedStatuses.nextStage.map((status) => (
                        <Button
                          key={status.id}
                          variant="ghost"
                          size="sm"
                          className={cn(
                            "h-7 flex-shrink-0 px-2.5 text-xs font-normal",
                            // Next Stage: Emerald (progress/forward)
                            "border border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100",
                            "transition-all hover:scale-[1.02]",
                            // Pending highlight
                            pendingStatus?.id === status.id && "ring-2 ring-blue-500 ring-offset-1 scale-105"
                          )}
                          onClick={() => {
                            if (resultHasDraggedRef.current) {
                              resultHasDraggedRef.current = false;
                              return;
                            }
                            handleStatusClick(status);
                          }}
                          disabled={addConsultation.isPending}
                        >
                          {savingStatusId === status.id ? (
                            <Loader2 className="mr-1.5 h-3 w-3 animate-spin" />
                          ) : (
                            <span
                              className="mr-1.5 h-1.5 w-1.5 flex-shrink-0 rounded-full"
                              style={{ backgroundColor: status.color_code }}
                            />
                          )}
                          {status.name}
                        </Button>
                      ))}
                    </>
                  )}
                </div>
              </div>

              {/* Dynamic Gradient Progress Bar */}
              {(() => {
                 // Calculate colors for gradient
                 // Fallbacks: Slate-200 (Gray), Primary (Blue/Brand), Emerald-200 (Green)
                 const prevColor = groupedStatuses.previousStage.length > 0 
                    ? groupedStatuses.previousStage[groupedStatuses.previousStage.length - 1].color_code 
                    : "#e2e8f0";
                 
                 const currColor = groupedStatuses.sameStage.find(s => s.id === currentStatusId)?.color_code 
                    || groupedStatuses.sameStage[0]?.color_code 
                    || "#3b82f6";
                 
                 const nextColor = groupedStatuses.nextStage.length > 0 
                    ? groupedStatuses.nextStage[0].color_code 
                    : "#a7f3d0";

                 return (
                   <div 
                     className="mt-2 h-1 rounded-full opacity-80"
                     style={{
                       background: `linear-gradient(to right, ${prevColor}, ${currColor}, ${nextColor})`
                     }}
                   />
                 );
              })()}

              {/* ✅ INLINE DELAYED COMMIT CONFIRMATION BAR */}
              {pendingStatus && (
                <div className="mt-3 overflow-hidden rounded-lg border border-blue-200 bg-blue-50">
                  {/* Progress bar (shrinks from right to left) */}
                  <div 
                    className="h-1 bg-blue-500 transition-all duration-1000 ease-linear"
                    style={{ width: `${(countdown / 3) * 100}%` }}
                  />
                  
                  {/* Content */}
                  <div className="flex items-center justify-between gap-2 px-3 py-2">
                    {/* Left: Status info */}
                    <div className="flex items-center gap-2 min-w-0">
                      <CheckCircle2 className="h-4 w-4 flex-shrink-0 text-blue-600" />
                      <span className="text-sm text-blue-700 truncate">
                        Sẽ lưu: <strong>{pendingStatus.name}</strong>
                      </span>
                    </div>
                    
                    {/* Right: Actions + Timer */}
                    <div className="flex items-center gap-2 flex-shrink-0">
                      {/* Undo button */}
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="h-7 px-2 text-xs text-gray-600 hover:text-gray-800 hover:bg-gray-100"
                        onClick={cancelPending}
                      >
                        Hoàn tác
                      </Button>
                      
                      {/* Save now button */}
                      <Button
                        type="button"
                        variant="default"
                        size="sm"
                        className="h-7 px-3 text-xs bg-blue-600 hover:bg-blue-700"
                        onClick={() => commitSave(pendingStatus)}
                        disabled={addConsultation.isPending}
                      >
                        {addConsultation.isPending ? (
                          <Loader2 className="h-3 w-3 animate-spin" />
                        ) : (
                          "Lưu ngay"
                        )}
                      </Button>
                      
                      {/* Countdown timer */}
                      <span className="text-xs font-medium text-blue-600 w-4 text-center">
                        {countdown}s
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </div>

        )}

      </div>
    </div>
  );
}

export default QuickConsultationSection;

