  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

// =============================================================================
// TYPES
// =============================================================================

interface LeadFilterBarProps {
  // Search
  search: string;
  onSearchChange: (value: string) => void;
  // Status filter
  statusFilters: LeadStatus[];
  onStatusChange: (statuses: LeadStatus[]) => void;
  // Multi-select filters
  sourceFilters: string[];
  onSourceChange: (sources: string[]) => void;
  offeringFilters: string[];
  onOfferingChange: (offerings: string[]) => void;
  stageFilters: string[];
  onStageChange: (stages: string[]) => void;
  officerFilters: string[];
  onOfficerChange: (officers: string[]) => void;
  // Score range
  scoreRange: [number, number];
  onScoreRangeChange: (range: [number, number]) => void;
  // Date range
  dateFrom: string;
  dateTo: string;
  dateField: "created_at" | "last_consultation_at";
  onDateFromChange: (date: string) => void;
  onDateToChange: (date: string) => void;
  onDateFieldChange: (field: "created_at" | "last_consultation_at") => void;
  // Actions
  onReset: () => void;
  onExport: () => void;
  onAddLead: () => void;
  // Total count
  totalCount: number;
}

// =============================================================================
// FILTER DROPDOWN COMPONENT
// =============================================================================

interface FilterDropdownProps {
  label: string;
  count: number;
  children: React.ReactNode;
}

function FilterDropdown({ label, count, children }: FilterDropdownProps) {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn(
            "h-8 gap-1 transition-all duration-200",
            count > 0 && "border-primary bg-primary/5"
          )}
        >
          {label}
          {count > 0 && (
            <Badge
              variant="secondary"
              className="bg-primary text-primary-foreground ml-1 h-5 min-w-[20px] px-1.5 text-xs"
            >
              {count}
            </Badge>
          )}
          <ChevronDown className="h-3.5 w-3.5 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-3" align="start">
        {children}
      </PopoverContent>
    </Popover>
  );
}

// =============================================================================
// FILTER PILL COMPONENT
// =============================================================================

interface FilterPillProps {
  label: string;
  onRemove: () => void;
}

function FilterPill({ label, onRemove }: FilterPillProps) {
  return (
    <Badge
      variant="secondary"
      className="animate-in fade-in-0 zoom-in-95 h-6 gap-1 pr-1 text-xs transition-all duration-200"
    >
      {label}
      <button
        onClick={onRemove}
        className="hover:bg-muted ml-0.5 rounded-full p-0.5 transition-colors"
      >
        <X className="h-3 w-3" />
      </button>
    </Badge>
  );
}

// =============================================================================
// MAIN COMPONENT
// =============================================================================

export function LeadFilterBar({
  search,
  onSearchChange,
  statusFilters,
  onStatusChange,
  sourceFilters,
  onSourceChange,
  offeringFilters,
  onOfferingChange,
  stageFilters,
  onStageChange,
  officerFilters,
  onOfficerChange,
  scoreRange,
  onScoreRangeChange,
  dateFrom,
  dateTo,
  dateField,
  onDateFromChange,
  onDateToChange,
  onDateFieldChange,
  onReset,
  onExport,
  onAddLead,
  totalCount,
}: LeadFilterBarProps) {
  const [isPending, startTransition] = useTransition();
  const { user } = useAuth();
  const { data: pipelineStages = [] } = usePipelineStages();
  const { data: offeringsList = [] } = useAllProgramOfferings();
  const { data: usersData } = useAdminUsersList({ page: 1, page_size: 100, status: "active" });
  const officers = usersData?.users?.filter((u) => u.role === "officer" || u.role === "manager") || [];

  const [isMounted, setIsMounted] = React.useState(false);
  React.useEffect(() => { setIsMounted(true); }, []);

  const isAdmin = isMounted && user?.role === "admin";
  const isManager = isMounted && user?.role === "manager";
  const canFilterByOfficer = isAdmin || isManager;

  // Collapsible filter pills state
  const [isFiltersExpanded, setIsFiltersExpanded] = React.useState(false);
  const MAX_VISIBLE_PILLS = 5;

  // Toggle handlers
  const handleStatusToggle = useCallback((status: LeadStatus) => {
    startTransition(() => {
      if (statusFilters.includes(status)) {
        onStatusChange(statusFilters.filter((s) => s !== status));
      } else {
        onStatusChange([...statusFilters, status]);
      }
    });
  }, [statusFilters, onStatusChange]);

  const handleSourceToggle = useCallback((source: string) => {
    startTransition(() => {
      if (sourceFilters.includes(source)) {
        onSourceChange(sourceFilters.filter((s) => s !== source));
      } else {
        onSourceChange([...sourceFilters, source]);
      }
    });
  }, [sourceFilters, onSourceChange]);

  const handleStageToggle = useCallback((stageId: string) => {
    startTransition(() => {
      if (stageFilters.includes(stageId)) {
        onStageChange(stageFilters.filter((s) => s !== stageId));
      } else {
        onStageChange([...stageFilters, stageId]);
      }
    });
  }, [stageFilters, onStageChange]);

  const handleOfficerToggle = useCallback((officerId: string) => {
    startTransition(() => {
      if (officerFilters.includes(officerId)) {
        onOfficerChange(officerFilters.filter((o) => o !== officerId));
      } else {
        onOfficerChange([...officerFilters, officerId]);
      }
    });
  }, [officerFilters, onOfficerChange]);

  const handleOfferingToggle = useCallback((offeringId: string) => {
    startTransition(() => {
      if (offeringFilters.includes(offeringId)) {
        onOfferingChange(offeringFilters.filter((o) => o !== offeringId));
      } else {
        onOfferingChange([...offeringFilters, offeringId]);
      }
    });
  }, [offeringFilters, onOfferingChange]);

  // Check if any filters are active
  const hasScoreFilter = scoreRange[0] > 0 || scoreRange[1] < 100;
  const hasActiveFilters =
    search ||
    statusFilters.length > 0 ||
    sourceFilters.length > 0 ||
    offeringFilters.length > 0 ||
    stageFilters.length > 0 ||
    officerFilters.length > 0 ||
    hasScoreFilter ||
    dateFrom ||
    dateTo;

  // Get display labels
  const getStatusLabel = (value: LeadStatus) =>
    LEAD_STATUS_OPTIONS.find((o) => o.value === value)?.label || value;
  const getSourceLabel = (value: string) =>
    LEAD_SOURCE_OPTIONS.find((o) => o.value === value)?.label || value;
  const getStageLabel = (id: string) =>
    pipelineStages.find((s) => s.id === id)?.name || id;
  const getOfficerLabel = (id: string) =>
    officers.find((o) => o.id.toString() === id)?.full_name || id;
  const getOfferingLabel = (id: string) => {
    const offering = offeringsList.find((o) => o.id.toString() === id);
    if (!offering) return id;
    const programName = offering.program?.name || "";
    const type = offering.offering_type || "";
    return `${programName} - ${type}`;
  };

  return (
    <div className="bg-background/95 supports-[backdrop-filter]:bg-background/60 border-b backdrop-blur">
      {/* Main Filter Row */}
      <div className="flex items-center gap-3 px-4 py-3">
        {/* Search */}
        <div className="relative w-64">
          <Search className="text-muted-foreground absolute top-1/2 left-2.5 h-4 w-4 -translate-y-1/2" />
          <Input
            placeholder="Tìm kiếm tên, SĐT, email..."
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
            className="h-8 pl-9 pr-8 text-sm"
          />
          {search && (
            <button
              onClick={() => onSearchChange("")}
              className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2"
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>

        {/* Divider */}
        <div className="bg-border h-6 w-px" />

        {/* Filter Dropdowns */}
        <div className="flex items-center gap-2">
          {/* Status Filter - Admin only */}
          {isAdmin && (
            <FilterDropdown label="Trạng thái" count={statusFilters.length}>
              <div className="space-y-2">
                {LEAD_STATUS_OPTIONS.map((option) => (
                  <div key={option.value} className="flex items-center space-x-2">
                    <Checkbox
                      id={`bar-status-${option.value}`}
                      checked={statusFilters.includes(option.value)}
                      onCheckedChange={() => handleStatusToggle(option.value)}
                    />
                    <Label
                      htmlFor={`bar-status-${option.value}`}
                      className="flex cursor-pointer items-center gap-2 text-sm font-normal"
                    >
                      <span className={`h-2 w-2 rounded-full ${option.color}`} />
                      {option.label}
                    </Label>
                  </div>
                ))}
              </div>
            </FilterDropdown>
          )}

          {/* Source Filter */}
          <FilterDropdown label="Nguồn" count={sourceFilters.length}>
            <div className="space-y-2">
              {LEAD_SOURCE_OPTIONS.map((option) => (
                <div key={option.value} className="flex items-center space-x-2">
                  <Checkbox
                    id={`bar-source-${option.value}`}
                    checked={sourceFilters.includes(option.value)}
                    onCheckedChange={() => handleSourceToggle(option.value)}
                  />
                  <Label
                    htmlFor={`bar-source-${option.value}`}
                    className="cursor-pointer text-sm font-normal"
                  >
                    {option.label}
                  </Label>
                </div>
              ))}
            </div>
          </FilterDropdown>

          {/* Stage Filter */}
          <FilterDropdown label="Giai đoạn" count={stageFilters.length}>
            <div className="space-y-2">
              {pipelineStages.map((stage) => (
                <div key={stage.id} className="flex items-center space-x-2">
                  <Checkbox
                    id={`bar-stage-${stage.id}`}
                    checked={stageFilters.includes(stage.id)}
                    onCheckedChange={() => handleStageToggle(stage.id)}
                  />
                  <Label
                    htmlFor={`bar-stage-${stage.id}`}
                    className="flex cursor-pointer items-center gap-2 text-sm font-normal"
                  >
                    <span
                      className="h-2.5 w-2.5 rounded-full"
                      style={{ backgroundColor: STAGE_COLORS[stage.id] || "#6B7280" }}
                    />
                    {stage.name}
                  </Label>
                </div>
              ))}
            </div>
          </FilterDropdown>

          {/* Offering Filter */}
          <FilterDropdown label="Chương trình" count={offeringFilters.length}>
            <MultiOfferingSelector
              values={offeringFilters}
              onChange={onOfferingChange}
            />
          </FilterDropdown>

          {/* Officer Filter - Admin/Manager only */}
          {canFilterByOfficer && (
            <FilterDropdown label="Cán bộ" count={officerFilters.length}>
              <div className="max-h-48 space-y-2 overflow-y-auto">
                {officers.map((officer) => (
                  <div key={officer.id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`bar-officer-${officer.id}`}
                      checked={officerFilters.includes(officer.id.toString())}
                      onCheckedChange={() => handleOfficerToggle(officer.id.toString())}
                    />
                    <Label
                      htmlFor={`bar-officer-${officer.id}`}
                      className="cursor-pointer text-sm font-normal"
                    >
                      {officer.full_name}
                    </Label>
                  </div>
                ))}
              </div>
            </FilterDropdown>
          )}

          {/* Score Filter */}
          <FilterDropdown
            label="Điểm"
            count={hasScoreFilter ? 1 : 0}
          >
            <div className="space-y-4">
              <div className="flex items-center justify-between text-sm">
                <span>Điểm lead</span>
                <span className="text-muted-foreground">
                  {scoreRange[0]} - {scoreRange[1]}
                </span>
              </div>
              <Slider
                value={scoreRange}
                onValueChange={(value) => onScoreRangeChange(value as [number, number])}
                min={0}
                max={100}
                step={5}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>0</span>
                <span>50</span>
                <span>100</span>
              </div>
            </div>
          </FilterDropdown>

          {/* Date Range */}
          <Popover>
            <PopoverTrigger asChild>
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  "h-8 gap-1",
                  (dateFrom || dateTo) && "border-primary bg-primary/5"
                )}
              >
                <Calendar className="h-3.5 w-3.5" />
                {dateField === "created_at" ? "Ngày tạo" : "Ngày TĐ"}
                {(dateFrom || dateTo) && (
                  <Badge variant="secondary" className="bg-primary text-primary-foreground ml-1 h-5 px-1.5 text-xs">
                    1
                  </Badge>
                )}
                <ChevronDown className="h-3.5 w-3.5 opacity-50" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-72 p-3" align="start">
              <div className="space-y-3">
                {/* Date Field Selector */}
                <div>
                  <Label className="text-xs">Lọc theo</Label>
                  <Select value={dateField} onValueChange={(v) => onDateFieldChange(v as "created_at" | "last_consultation_at")}>
                    <SelectTrigger className="mt-1 h-8">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="created_at">Ngày tạo</SelectItem>
                      <SelectItem value="last_consultation_at">Ngày tư vấn cuối</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-xs">Từ ngày</Label>
                  <Input
                    type="date"
                    value={dateFrom}
                    onChange={(e) => onDateFromChange(e.target.value)}
                    className="mt-1 h-8"
                  />
                </div>
                <div>
                  <Label className="text-xs">Đến ngày</Label>
                  <Input
                    type="date"
                    value={dateTo}
                    onChange={(e) => onDateToChange(e.target.value)}
                    className="mt-1 h-8"
                  />
                </div>
              </div>
            </PopoverContent>
          </Popover>
        </div>

        {/* Spacer */}
        <div className="flex-1" />

        {/* Actions */}
        <div className="flex items-center gap-2">
          {hasActiveFilters && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onReset}
              className="h-8 text-xs"
            >
              <RotateCcw className="mr-1 h-3.5 w-3.5" />
              Đặt lại
            </Button>
          )}
          <Button variant="outline" size="sm" onClick={onExport} className="h-8">
            <Download className="mr-1.5 h-3.5 w-3.5" />
            Xuất
          </Button>
          <Button size="sm" onClick={onAddLead} className="h-8">
            <Plus className="mr-1.5 h-3.5 w-3.5" />
            Thêm Lead
          </Button>
        </div>
      </div>

      {/* Active Filter Pills - Collapsible */}
      {hasActiveFilters && (() => {
        // Build all pills as an array
        const allPills: { key: string; label: string; onRemove: () => void }[] = [];
        
        if (search) {
          allPills.push({ key: "search", label: `"${search}"`, onRemove: () => onSearchChange("") });
        }
        statusFilters.forEach((status) => {
          allPills.push({ key: `status-${status}`, label: getStatusLabel(status), onRemove: () => handleStatusToggle(status) });
        });
        sourceFilters.forEach((source) => {
          allPills.push({ key: `source-${source}`, label: getSourceLabel(source), onRemove: () => handleSourceToggle(source) });
        });
        stageFilters.forEach((stage) => {
          allPills.push({ key: `stage-${stage}`, label: getStageLabel(stage), onRemove: () => handleStageToggle(stage) });
        });
        officerFilters.forEach((officer) => {
          allPills.push({ key: `officer-${officer}`, label: getOfficerLabel(officer), onRemove: () => handleOfficerToggle(officer) });
        });
        offeringFilters.forEach((id) => {
          allPills.push({ key: `offering-${id}`, label: getOfferingLabel(id), onRemove: () => handleOfferingToggle(id) });
        });
        if (hasScoreFilter) {
          allPills.push({ key: "score", label: `Điểm: ${scoreRange[0]}-${scoreRange[1]}`, onRemove: () => onScoreRangeChange([0, 100]) });
        }
        if (dateFrom || dateTo) {
          allPills.push({
            key: "date",
            label: `${dateField === "created_at" ? "Tạo" : "TĐ"}: ${dateFrom || "..."} → ${dateTo || "..."}`,
            onRemove: () => { onDateFromChange(""); onDateToChange(""); },
          });
        }

        const visiblePills = isFiltersExpanded ? allPills : allPills.slice(0, MAX_VISIBLE_PILLS);
        const hiddenCount = allPills.length - MAX_VISIBLE_PILLS;

        return (
          <div className="flex flex-wrap items-center gap-2 border-t px-4 py-2">
            <span className="text-muted-foreground text-xs">Đang lọc:</span>
            
            {visiblePills.map((pill) => (
              <FilterPill key={pill.key} label={pill.label} onRemove={pill.onRemove} />
            ))}
            
            {/* Show "+X more" button when collapsed and has hidden pills */}
            {!isFiltersExpanded && hiddenCount > 0 && (
              <Badge
                variant="outline"
                className="h-6 cursor-pointer gap-1 px-2 text-xs transition-colors hover:bg-primary/10"
                onClick={() => setIsFiltersExpanded(true)}
              >
                +{hiddenCount} more
                <ChevronDown className="h-3 w-3" />
              </Badge>
            )}
            
            {/* Show "Thu gọn" button when expanded */}
            {isFiltersExpanded && allPills.length > MAX_VISIBLE_PILLS && (
              <Badge
                variant="outline"
                className="h-6 cursor-pointer gap-1 px-2 text-xs transition-colors hover:bg-primary/10"
                onClick={() => setIsFiltersExpanded(false)}
              >
                Thu gọn
                <ChevronDown className="h-3 w-3 rotate-180" />
              </Badge>
            )}

            <span className="text-muted-foreground ml-2 text-xs">
              • {totalCount.toLocaleString()} kết quả
            </span>
          </div>
        );
      })()}
    </div>
  );
}

export default LeadFilterBar;

// src/components/leads/command-center/LeadFilters.tsx
"use client";

import React from "react";
import { Search, X, RotateCcw } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Slider } from "@/components/ui/slider";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { LeadStatus } from "@/types/lead.types";
import { MultiOfferingSelector } from "@/components/common/selectors";
import { LEAD_STATUS_OPTIONS, LEAD_SOURCE_OPTIONS } from "@/constants";
import { usePipelineStages } from "@/hooks/usePipeline";
import { useAdminUsersList } from "@/hooks/useAdminUsers";
import { STAGE_COLORS } from "@/types/pipeline.types";
import { useAuth } from "@/hooks/useAuth";

interface LeadFiltersProps {
  search: string;
  onSearchChange: (value: string) => void;
  statusFilters: LeadStatus[];
  onStatusChange: (statuses: LeadStatus[]) => void;
  // Multi-select arrays
  sourceFilters: string[];
  onSourceChange: (sources: string[]) => void;
  scoreRange: [number, number];
  onScoreRangeChange: (range: [number, number]) => void;
  offeringFilters: string[];
  onOfferingChange: (offeringIds: string[]) => void;
  stageFilters: string[];
  onStageChange: (stageIds: string[]) => void;
  // === OFFICER FILTER (admin/manager only) ===
  officerFilters: string[];
  onOfficerChange: (officerIds: string[]) => void;
  // === DATE RANGE FILTER ===
  dateFrom: string;
  dateTo: string;
  dateField: "created_at" | "updated_at";
  onDateFromChange: (date: string) => void;
  onDateToChange: (date: string) => void;
  onDateFieldChange: (field: "created_at" | "updated_at") => void;
  onReset: () => void;
}

// Using centralized constants from @/constants
// STATUS_OPTIONS and SOURCE_OPTIONS are now imported as LEAD_STATUS_OPTIONS and LEAD_SOURCE_OPTIONS

export const LeadFilters = React.memo(function LeadFilters({
  search,
  onSearchChange,
  statusFilters,
  onStatusChange,
  // Multi-select
  sourceFilters,
  onSourceChange,
  scoreRange,
  onScoreRangeChange,
  offeringFilters,
  onOfferingChange,
  stageFilters,
  onStageChange,
  // === OFFICER FILTER ===
  officerFilters,
  onOfficerChange,
  // === DATE RANGE FILTER ===
  dateFrom,
  dateTo,
  dateField,
  onDateFromChange,
  onDateToChange,
  onDateFieldChange,
  onReset,
}: LeadFiltersProps) {
  // Fetch pipeline stages
  const { data: pipelineStages = [] } = usePipelineStages();
  const { user } = useAuth();

  // Hydration-safe role checks - only render role-dependent UI after mount
  const [isMounted, setIsMounted] = React.useState(false);
  React.useEffect(() => {
    setIsMounted(true);
  }, []);

  // Role checks only work after hydration to prevent server/client mismatch
  const isAdmin = isMounted && user?.role === "admin";
  const isManager = isMounted && user?.role === "manager";
  const canFilterByOfficer = isAdmin || isManager;

  // Fetch officers list (always fetch, conditionally render UI)
  // We fetch all active users and filter by role on the client
  const { data: usersData } = useAdminUsersList({ page: 1, page_size: 100, status: "active" });
  const officers = usersData?.users?.filter((u) => u.role === "officer" || u.role === "manager") || [];

  const handleStatusToggle = (status: LeadStatus) => {
    if (statusFilters.includes(status)) {
      onStatusChange(statusFilters.filter((s) => s !== status));
    } else {
      onStatusChange([...statusFilters, status]);
    }
  };

  // Multi-select toggle helpers
  const handleSourceToggle = (source: string) => {
    if (sourceFilters.includes(source)) {
      onSourceChange(sourceFilters.filter((s) => s !== source));
    } else {
      onSourceChange([...sourceFilters, source]);
    }
  };

  const handleStageToggle = (stageId: string) => {
    if (stageFilters.includes(stageId)) {
      onStageChange(stageFilters.filter((s) => s !== stageId));
    } else {
      onStageChange([...stageFilters, stageId]);
    }
  };

  const handleOfficerToggle = (officerId: string) => {
    if (officerFilters.includes(officerId)) {
      onOfficerChange(officerFilters.filter((o) => o !== officerId));
    } else {
      onOfficerChange([...officerFilters, officerId]);
    }
  };

  const hasActiveFilters =
    search ||
    statusFilters.length > 0 ||
    sourceFilters.length > 0 ||
    scoreRange[0] > 0 ||
    scoreRange[1] < 100 ||
    offeringFilters.length > 0 ||
    stageFilters.length > 0 ||
    officerFilters.length > 0 ||
    dateFrom ||
    dateTo;

  return (
    <div className="bg-card h-full">
      <div className="h-full space-y-4 overflow-y-auto p-4">
        {/* Tiêu đề */}
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-semibold">Bộ lọc</h3>
          {hasActiveFilters && (
            <Button variant="ghost" size="sm" onClick={onReset} className="h-7 px-2 text-xs">
              <RotateCcw className="mr-1 h-3 w-3" />
              Đặt lại
            </Button>
          )}
        </div>

        {/* Tìm kiếm */}
        <div className="relative">
          <Search className="text-muted-foreground absolute top-2.5 left-2.5 h-4 w-4" />
          <Input
            placeholder="Tìm kiếm tên, số điện thoại, email..."
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
            className="pr-8 pl-8"
          />
          {search && (
            <button
              onClick={() => onSearchChange("")}
              className="text-muted-foreground hover:text-foreground absolute top-2.5 right-2.5"
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>

        {/* Bộ lọc */}
        <Accordion type="multiple" defaultValue={["pipeline_stage"]} className="space-y-2">
          {/* Bộ lọc trạng thái - Chỉ hiển thị cho Admin */}
          {isAdmin && (
            <AccordionItem value="status" className="rounded-lg border px-3">
              <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
                Vòng đời Lead
                {statusFilters.length > 0 && (
                  <span className="bg-primary text-primary-foreground mr-2 ml-auto rounded-full px-1.5 py-0.5 text-xs">
                    {statusFilters.length}
                  </span>
                )}
              </AccordionTrigger>
              <AccordionContent className="pb-3">
                <div className="space-y-2">
                  {LEAD_STATUS_OPTIONS.map((option) => (
                    <div key={option.value} className="flex items-center space-x-2">
                      <Checkbox
                        id={`status-${option.value}`}
                        checked={statusFilters.includes(option.value)}
                        onCheckedChange={() => handleStatusToggle(option.value)}
                      />
                      <Label
                        htmlFor={`status-${option.value}`}
                        className="flex cursor-pointer items-center gap-2 text-sm font-normal"
                      >
                        <span className={`h-2 w-2 rounded-full ${option.color}`} />
                        {option.label}
                      </Label>
                    </div>
                  ))}
                </div>
              </AccordionContent>
            </AccordionItem>
          )}

          {/* Bộ lọc Pipeline Stage - Multi-select */}
          <AccordionItem value="pipeline_stage" className="rounded-lg border px-3">
            <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
              Giai đoạn Pipeline
              {stageFilters.length > 0 && (
                <span className="bg-primary text-primary-foreground mr-2 ml-auto rounded-full px-1.5 py-0.5 text-xs">
                  {stageFilters.length}
                </span>
              )}
            </AccordionTrigger>
            <AccordionContent className="pb-3">
              <div className="space-y-2">
                {pipelineStages.map((stage) => (
                  <div key={stage.id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`stage-${stage.id}`}
                      checked={stageFilters.includes(stage.id)}
                      onCheckedChange={() => handleStageToggle(stage.id)}
                    />
                    <Label
                      htmlFor={`stage-${stage.id}`}
                      className="flex cursor-pointer items-center gap-2 text-sm font-normal"
                    >
                      <span
                        className="h-2.5 w-2.5 rounded-full"
                        style={{ backgroundColor: STAGE_COLORS[stage.id] || "#6B7280" }}
                      />
                      {stage.name}
                    </Label>
                  </div>
                ))}
              </div>
            </AccordionContent>
          </AccordionItem>

          {/* Bộ lọc nguồn - Multi-select */}
          <AccordionItem value="source" className="rounded-lg border px-3">
            <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
              Nguồn
              {sourceFilters.length > 0 && (
                <span className="bg-primary text-primary-foreground mr-2 ml-auto rounded-full px-1.5 py-0.5 text-xs">
                  {sourceFilters.length}
                </span>
              )}
            </AccordionTrigger>
            <AccordionContent className="pb-3">
              <div className="space-y-2">
                {LEAD_SOURCE_OPTIONS.map((option) => (
                  <div key={option.value} className="flex items-center space-x-2">
                    <Checkbox
                      id={`source-${option.value}`}
                      checked={sourceFilters.includes(option.value)}
                      onCheckedChange={() => handleSourceToggle(option.value)}
                    />
                    <Label
                      htmlFor={`source-${option.value}`}
                      className="cursor-pointer text-sm font-normal"
                    >
                      {option.label}
                    </Label>
                  </div>
                ))}
              </div>
            </AccordionContent>
          </AccordionItem>

          {/* Bộ lọc điểm Lead */}
          <AccordionItem value="score" className="rounded-lg border px-3">
            <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
              Điểm Lead
            </AccordionTrigger>
            <AccordionContent className="pt-2 pb-3">
              <div className="space-y-4">
                <Slider
                  value={scoreRange}
                  onValueChange={(value) => onScoreRangeChange(value as [number, number])}
                  max={100}
                  min={0}
                  step={5}
                  className="w-full"
                />
                <div className="text-muted-foreground flex justify-between text-xs">
                  <span>{scoreRange[0]}</span>
                  <span>{scoreRange[1]}</span>
                </div>
              </div>
            </AccordionContent>
          </AccordionItem>

          {/* Bộ lọc chương trình - Multi-select */}
          <AccordionItem value="offering" className="rounded-lg border px-3">
            <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
              Chương trình
              {offeringFilters.length > 0 && (
                <span className="bg-primary text-primary-foreground mr-2 ml-auto rounded-full px-1.5 py-0.5 text-xs">
                  {offeringFilters.length}
                </span>
              )}
            </AccordionTrigger>
            <AccordionContent className="pb-3">
              <MultiOfferingSelector
                values={offeringFilters}
                onChange={onOfferingChange}
              />
            </AccordionContent>
          </AccordionItem>

          {/* Bộ lọc cán bộ phụ trách - Multi-select, chỉ cho Admin/Manager */}
          {(isAdmin || isManager) && (
            <AccordionItem value="officer" className="rounded-lg border px-3">
              <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
                Cán bộ phụ trách
                {officerFilters.length > 0 && (
                  <span className="bg-primary text-primary-foreground mr-2 ml-auto rounded-full px-1.5 py-0.5 text-xs">
                    {officerFilters.length}
                  </span>
                )}
              </AccordionTrigger>
              <AccordionContent className="pb-3">
                <div className="max-h-48 space-y-2 overflow-y-auto">
                  {officers.map((officer) => (
                    <div key={officer.id} className="flex items-center space-x-2">
                      <Checkbox
                        id={`officer-${officer.id}`}
                        checked={officerFilters.includes(officer.id.toString())}
                        onCheckedChange={() => handleOfficerToggle(officer.id.toString())}
                      />
                      <Label
                        htmlFor={`officer-${officer.id}`}
                        className="cursor-pointer text-sm font-normal"
                      >
                        {officer.full_name}
                      </Label>
                    </div>
                  ))}
                </div>
              </AccordionContent>
            </AccordionItem>
          )}

          {/* Bộ lọc ngày tạo/cập nhật */}
          <AccordionItem value="date" className="rounded-lg border px-3">
            <AccordionTrigger className="py-3 text-sm font-medium hover:no-underline">
              <div className="flex items-center gap-2">Khoảng thời gian</div>
              {(dateFrom || dateTo) && (
                <span className="bg-primary text-primary-foreground mr-2 ml-auto rounded-full px-1.5 py-0.5 text-xs">
                  1
                </span>
              )}
            </AccordionTrigger>
            <AccordionContent className="space-y-3 pb-3">
              {/* Date field selector */}
              <div className="space-y-1.5">
                <Label className="text-muted-foreground text-xs">Lọc theo</Label>
                <Select
                  value={dateField}
                  onValueChange={(val) => onDateFieldChange(val as "created_at" | "updated_at")}
                >
                  <SelectTrigger className="h-8 w-full text-sm">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="created_at">Ngày tạo</SelectItem>
                    <SelectItem value="updated_at">Ngày cập nhật</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Date from */}
              <div className="space-y-1.5">
                <Label className="text-muted-foreground text-xs">Từ ngày</Label>
                <Input
                  type="date"
                  value={dateFrom}
                  onChange={(e) => onDateFromChange(e.target.value)}
                  className="h-8 text-sm"
                />
              </div>

              {/* Date to */}
              <div className="space-y-1.5">
                <Label className="text-muted-foreground text-xs">Đến ngày</Label>
                <Input
                  type="date"
                  value={dateTo}
                  onChange={(e) => onDateToChange(e.target.value)}
                  className="h-8 text-sm"
                />
              </div>
            </AccordionContent>
          </AccordionItem>
        </Accordion>
      </div>
    </div>
  );
});

// src/components/leads/command-center/LeadsTable.tsx
/**
 * LeadsTable - Advanced data table for leads
 * 
 * Features:
 * - @tanstack/react-table for state management
 * - @tanstack/react-virtual for virtualization (Option A)
 * - Row selection with keyboard navigation
 * - Sortable columns with column resize
 * - Compact/Normal view modes
 * - Column visibility toggle
 * - Footer with pagination
 * - Keyboard shortcuts
 */

"use client";

import React, { useMemo, useCallback, useEffect, useRef } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { leadsKeys } from "@/hooks/useLeads";
import { leadsApi } from "@/lib/api/leads";
import { useRouter } from "next/navigation";
import { useVirtualizer } from "@tanstack/react-virtual";
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
  type RowSelectionState,
  type ColumnResizeMode,
  type VisibilityState,
} from "@tanstack/react-table";
import { format } from "date-fns";
import { vi } from "date-fns/locale";
import {
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
  MoreHorizontal,
  ChevronLeft,
  SearchX,
  ChevronRight,
  GripVertical,
  Zap,
} from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import type { Lead } from "@/types/lead.types";
import { LEAD_SOURCE_OPTIONS } from "@/constants";
import { STAGE_COLORS } from "@/types/pipeline.types";
import { TableToolbar, type DensityMode } from "./TableToolbar";
import { BulkActionsBar } from "./BulkActionsBar";
import { CopyableCell } from "@/components/common/CopyableCell";
import { ActivityIndicator } from "@/components/common/ActivityIndicator";
import { UrgencyBadge } from "@/components/common/UrgencyBadge";
import { EmptyLeadsState } from "./EmptyLeadsState";

// =============================================================================
// TYPES
// =============================================================================

interface LeadsTableProps {
  leads: Lead[];
  selectedLeadId: number | null;
  onSelectLead: (lead: Lead) => void;
  onEditLead: (lead: Lead) => void;
  onDeleteLead: (lead: Lead) => void;
  isLoading?: boolean;
  // Pagination props
  page?: number;
  pageSize?: number;
  totalCount?: number;
  onPageChange?: (page: number) => void;
  // Bulk action handlers
  onBulkAssign?: (leads: Lead[]) => void;
  onBulkChangeStage?: (leads: Lead[]) => void;
  onBulkExport?: (leads: Lead[]) => void;
  onBulkDelete?: (leads: Lead[]) => void;
  // Search focus
  onSearchFocus?: () => void;
  // Reset selection when this key changes (e.g., after bulk action)
  resetSelectionKey?: number;
  // ✅ Phase 3: Contextual empty state props
  hasFilters?: boolean;
  searchQuery?: string;
  onResetFilters?: () => void;
  onCreateLead?: () => void;
}

// =============================================================================
// CONSTANTS
// =============================================================================

const COLUMN_VISIBILITY_STORAGE_KEY = "leads_table_columns";
const DENSITY_MODE_STORAGE_KEY = "leads_table_density";
const SORTING_STORAGE_KEY = "leads_table_sorting";

// Default sort: urgency_score DESC (most urgent leads first)
const DEFAULT_SORTING: SortingState = [{ id: "cached_urgency_score", desc: true }];

// Density configuration
const DENSITY_CONFIG: Record<DensityMode, { rowHeight: number; cellPadding: string; headerHeight: string }> = {
  condensed: { rowHeight: 36, cellPadding: 'py-1', headerHeight: 'h-8' },
  regular: { rowHeight: 48, cellPadding: 'py-2', headerHeight: 'h-10' },
  relaxed: { rowHeight: 60, cellPadding: 'py-3', headerHeight: 'h-12' },
};

const columnHelper = createColumnHelper<Lead>();

const getSourceLabel = (value: string) =>
  LEAD_SOURCE_OPTIONS.find((o) => o.value === value)?.label || value;

// =============================================================================
// MAIN COMPONENT
// =============================================================================

export function LeadsTable({
  leads,
  selectedLeadId,
  onSelectLead,
  onEditLead,
  onDeleteLead,
  isLoading = false,
  page = 1,
  pageSize = 50,
  totalCount = 0,
  onPageChange,
  onBulkAssign,
  onBulkChangeStage,
  onBulkExport,
  onBulkDelete,
  onSearchFocus,
  resetSelectionKey,
  // ✅ Phase 3: Contextual empty state props
  hasFilters = false,
  searchQuery = "",
  onResetFilters,
  onCreateLead,
}: LeadsTableProps) {
  const router = useRouter();
  const queryClient = useQueryClient();
  const tableContainerRef = useRef<HTMLDivElement>(null);
  
  // ✅ Sorting state with localStorage persistence and default urgency sort
  const [sorting, setSorting] = React.useState<SortingState>(DEFAULT_SORTING);
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});
  const [columnResizeMode] = React.useState<ColumnResizeMode>("onChange");
  const [focusedRowIndex, setFocusedRowIndex] = React.useState<number>(-1);
  
  // Load persisted states - START with defaults, then hydrate from localStorage
  const [densityMode, setDensityMode] = React.useState<DensityMode>('regular');
  // Default: hide phone column for privacy protection
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({ phone: false });
  const [isHydrated, setIsHydrated] = React.useState(false);

  // Hydrate from localStorage after mount to avoid SSR mismatch
  useEffect(() => {
    const savedDensity = localStorage.getItem(DENSITY_MODE_STORAGE_KEY);
    if (savedDensity && ['condensed', 'regular', 'relaxed'].includes(savedDensity)) {
      setDensityMode(savedDensity as DensityMode);
    }
    
    try {
      const savedVisibility = localStorage.getItem(COLUMN_VISIBILITY_STORAGE_KEY);
      if (savedVisibility) {
        const parsed = JSON.parse(savedVisibility);
        // Merge with defaults (user preferences override defaults)
        setColumnVisibility({ phone: false, ...parsed });
      }
    } catch {
      // Ignore parse errors
    }

    try {
      const savedSorting = localStorage.getItem(SORTING_STORAGE_KEY);
      if (savedSorting) {
        setSorting(JSON.parse(savedSorting));
      }
    } catch {
      // Ignore parse errors
    }
    
    setIsHydrated(true);
  }, []);

  const totalPages = Math.ceil(totalCount / pageSize);
  const densityConfig = DENSITY_CONFIG[densityMode];

  // Persist density mode (only after hydration)
  useEffect(() => {
    if (isHydrated) {
      localStorage.setItem(DENSITY_MODE_STORAGE_KEY, densityMode);
    }
  }, [densityMode, isHydrated]);

  // Persist column visibility (only after hydration)
  useEffect(() => {
    if (isHydrated) {
      localStorage.setItem(COLUMN_VISIBILITY_STORAGE_KEY, JSON.stringify(columnVisibility));
    }
  }, [columnVisibility, isHydrated]);

  // ✅ Persist sorting preference
  useEffect(() => {
    localStorage.setItem(SORTING_STORAGE_KEY, JSON.stringify(sorting));
  }, [sorting]);

  // Reset row selection when resetSelectionKey changes (after bulk actions)
  useEffect(() => {
    if (resetSelectionKey !== undefined) {
      setRowSelection({});
    }
  }, [resetSelectionKey]);

  // Reset focused row when leads data changes (after create/update/delete)
  useEffect(() => {
    setFocusedRowIndex(-1);
  }, [leads]);

  // Column definitions
  const columns = useMemo(
    () => [
      // Checkbox column
      columnHelper.display({
        id: "select",
        header: ({ table }) => (
          <Checkbox
            checked={
              table.getIsAllPageRowsSelected() ||
              (table.getIsSomePageRowsSelected() && "indeterminate")
            }
            onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
            aria-label="Select all"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(!!value)}
            onClick={(e) => e.stopPropagation()}
            aria-label="Select row"
          />
        ),
        size: 40,
        enableResizing: false,
        enableHiding: false,
      }),

      // Name column
      columnHelper.accessor("full_name", {
        header: ({ column }) => (
          <Button
            variant="ghost"
            className="-ml-3 h-8 font-medium"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Tên Lead
            {column.getIsSorted() === "asc" ? (
              <ArrowUp className="ml-1 h-3.5 w-3.5" />
            ) : column.getIsSorted() === "desc" ? (
              <ArrowDown className="ml-1 h-3.5 w-3.5" />
            ) : (
              <ArrowUpDown className="ml-1 h-3.5 w-3.5 opacity-50" />
            )}
          </Button>
        ),
        cell: ({ row }) => (
          <div className="text-sm font-medium">{row.original.full_name || "—"}</div>
        ),
        size: 180,
      }),

      // Phone column - with copy to clipboard
      columnHelper.accessor("phone", {
        header: "SĐT",
        cell: ({ row }) => (
          <CopyableCell
            value={row.original.phone}
            label="số điện thoại"
            className="text-muted-foreground font-mono text-sm tabular-nums"
          />
        ),
        size: 120,
      }),

      // Source column
      columnHelper.accessor("source", {
        header: "Nguồn",
        cell: ({ row }) => {
          const source = row.original.source;
          if (!source) return <span className="text-muted-foreground">—</span>;
          return (
            <Badge variant="outline" className="text-[10px] h-5 px-2 font-normal">
              {getSourceLabel(source)}
            </Badge>
          );
        },
        size: 90,
      }),

      // Pipeline Stage column
      columnHelper.accessor("pipeline_stage", {
        header: "Giai đoạn",
        cell: ({ row }) => {
          const stage = row.original.pipeline_stage;
          if (!stage) return <span className="text-muted-foreground">—</span>;
          const color = STAGE_COLORS[stage.id] || "#6B7280";
          return (
            <Badge
              className="text-[10px] h-5 px-2 font-normal whitespace-nowrap"
              style={{
                backgroundColor: `${color}20`,
                color: color,
                borderColor: color,
              }}
            >
              {stage.name}
            </Badge>
          );
        },
        size: 110,
      }),

      // Consultation Status column - text color from status.color
      columnHelper.accessor("consultation_status", {
        header: "Trạng thái TĐ",
        cell: ({ row }) => {
          const status = row.original.consultation_status;
          if (!status) return <span className="text-muted-foreground">—</span>;
          return (
            <Badge
              variant="secondary"
              className="text-[10px] h-5 px-2 font-medium whitespace-nowrap"
              style={{ color: status.color || status.color_code || "inherit" }}
            >
              {status.name}
            </Badge>
          );
        },
        size: 110,
      }),

      // Officer column
      columnHelper.accessor("assigned_officer", {
        header: "Cán bộ",
        cell: ({ row }) => {
          const officer = row.original.assigned_officer;
          if (!officer) return <span className="text-muted-foreground text-sm">Chưa gán</span>;
          return (
            <div className="text-sm">{officer.full_name}</div>
          );
        },
        size: 140,
      }),

      // Lead Score column - ✅ Now sortable
      columnHelper.accessor("lead_score", {
        header: ({ column }) => (
          <Button
            variant="ghost"
            className="-ml-3 h-8 font-medium"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Điểm
            {column.getIsSorted() === "asc" ? (
              <ArrowUp className="ml-1 h-3.5 w-3.5" />
            ) : column.getIsSorted() === "desc" ? (
              <ArrowDown className="ml-1 h-3.5 w-3.5" />
            ) : (
              <ArrowUpDown className="ml-1 h-3.5 w-3.5 opacity-50" />
            )}
          </Button>
        ),
        cell: ({ row }) => {
          const score = row.original.lead_score ?? 0;
          // Color coding based on score ranges
          let colorClass = "text-muted-foreground";
          if (score >= 70) colorClass = "text-green-600 font-semibold";
          else if (score >= 50) colorClass = "text-blue-600 font-medium";
          else if (score >= 30) colorClass = "text-yellow-600";
          return (
            <div className={cn("text-sm text-right tabular-nums pr-2", colorClass)}>
              {score}
            </div>
          );
        },
        size: 80,
      }),

      // Activity column - ✅ FIX: Sort by last_consultation_at || created_at (same as display)
      columnHelper.accessor(
        (row) => row.last_consultation_at || row.created_at,
        {
          id: "activity",
          header: ({ column }) => (
            <Button
              variant="ghost"
              className="-ml-3 h-8 font-medium"
              onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
            >
              Hoạt động
              {column.getIsSorted() === "asc" ? (
                <ArrowUp className="ml-1 h-3.5 w-3.5" />
              ) : column.getIsSorted() === "desc" ? (
                <ArrowDown className="ml-1 h-3.5 w-3.5" />
              ) : (
                <ArrowUpDown className="ml-1 h-3.5 w-3.5 opacity-50" />
              )}
            </Button>
          ),
          cell: ({ row }) => (
            <ActivityIndicator
              date={row.original.last_consultation_at || row.original.created_at}
              nextActivityAt={row.original.next_activity_at}
            />
          ),
          sortingFn: (rowA, rowB) => {
            const dateA = new Date(rowA.original.last_consultation_at || rowA.original.created_at).getTime();
            const dateB = new Date(rowB.original.last_consultation_at || rowB.original.created_at).getTime();
            return dateA - dateB;
          },
          size: 100,
        }
      ),

      // Urgency Score column (Lead Insights Upgrade)
      columnHelper.accessor("cached_urgency_score", {
        header: ({ column }) => (
          <TooltipProvider delayDuration={200}>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  className="-ml-3 h-8 w-8 p-0"
                  onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
                >
                  <Zap className="h-4 w-4 text-amber-500" />
                  {column.getIsSorted() === "asc" ? (
                    <ArrowUp className="ml-0.5 h-3 w-3" />
                  ) : column.getIsSorted() === "desc" ? (
                    <ArrowDown className="ml-0.5 h-3 w-3" />
                  ) : null}
                </Button>
              </TooltipTrigger>
              <TooltipContent>Độ khẩn cấp</TooltipContent>
            </Tooltip>
          </TooltipProvider>
        ),
        cell: ({ row }) => (
          <UrgencyBadge score={row.original.cached_urgency_score} showLabel={false} />
        ),
        size: 50,
      }),

      // Actions column
      columnHelper.display({
        id: "actions",
        cell: ({ row }) => (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="sm"
                className="h-8 w-8 p-0"
                onClick={(e) => e.stopPropagation()}
              >
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => onEditLead(row.original)}>
                Chỉnh sửa
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => onDeleteLead(row.original)}
                className="text-destructive"
              >
                Xóa
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        ),
        size: 50,
        enableResizing: false,
        enableHiding: false,
      }),
    ],
    [onEditLead, onDeleteLead]
  );

  // Table instance
  const table = useReactTable({
    data: leads,
    columns,
    state: {
      sorting,
      rowSelection,
      columnVisibility,
    },
    enableRowSelection: true,
    enableColumnResizing: true,
    columnResizeMode,
    onSortingChange: (updater) => {
      setSorting(updater);
      setFocusedRowIndex(-1); // Reset focus when sorting changes
    },
    onRowSelectionChange: setRowSelection,
    onColumnVisibilityChange: setColumnVisibility,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });

  // Get all rows for virtualization
  const rows = table.getRowModel().rows;

  // ✅ Option A: Virtualization setup
  const tableScrollRef = useRef<HTMLDivElement>(null);
  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => tableScrollRef.current,
    estimateSize: () => densityConfig.rowHeight, // Dynamic row height based on density mode
    overscan: 5, // Render 5 extra rows above/below viewport
  });
  const virtualRows = rowVirtualizer.getVirtualItems();

  // Get selected leads
  const selectedLeads = useMemo(() => {
    const selectedRows = table.getSelectedRowModel().rows;
    return selectedRows.map((row) => row.original);
  }, [table, rowSelection]);

  // Handle row click
  const handleRowClick = useCallback(
    (lead: Lead, index: number) => {
      onSelectLead(lead);
      setFocusedRowIndex(index);
    },
    [onSelectLead]
  );

  // Clear selection
  const handleClearSelection = useCallback(() => {
    setRowSelection({});
  }, []);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // / to focus search
      if (e.key === "/" && !e.ctrlKey && !e.metaKey) {
        const target = e.target as HTMLElement;
        if (target.tagName !== "INPUT" && target.tagName !== "TEXTAREA") {
          e.preventDefault();
          onSearchFocus?.();
          return;
        }
      }

      // Skip if typing in input/textarea
      const target = e.target as HTMLElement;
      if (target.tagName === "INPUT" || target.tagName === "TEXTAREA") {
        return;
      }

      // If focus is on table or no specific focus (for global shortcuts)
      const isTableFocused = tableContainerRef.current?.contains(document.activeElement);
      
      const rows = table.getRowModel().rows;
      if (rows.length === 0) return;

      switch (e.key) {
        // ✅ Phase 3: Vim-style navigation
        case "j":
        case "ArrowDown":
          e.preventDefault();
          if (focusedRowIndex === -1) {
            setFocusedRowIndex(0);
          } else {
            setFocusedRowIndex((prev) => Math.min(prev + 1, rows.length - 1));
          }
          break;
        case "k":
        case "ArrowUp":
          e.preventDefault();
          if (focusedRowIndex === -1) {
            setFocusedRowIndex(rows.length - 1);
          } else {
            setFocusedRowIndex((prev) => Math.max(prev - 1, 0));
          }
          break;
        case "Enter":
          e.preventDefault();
          if (focusedRowIndex >= 0 && focusedRowIndex < rows.length) {
            onSelectLead(rows[focusedRowIndex].original);
          }
          break;
        case " ":
          if (isTableFocused) {
            e.preventDefault();
            if (focusedRowIndex >= 0 && focusedRowIndex < rows.length) {
              rows[focusedRowIndex].toggleSelected();
            }
          }
          break;
        // ✅ Phase 3: 'e' to edit focused lead
        case "e":
          e.preventDefault();
          if (focusedRowIndex >= 0 && focusedRowIndex < rows.length) {
            onEditLead(rows[focusedRowIndex].original);
          }
          break;
        case "Escape":
          e.preventDefault();
          handleClearSelection();
          setFocusedRowIndex(-1);
          break;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [table, focusedRowIndex, onSelectLead, onEditLead, onSearchFocus, handleClearSelection]);

  // Loading skeleton
  if (isLoading) {
    return (
      <div className="space-y-2 p-4">
        {Array.from({ length: 10 }).map((_, i) => (
          <Skeleton key={i} className="h-12 w-full" />
        ))}
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col" ref={tableContainerRef} tabIndex={0}>
      {/* Toolbar */}
      <div className="bg-muted/30 flex shrink-0 items-center justify-between border-b px-4 py-2">
        <span className="text-muted-foreground text-sm">
          {selectedLeads.length > 0 ? (
            <span className="text-primary font-medium">{selectedLeads.length} đã chọn</span>
          ) : (
            `${leads.length} lead`
          )}
        </span>
        <TableToolbar
          densityMode={densityMode}
          onDensityChange={setDensityMode}
          columnVisibility={columnVisibility}
          onColumnVisibilityChange={(columnId, isVisible) => {
            setColumnVisibility((prev) => ({
              ...prev,
              [columnId]: isVisible,
            }));
          }}
        />
      </div>

      {/* Table with Virtualization */}
      <div 
        ref={tableScrollRef}
        className="flex-1 overflow-x-auto overflow-y-auto"
      >
        {/* ✅ Phase 3: ARIA improvements for accessibility */}
        <Table 
          className="w-full"
          role="grid"
          aria-label="Danh sách lead"
          aria-rowcount={totalCount}
        >
          <TableHeader className="bg-muted/50 sticky top-0 z-10">
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    style={{ width: header.getSize() }}
                    className={cn(
                      "relative whitespace-nowrap",
                      densityConfig.headerHeight
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(header.column.columnDef.header, header.getContext())}
                    {/* Resize handle */}
                    {header.column.getCanResize() && (
                      <div
                        onMouseDown={header.getResizeHandler()}
                        onTouchStart={header.getResizeHandler()}
                        className={cn(
                          "absolute top-0 right-0 h-full w-1 cursor-col-resize select-none touch-none",
                          "hover:bg-primary/50 active:bg-primary",
                          header.column.getIsResizing() && "bg-primary"
                        )}
                      />
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={columns.length} className="h-64">
                  {/* ✅ Phase 3: Contextual empty state */}
                  <EmptyLeadsState
                    hasFilters={hasFilters}
                    searchQuery={searchQuery}
                    totalCount={totalCount}
                    onResetFilters={onResetFilters}
                    onCreateLead={onCreateLead}
                  />
                </TableCell>
              </TableRow>
            ) : (
              <>
                {/* Virtualization spacer - top */}
                {virtualRows.length > 0 && virtualRows[0].start > 0 && (
                  <tr style={{ height: virtualRows[0].start }} />
                )}
                {/* Virtualized rows */}
                {virtualRows.map((virtualRow) => {
                  const row = rows[virtualRow.index];
                  const isSelected = row.original.id === selectedLeadId;
                  const isFocused = virtualRow.index === focusedRowIndex;
                  return (
                    <TableRow
                      key={row.id}
                      data-index={virtualRow.index}
                      data-state={isSelected ? "selected" : undefined}
                      // ✅ Phase 3: ARIA attributes for accessibility
                      role="row"
                      aria-rowindex={(page - 1) * pageSize + virtualRow.index + 1}
                      aria-selected={isSelected}
                      tabIndex={isFocused ? 0 : -1}
                      onClick={() => handleRowClick(row.original, virtualRow.index)}
                      onDoubleClick={() => router.push(`/leads/${row.original.id}`)}
                      // ✅ Phase 1: Prefetch lead detail on hover for instant panel load
                      onMouseEnter={() => {
                        queryClient.prefetchQuery({
                          queryKey: leadsKeys.detail(row.original.id),
                          queryFn: () => leadsApi.getLead(row.original.id),
                          staleTime: 1000 * 30, // 30 seconds
                        });
                      }}
                      className={cn(
                        "cursor-pointer transition-all duration-150",
                        "border-b border-border/50", // Consistent row dividers
                        "hover:bg-muted/50",
                        // Zebra stripes for better readability
                        virtualRow.index % 2 === 1 && !isSelected && !isFocused && "bg-muted/40",
                        // ✅ Phase 2: Enhanced selected row - prominent background, left border, and subtle shadow
                        isSelected && "bg-primary/10 border-l-primary border-l-3 hover:bg-primary/15 shadow-sm",
                        // Focused row (keyboard nav) - visible highlight
                        isFocused && !isSelected && "bg-blue-50 dark:bg-blue-950/30 border-l-blue-500 border-l-2"
                      )}
                      style={{ 
                        height: virtualRow.size,
                        // ✅ Phase 2: Subtle scale on selection for visual pop
                        transform: isSelected ? 'scaleX(1.005)' : 'scaleX(1)',
                        transformOrigin: 'left center',
                      }}
                    >
                      {row.getVisibleCells().map((cell) => (
                        <TableCell
                          key={cell.id}
                          style={{ width: cell.column.getSize() }}
                          className={densityConfig.cellPadding}
                        >
                          {flexRender(cell.column.columnDef.cell, cell.getContext())}
                        </TableCell>
                      ))}
                    </TableRow>
                  );
                })}
                {/* Virtualization spacer - bottom */}
                {virtualRows.length > 0 && (
                  <tr style={{ height: rowVirtualizer.getTotalSize() - (virtualRows[virtualRows.length - 1]?.end || 0) }} />
                )}
              </>
            )}
          </TableBody>
        </Table>
      </div>

      {/* Footer with Pagination */}
      <div className="bg-muted/30 flex shrink-0 items-center justify-between border-t px-4 py-2">
        <div className="text-muted-foreground text-sm">
          Hiển thị {leads.length > 0 ? (page - 1) * pageSize + 1 : 0}-
          {Math.min(page * pageSize, totalCount)} / {totalCount.toLocaleString()} lead
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange?.(page - 1)}
            disabled={page <= 1}
            className="h-8 w-8 p-0"
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <span className="text-muted-foreground min-w-[100px] text-center text-sm">
            Trang {page} / {totalPages || 1}
          </span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange?.(page + 1)}
            disabled={page >= totalPages}
            className="h-8 w-8 p-0"
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Bulk Actions Bar */}
      {onBulkAssign && onBulkChangeStage && onBulkExport && onBulkDelete && (
        <BulkActionsBar
          selectedLeads={selectedLeads}
          onClearSelection={handleClearSelection}
          onBulkAssign={onBulkAssign}
          onBulkChangeStage={onBulkChangeStage}
          onBulkExport={onBulkExport}
          onBulkDelete={onBulkDelete}
        />
      )}
    </div>
  );
}

export default LeadsTable;

"use client"

/**
 * StatusBanner Component
 * 
 * Architecture Standard: Status-Driven UI (ADR-FE-003)
 * 
 * A reusable banner component that renders status-based messages
 * using the centralized status-config.
 * 
 * Usage:
 * <StatusBanner status={profile.status} module="admission" />
 */

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { 
  CheckCircle2, 
  Clock, 
  AlertCircle, 
  XCircle, 
  Info,
  Loader2
} from "lucide-react"
import { getStatusConfig, type StatusUIConfig } from "@/lib/status-config"
import { cn } from "@/lib/utils"

interface StatusBannerProps {
  /** Current status value from backend */
  status: string
  /** Module name for config lookup (default: "admission") */
  module?: "admission" | "lead"
  /** Optional custom message override */
  customMessage?: string
  /** Optional className for styling */
  className?: string
  /** Optional: Show loading state */
  isLoading?: boolean
}

const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  success: CheckCircle2,
  info: Clock,
  warning: AlertCircle,
  error: XCircle,
}

export function StatusBanner({ 
  status, 
  module = "admission",
  customMessage,
  className,
  isLoading = false
}: StatusBannerProps) {
  const config = getStatusConfig(status, module)
  
  // Don't render if banner should not be shown
  if (!config.showBanner) return null
  
  const Icon = ICON_MAP[config.bannerType ?? 'info'] ?? Info
  const message = customMessage ?? config.bannerMessage
  
  if (!message) return null
  
  return (
    <Alert 
      variant={config.bannerType === 'error' ? 'destructive' : 'default'}
      className={cn(
        "mb-6",
        config.bannerType === 'success' && "border-green-200 bg-green-50 text-green-800",
        config.bannerType === 'info' && "border-blue-200 bg-blue-50 text-blue-800",
        config.bannerType === 'warning' && "border-yellow-200 bg-yellow-50 text-yellow-800",
        className
      )}
    >
      {isLoading ? (
        <Loader2 className="h-4 w-4 animate-spin" />
      ) : (
        <Icon className="h-4 w-4" />
      )}
      <AlertTitle>{config.label}</AlertTitle>
      <AlertDescription>{message}</AlertDescription>
    </Alert>
  )
}

/**
 * AdmissionPendingBanner - Specialized for pending approval state
 * Shows when profile.status === 'submitted' or 'resubmitted'
 */
interface AdmissionPendingBannerProps {
  status: string
  className?: string
}

export function AdmissionPendingBanner({ status, className }: AdmissionPendingBannerProps) {
  const isPending = status === 'submitted' || status === 'resubmitted'
  
  if (!isPending) return null
  
  return (
    <Alert 
      className={cn(
        "mb-6 border-yellow-200 bg-yellow-50",
        className
      )}
    >
      <Clock className="h-4 w-4 text-yellow-600" />
      <AlertTitle className="text-yellow-800">Đang chờ duyệt</AlertTitle>
      <AlertDescription className="text-yellow-700">
        Hồ sơ của bạn đã được nộp và đang chờ phê duyệt từ bộ phận tuyển sinh.
        Bạn sẽ nhận được thông báo khi có kết quả.
      </AlertDescription>
    </Alert>
  )
}

/**
 * ValidationErrorsBanner - Shows backend validation errors
 */
interface ValidationErrorsBannerProps {
  errors: string[]
  className?: string
}

export function ValidationErrorsBanner({ errors, className }: ValidationErrorsBannerProps) {
  if (!errors || errors.length === 0) return null
  
  return (
    <Alert 
      variant="destructive"
      className={cn("mb-6", className)}
    >
      <AlertCircle className="h-4 w-4" />
      <AlertTitle>Hồ sơ chưa đủ điều kiện</AlertTitle>
      <AlertDescription>
        <ul className="list-disc pl-5 mt-2 space-y-1">
          {errors.map((err, idx) => (
            <li key={idx}>{err}</li>
          ))}
        </ul>
      </AlertDescription>
    </Alert>
  )
}

/**
 * useAdmissionConfigState Hook
 *
 * State machine for Admission Config navigation
 * Manages transitions between Welcome -> Phase1 -> Phase2 -> Phase3
 */

"use client";

import { useMemo } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import type {
  AdmissionConfigState,
  Phase1Step,
  Phase2Step,
  SelectionContext,
  Phase3View,
} from "@/app/(dashboard)/admin/admission-config/_components/shared/types";

// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Check if Phase 1 master data is complete
 */
async function checkPhase1Complete(): Promise<boolean> {
  try {
    // Check if all Phase 1 entities have at least one record
    // This is a simple check - can be enhanced with more robust validation
    const response = await fetch("/api/admin/offering-types?active_only=false");
    const data = await response.json();
    return data && data.length > 0;
  } catch {
    return false;
  }
}

/**
 * Check if Phase 2 program data exists
 */
async function checkPhase2Complete(): Promise<boolean> {
  try {
    const response = await fetch("/api/programs");
    const data = await response.json();
    return data && data.length > 0;
  } catch {
    return false;
  }
}

/**
 * Parse selection context from URL params
 */
function getContextFromParams(params: URLSearchParams): SelectionContext | null {
  const year = params.get("year");
  const major = params.get("major");
  const offering = params.get("offering");
  const academicInfo = params.get("academicInfo");

  if (!year || !major || !offering || !academicInfo) {
    return null;
  }

  return {
    academicYear: parseInt(year),
    majorProgramId: parseInt(major),
    offeringId: parseInt(offering),
    academicInfoId: parseInt(academicInfo),
  };
}

/**
 * Parse Phase 3 view from URL params
 */
function parsePhase3View(view: string | null, params: URLSearchParams): Phase3View {
  if (view === "matrix") {
    return { type: "matrix" };
  }

  if (view === "wizard") {
    const pathId = params.get("pathId");
    const wizardStep = params.get("wizardStep");

    return {
      type: "wizard",
      pathId: pathId ? parseInt(pathId) : undefined,
      wizardStep: wizardStep ? parseInt(wizardStep) : undefined,
    };
  }

  // Default to list view
  return { type: "list" };
}

/**
 * Convert state to URL string
 */
function stateToUrl(state: AdmissionConfigState): string {
  const base = "/admin/admission-config";

  if (state.type === "welcome") {
    return base;
  }

  if (state.type === "phase1") {
    return `${base}?phase=1&step=${state.step}`;
  }

  if (state.type === "phase2") {
    return `${base}?phase=2&step=${state.step}`;
  }

  if (state.type === "select-context") {
    return `${base}?phase=3`;
  }

  if (state.type === "phase3") {
    const ctx = state.context;
    const params = new URLSearchParams({
      phase: "3",
      year: ctx.academicYear.toString(),
      major: ctx.majorProgramId.toString(),
      offering: ctx.offeringId.toString(),
      academicInfo: ctx.academicInfoId.toString(),
      view: state.view.type,
    });

    if (state.view.type === "wizard") {
      if (state.view.pathId) {
        params.set("pathId", state.view.pathId.toString());
      }
      if (state.view.wizardStep !== undefined) {
        params.set("wizardStep", state.view.wizardStep.toString());
      }
    }

    return `${base}?${params.toString()}`;
  }

  return base;
}

// ============================================
// HOOK
// ============================================

export function useAdmissionConfigState() {
  const searchParams = useSearchParams();
  const router = useRouter();

  // Check Phase 1 completion
  const { data: hasPhase1Data, isLoading: checkingPhase1 } = useQuery({
    queryKey: ["phase1-check"],
    queryFn: checkPhase1Complete,
    staleTime: 30000, // 30 seconds
  });

  // Check Phase 2 completion
  const { data: hasPhase2Data, isLoading: checkingPhase2 } = useQuery({
    queryKey: ["phase2-check"],
    queryFn: checkPhase2Complete,
    staleTime: 30000,
    enabled: hasPhase1Data === true,
  });

  // Derive current state from URL params + data availability
  const currentState: AdmissionConfigState = useMemo(() => {
    const phase = searchParams.get("phase");
    const step = searchParams.get("step");
    const view = searchParams.get("view");

    // If checking data, stay in welcome state
    if (checkingPhase1 || checkingPhase2) {
      return { type: "welcome" };
    }

    // If Phase 1 URL param, show Phase 1
    if (phase === "1" && step) {
      return { type: "phase1", step: step as Phase1Step };
    }

    // If Phase 2 URL param, show Phase 2
    if (phase === "2" && step) {
      return { type: "phase2", step: step as Phase2Step };
    }

    // If Phase 3 URL param
    if (phase === "3") {
      const context = getContextFromParams(searchParams);
      if (!context) {
        return { type: "select-context" };
      }
      return {
        type: "phase3",
        context,
        view: parsePhase3View(view, searchParams),
      };
    }

    // If no phase param and no Phase 1 data, show welcome screen
    if (!phase && !hasPhase1Data) {
      return { type: "welcome" };
    }

    // If no phase param but has Phase 1 data, go to Phase 1
    if (!phase && hasPhase1Data) {
      return { type: "phase1", step: "units" };
    }

    // Default to welcome
    return { type: "welcome" };
  }, [searchParams, hasPhase1Data, hasPhase2Data, checkingPhase1, checkingPhase2]);

  // Navigate to a new state
  const navigate = (state: AdmissionConfigState, replace = false) => {
    const url = stateToUrl(state);
    if (replace) {
      router.replace(url);
    } else {
      router.push(url);
    }
  };

  return {
    currentState,
    navigate,
    isLoading: checkingPhase1 || checkingPhase2,
    hasPhase1Data: hasPhase1Data || false,
    hasPhase2Data: hasPhase2Data || false,
  };
}
